"use strict";exports.id=9177,exports.ids=[9177],exports.modules={59177:(a,b,c)=>{c.d(b,{n:()=>d});let d={powerpoint:[{moduleNumber:1,moduleSlug:"module-1",title:"Getting Started with PowerPoint",emoji:"\uD83C\uDFA8",description:"Learn the PowerPoint interface, create presentations, save files, and understand how slides work.",lessons:[{slug:"getting-started-with-powerpoint",title:"Getting Started with PowerPoint",description:"Learn your way around the PowerPoint interface including the Ribbon, Quick Access Toolbar, slide views, zoom controls, and Backstage view.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/k6pg4nZS6fA",practiceFiles:[],sections:[{heading:"PowerPoint Start Screen",blocks:[{type:"paragraph",text:"When you open PowerPoint, the Start Screen appears. From here you can create a new presentation, choose from templates, or open recent files."},{type:"paragraph",text:"Select Blank Presentation to open the PowerPoint editing environment and begin building your slides."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_interface.png",alt:"PowerPoint interface overview"}]},{heading:"Understanding the PowerPoint Interface",blocks:[{type:"paragraph",text:"Once a presentation opens, you will see the PowerPoint interface. The main workspace includes the Ribbon, slide navigation pane, slide editing area, and status bar."},{type:"paragraph",text:"The slide pane is where you build your presentation, while the navigation pane on the left allows you to organize and switch between slides."}]},{heading:"The Ribbon",blocks:[{type:"paragraph",text:"The Ribbon contains the commands you use to create and edit presentations. It is organized into tabs such as Home, Insert, Design, Transitions, Animations, Slide Show, Review, and View."},{type:"paragraph",text:"Each tab contains groups of related commands. For example, the Font group contains tools for formatting text."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_ribbon.png",alt:"PowerPoint ribbon tabs"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_small_arrow.png",alt:"Ribbon dialog launcher"}]},{heading:"Showing and Hiding the Ribbon",blocks:[{type:"paragraph",text:"You can control how much of the Ribbon is visible using the Ribbon Display Options in the top-right corner of PowerPoint."},{type:"paragraph",text:"Options include Auto-hide Ribbon, Show Tabs, and Show Tabs and Commands."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_ribbon_dropdown.png",alt:"Ribbon display options"}]},{heading:"Quick Access Toolbar",blocks:[{type:"paragraph",text:"The Quick Access Toolbar is located above the Ribbon and provides quick access to commonly used commands such as Save, Undo, Redo, and Start From Beginning."},{type:"paragraph",text:"You can customize the Quick Access Toolbar by clicking the drop-down arrow and selecting additional commands."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_quick_access.png",alt:"Quick access toolbar"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_quick_print_setup.png",alt:"Quick access customization menu"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_quick_print.png",alt:"Quick print added to quick access toolbar"}]},{heading:"Using the Tell Me Box",blocks:[{type:"paragraph",text:"The Tell Me box works like a search tool inside PowerPoint. You can type the name of a command or feature and PowerPoint will help you find it instantly."},{type:"paragraph",text:"This is especially useful when you are learning PowerPoint and do not know where certain tools are located."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_shapes.png",alt:"Using the Tell Me box to search commands"}]},{heading:"Ruler, Guides, and Gridlines",blocks:[{type:"paragraph",text:"PowerPoint includes layout tools to help align objects on your slides. These include the ruler, guides, and gridlines."},{type:"paragraph",text:"You can enable these tools from the View tab in the Ribbon under the Show group."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_view_tools.png",alt:"View tab ruler gridlines guides"}]},{heading:"Slide Views",blocks:[{type:"paragraph",text:"PowerPoint includes multiple slide views that change how your presentation is displayed. These include Normal view, Slide Sorter view, Reading view, and Slide Show view."},{type:"paragraph",text:"You can switch between these views using the view buttons in the bottom-right corner of the PowerPoint window."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_slide_view_command.png",alt:"Slide view buttons"}]},{heading:"Zoom Controls",blocks:[{type:"paragraph",text:"The Zoom slider located in the bottom-right corner allows you to zoom in or out of your slide."},{type:"paragraph",text:"This helps you adjust your workspace when working on detailed slide content."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_zoom_command.png",alt:"Zoom slider control"}]},{heading:"Backstage View",blocks:[{type:"paragraph",text:"Backstage view is accessed by clicking the File tab. It contains options for saving, printing, sharing, exporting, and managing your presentation."},{type:"paragraph",text:"This area also shows presentation information such as file size, slide count, and document properties."},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_file_tab.png",alt:"File tab backstage button"},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_backstage_view.png",alt:"PowerPoint backstage view"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Where are most PowerPoint commands organized?",options:["The status bar at the bottom of the screen","The Quick Access Toolbar above the slide","The Ribbon at the top of the screen","The slide navigation pane on the left"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open PowerPoint and create a blank presentation.","Change the Ribbon Display Options to Show Tabs.","Add New, Quick Print, and Spelling to the Quick Access Toolbar.","Use the Tell Me box to search for Shapes.","Insert a shape onto the slide.","Enable the Ruler from the View tab.","Zoom the presentation to 120%.","Return the Ribbon display to Show Tabs and Commands."]},{type:"image",src:"/images/powerpoint/module-1/getting-started/powerpoint_final_result.png",alt:"PowerPoint backstage view"}]},{slug:"understanding-onedrive-for-powerpoint",title:"Understanding OneDrive for PowerPoint",description:"Learn how to sign in to PowerPoint, connect your Microsoft account, and use OneDrive to save and access presentations from anywhere.",duration:"8 min",sections:[{heading:"What is OneDrive?",blocks:[{type:"paragraph",text:"OneDrive is Microsoft's cloud storage service. It allows you to store presentations and other files online so you can access them from any computer, tablet, or smartphone with an internet connection."},{type:"paragraph",text:"Using OneDrive makes it easy to save, edit, and share PowerPoint presentations while keeping your files protected and backed up."}]},{heading:"Signing in to PowerPoint",blocks:[{type:"paragraph",text:"To use OneDrive features, you need to sign in with a Microsoft account. Click the Sign in button in the upper-right corner of the PowerPoint window."},{type:"paragraph",text:"After signing in, PowerPoint connects to your OneDrive storage so you can save presentations online and access them across devices."},{type:"image",src:"/images/powerpoint/module-1/onedrive/powerpoint_sign_in.png",alt:"PowerPoint sign in button"}]},{heading:"Benefits of Using OneDrive",blocks:[{type:"paragraph",text:"Once you sign in, OneDrive provides several powerful advantages for managing presentations."},{type:"list",ordered:!1,items:["Access files anywhere from any device connected to the internet.","Back up presentations safely in the cloud.","Share files with coworkers or classmates.","Collaborate on presentations with multiple people at the same time."]}]},{heading:"Saving Presentations to OneDrive",blocks:[{type:"paragraph",text:"When you save a presentation, you can choose OneDrive as the storage location. This allows the file to sync automatically with your Microsoft account."},{type:"paragraph",text:"Click File → Save As and choose OneDrive instead of saving directly to your computer."},{type:"image",src:"/images/powerpoint/module-1/onedrive/powerpoint_onedrive.png",alt:"Saving a PowerPoint presentation to OneDrive"}]},{heading:"Opening Files from OneDrive",blocks:[{type:"paragraph",text:"Once your presentations are stored in OneDrive, you can open them from any device. Simply sign into PowerPoint and choose OneDrive when opening a file."},{type:"paragraph",text:"You can still save files locally to your computer, but OneDrive provides additional convenience and protection."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the benefit of saving a presentation to OneDrive?",options:["It automatically adds transitions to every slide","It compresses the file size to save disk space","You can access and share it from any device","It protects the presentation from being edited by anyone"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Sign in to PowerPoint using a Microsoft account.","Open the File menu and select Save As.","Choose OneDrive as the save location.","Save a presentation to OneDrive.","Locate your saved presentation inside your OneDrive account."]}]},{slug:"creating-and-opening-presentations",title:"Creating and Opening Presentations",description:"Learn how to create new PowerPoint presentations, use templates, open existing files, pin presentations, and understand Compatibility Mode.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/OX3vRazm4fw",practiceFiles:[{name:"Creating & Opening Presentations Practice File",url:"/practice/powerpoint/module-1/creating-opening/Powerpoint_CreatingOpening_Practice.ppt"}],sections:[{heading:"Creating a New Presentation",blocks:[{type:"paragraph",text:"PowerPoint files are called presentations. When starting a new project, you will usually begin with a blank presentation."},{type:"paragraph",text:"To create a new presentation, click the File tab to open Backstage view, then select New and choose Blank Presentation."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_file_tab.png",alt:"File tab in PowerPoint"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_backstage.png",alt:"New presentation screen"}]},{heading:"Using Templates",blocks:[{type:"paragraph",text:"Templates are predesigned presentations that allow you to quickly start a slideshow with built-in formatting, layouts, and color themes."},{type:"paragraph",text:"From the New screen in Backstage view, you can search for templates using the search bar or choose from suggested templates."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_new_template.png",alt:"PowerPoint template selection screen"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_review_template.png",alt:"Template preview screen"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_new_template_create.png",alt:"Create presentation from template"}]},{heading:"Opening Existing Presentations",blocks:[{type:"paragraph",text:"You can open presentations that have already been saved on your computer or OneDrive."},{type:"paragraph",text:"Click File → Open to view recent files or browse your computer to locate a presentation."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_existing.png",alt:"Open presentations menu"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_existing_browse.png",alt:"Browse option in PowerPoint"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_doc_folder.png",alt:"Open dialog box"}]},{heading:"Pinning Presentations",blocks:[{type:"paragraph",text:"If you frequently use the same presentation, you can pin it to the Recent list so it stays easy to access."},{type:"paragraph",text:"Hover your mouse over a recent file and click the pushpin icon to pin the presentation."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_pin_present.png",alt:"Pinned presentation"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_unpin_present.png",alt:"Unpin presentation"}]},{heading:"Understanding Compatibility Mode",blocks:[{type:"paragraph",text:"If you open a presentation created in an older version of PowerPoint, it may open in Compatibility Mode."},{type:"paragraph",text:"Compatibility Mode disables certain newer features so the presentation remains compatible with older versions of PowerPoint."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_compatibility.png",alt:"PowerPoint compatibility mode"}]},{heading:"Converting a Presentation",blocks:[{type:"paragraph",text:"To access newer PowerPoint features, you can convert a presentation from Compatibility Mode to the latest file format."},{type:"paragraph",text:"Open Backstage view, click Convert, and save the presentation as the newer format."},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_convert_compat.png",alt:"Convert presentation command"},{type:"image",src:"/images/powerpoint/module-1/creating-opening/create_and_open_save_as.png",alt:"Save converted presentation"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a PowerPoint template?",options:["A blank slide with no formatting or placeholders","A slideshow that plays automatically without editing","A pre-designed presentation you can customize as a starting point","A file saved in read-only mode"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Create a new blank PowerPoint presentation.","Search for a template and create a presentation from it.","Open an existing presentation from your computer.","Pin a presentation in the Recent list.","Open a presentation in Compatibility Mode.","Convert the presentation to the latest PowerPoint format."]}]},{slug:"saving-presentations",title:"Saving Presentations",description:"Learn how to save PowerPoint presentations, change file types, export presentations, and recover unsaved work.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/iwecUGKmiyw",practiceFiles:[{name:"PowerPoint Saving Practice File",url:"/practice/powerpoint/module-1/saving/Powerpoint_Saving_Practice.pptx"}],sections:[{heading:"Saving a Presentation",blocks:[{type:"paragraph",text:"Saving protects your work and allows you to reopen your presentation later. You can save files to your computer or to OneDrive."},{type:"paragraph",text:"Click the File tab to open Backstage view and access the Save and Save As commands."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_file_tab.png",alt:"PowerPoint file tab"}]},{heading:"Using the Save Command",blocks:[{type:"paragraph",text:"The Save command stores the current presentation using the same file name and location."},{type:"paragraph",text:"If the presentation has never been saved before, PowerPoint will automatically open the Save As screen."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_command.png",alt:"Save command in PowerPoint"}]},{heading:"Using Save As",blocks:[{type:"paragraph",text:"Save As allows you to create a new version of a presentation or save it to a different location."},{type:"paragraph",text:"From the Save As screen you can choose to store the presentation on OneDrive, your computer, or another location."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_save_as.png",alt:"Save As screen"}]},{heading:"Entering a File Name",blocks:[{type:"paragraph",text:"When saving a presentation you must provide a file name. Use descriptive names so you can easily identify presentations later."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_filename_input.png",alt:"File name input field"},{type:"image",src:"/images/powerpoint/module-1/saving/saving_filename_input_change.png",alt:"Changing file name"}]},{heading:"Choosing a File Type",blocks:[{type:"paragraph",text:"PowerPoint allows you to save presentations in multiple file formats including PowerPoint Presentation (.pptx), PowerPoint Show, or PDF."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_file_type_save_as.png",alt:"File type dropdown"}]},{heading:"Exporting Presentations",blocks:[{type:"paragraph",text:"The Export section allows you to convert presentations into different formats such as PDF or video."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_change_file_type.png",alt:"Change file type export screen"},{type:"image",src:"/images/powerpoint/module-1/saving/saving_change_to_pdf.png",alt:"Export presentation as PDF"}]},{heading:"Sharing Presentations",blocks:[{type:"paragraph",text:"If a presentation is stored on OneDrive, you can share it directly with others from within PowerPoint."},{type:"paragraph",text:"You can invite people to view or edit the presentation by entering their email address."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_share.png",alt:"Share presentation window"},{type:"image",src:"/images/powerpoint/module-1/saving/saving_share_input.jpeg",alt:"Entering email to share presentation"}]},{heading:"Recovering Unsaved Presentations",blocks:[{type:"paragraph",text:"If PowerPoint closes unexpectedly, you may be able to recover work that was not saved."},{type:"paragraph",text:"Go to File → Info → Manage Presentation and choose Recover Unsaved Presentations."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_recover_unsaved.png",alt:"Recover unsaved presentations"}]},{heading:"Document Recovery",blocks:[{type:"paragraph",text:"When PowerPoint restarts after a crash, the Document Recovery pane may appear showing versions of your presentation that can be restored."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_doc_recovery.png",alt:"Document recovery pane"}]},{heading:"PowerPoint Save Options",blocks:[{type:"paragraph",text:"PowerPoint includes settings that control how presentations are saved. You can adjust AutoRecover settings and default save locations."},{type:"image",src:"/images/powerpoint/module-1/saving/saving_options.png",alt:"PowerPoint save options"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What should you do if you want to share a presentation that others cannot edit?",options:["Save it as a .pptx file and email it","Use the Share button to invite collaborators","Export it as a PDF","Mark it as Final in the Info pane"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open PowerPoint and create a new blank presentation.","Save the presentation to your computer using Save As.","Rename the presentation.","Export the presentation as a PDF.","Open the File tab and locate the Recover Unsaved Presentations option."]}]},{slug:"slide-basics",title:"Slide Basics",description:"Learn how to create slides, choose layouts, work with placeholders, duplicate and reorder slides, and apply design changes in PowerPoint.",duration:"14 min",videoUrl:"https://www.youtube.com/embed/TZfcVbKJs1E",practiceFiles:[{name:"PowerPoint Slide Basics Practice File",url:"/practice/powerpoint/module-1/slide-basics/Powerpoint_SlideBasics_Practice.pptx"}],sections:[{heading:"Understanding Slides",blocks:[{type:"paragraph",text:"PowerPoint presentations are built one slide at a time. Each slide acts like a page in your presentation, and together the slides tell your full story."},{type:"paragraph",text:"Most slides begin with placeholders. Placeholders are built-in boxes that make it easy to add titles, text, pictures, charts, tables, and other content without having to build the layout yourself."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_slide_placeholders.png",alt:"PowerPoint slide with placeholders"},{type:"paragraph",text:"Using placeholders helps keep slides organized and consistent. Instead of dragging random objects around the screen, PowerPoint gives you a structured starting point."}]},{heading:"Using the Slide Navigation Pane",blocks:[{type:"paragraph",text:"The Slide Navigation Pane appears on the left side of the PowerPoint window. It displays thumbnails of every slide in the presentation."},{type:"paragraph",text:"This pane allows you to jump between slides quickly, see the order of your presentation, and make changes to slide arrangement without leaving the main editing view."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_nav_pane.jpeg",alt:"PowerPoint slide navigation pane"},{type:"paragraph",text:"When a presentation begins to grow, the Navigation Pane becomes one of the most important tools for staying organized."}]},{heading:"Adding a New Slide",blocks:[{type:"paragraph",text:"To continue building a presentation, you will usually need to insert additional slides. PowerPoint makes this easy with the New Slide command on the Home tab."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_new_slide.png",alt:"New Slide command on Home tab"},{type:"paragraph",text:"Clicking the top half of the New Slide button inserts a new slide immediately. This is the fastest way to keep moving when you are building a presentation from scratch."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_quick_slide_add.png",alt:"Quick new slide insertion"},{type:"paragraph",text:"New slides usually appear directly below the currently selected slide in the Navigation Pane."}]},{heading:"Choosing the Right Slide Layout",blocks:[{type:"paragraph",text:"Not every slide should look the same. Some slides only need a title, while others may need text, pictures, or two side-by-side content areas."},{type:"paragraph",text:"That is where slide layouts come in. Layouts control how placeholders are arranged on the slide."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_choose_slide_layout.png",alt:"Choosing a slide layout"},{type:"paragraph",text:"One of the most common layouts is Title and Content. It gives you a title placeholder at the top and one large content area below."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_title_and_content.png",alt:"Title and Content layout example"},{type:"paragraph",text:"Choosing the correct layout early makes your slides easier to build and usually saves you from unnecessary resizing later."}]},{heading:"Changing the Layout of an Existing Slide",blocks:[{type:"paragraph",text:"Sometimes you create a slide and later realize it needs a different layout. Thankfully, you do not need to start over."},{type:"paragraph",text:"PowerPoint lets you change the layout of an existing slide using the Layout command on the Home tab."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_change_layout.png",alt:"Changing slide layout from Home tab"},{type:"paragraph",text:"For example, you may want to switch to a Blank slide if you want full control over where objects appear."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_blank_slide.png",alt:"Blank slide layout option"},{type:"paragraph",text:"Changing layouts is a clean way to reshape a slide without deleting it and rebuilding everything from scratch."}]},{heading:"Adding a Text Box",blocks:[{type:"paragraph",text:"Placeholders are useful, but sometimes you need more freedom. A text box allows you to place text exactly where you want it on the slide."},{type:"paragraph",text:"To insert one, go to the Insert tab and click Text Box."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_add_text_box.png",alt:"Text Box command on Insert tab"},{type:"paragraph",text:"After selecting the command, click and drag on the slide to draw the text box area."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_text_box_create.png",alt:"Drawing a text box on a slide"},{type:"paragraph",text:"Once the text box appears, you can type directly inside it and format it like any other text in PowerPoint."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_text_box_appear.png",alt:"Text box added to slide"}]},{heading:"Moving and Resizing Placeholders",blocks:[{type:"paragraph",text:"You are not locked into PowerPoint’s default object positions. Placeholders and text boxes can be moved and resized whenever needed."},{type:"paragraph",text:"To move an object, click its border and drag it to a new location."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_move_placeholder.png",alt:"Moving a placeholder on a slide"},{type:"paragraph",text:"To resize an object, drag one of the sizing handles on the corners or sides. Corner handles adjust both height and width, while side handles adjust only one dimension."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_resize_placeholder.png",alt:"Resizing a placeholder"},{type:"paragraph",text:"These adjustments help you improve spacing, balance your slide, and make room for other content."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_adjust_placeholder.png",alt:"Adjusted placeholder size and position"}]},{heading:"Duplicating Slides",blocks:[{type:"paragraph",text:"If you have a slide with a layout you want to reuse, duplicating it is much faster than rebuilding the entire slide from scratch."},{type:"paragraph",text:"To duplicate a slide, right-click the slide thumbnail in the Navigation Pane and choose Duplicate Slide."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_duplicate_slide.jpeg",alt:"Duplicate Slide command"},{type:"paragraph",text:"You can also copy and paste slides. This is useful when moving content between presentations or when you want even more control over placement."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_copy_slide.jpeg",alt:"Copying a slide thumbnail"},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_paste_appear.jpeg",alt:"Pasted slide appears in navigation pane"}]},{heading:"Reordering Slides",blocks:[{type:"paragraph",text:"As your presentation grows, you may decide that some slides belong earlier or later in the sequence."},{type:"paragraph",text:"To reorder slides, click and drag a slide thumbnail in the Navigation Pane. A horizontal insertion line shows where the slide will be placed."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_move_slide.jpeg",alt:"Dragging slide to new position"},{type:"paragraph",text:"Reordering slides is one of the easiest ways to improve the flow of your presentation without changing the content itself."}]},{heading:"Applying a Theme",blocks:[{type:"paragraph",text:"Themes give your presentation a consistent visual style by applying coordinated colors, fonts, and background styles across all slides."},{type:"paragraph",text:"To apply a theme, go to the Design tab and select one of the available theme thumbnails."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_select_theme.png",alt:"Selecting a theme from the Design tab"},{type:"paragraph",text:"Once applied, the theme updates the appearance of your presentation instantly."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_applied_theme.jpeg",alt:"Theme applied to presentation"}]},{heading:"Formatting the Background",blocks:[{type:"paragraph",text:"If you want to customize the appearance of a slide even more, you can modify the slide background."},{type:"paragraph",text:"Use the Format Background command to choose a solid fill, gradient, texture, or picture background."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_format_background.png",alt:"Format Background command"},{type:"paragraph",text:"You can then select the background fill style and choose a color or other formatting option."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_background_fill.png",alt:"Background fill options"},{type:"paragraph",text:"If you want the same background on every slide, click Apply to All."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_format_apply_to_all.jpeg",alt:"Apply background formatting to all slides"}]},{heading:"Changing Slide Size",blocks:[{type:"paragraph",text:"PowerPoint allows you to choose between Standard (4:3) and Widescreen (16:9) slide sizes."},{type:"paragraph",text:"Widescreen is the more modern format and is commonly used for classroom projectors, TVs, and online presentations."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_slide_size.png",alt:"Slide size options in PowerPoint"}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After adding slides, choosing layouts, inserting text, duplicating content, and applying theme changes, your presentation will start to look polished and organized."},{type:"paragraph",text:"The completed practice file gives a good example of how a simple presentation can become much more visually effective once these slide basics are applied."},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_final_result.png",alt:"Completed PowerPoint presentation example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a layout in PowerPoint?",options:["A theme that changes the fonts and colors of a presentation","A color palette used across all slides","A pre-arranged set of placeholders for content on a slide","A saved view that shows all slides at once"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Insert a new slide into the presentation.","Change the layout of one slide.","Add a text box to a blank slide.","Move or resize a placeholder.","Duplicate one of the existing slides.","Reorder a slide in the Navigation Pane.","Apply a theme to the presentation.","Change the background formatting and apply it to all slides."]},{type:"image",src:"/images/powerpoint/module-1/slide-basics/slide-basics_final_result.png",alt:"Final result for slide basics challenge"}]}],level:"Beginner",estimatedMinutes:43},{moduleNumber:2,moduleSlug:"module-2",title:"Working with Text",emoji:"\uD83D\uDCDD",description:"Learn how to edit slide content, format text, organize slides, and work with lists in PowerPoint.",lessons:[{slug:"powerpoint-text-basics",title:"PowerPoint Text Basics",description:"Learn how to select text, cut, copy, paste, drag text, and format text using the tools on the Home tab.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/F9RL0Lk5cmw",practiceFiles:[{name:"PowerPoint Text Basics Practice File",url:"/practice/powerpoint/module-2/text-basics/Powerpoint_TextBasics_Practice.pptx"}],sections:[{heading:"Selecting Text",blocks:[{type:"paragraph",text:"Before you can edit or move text in PowerPoint, you first need to select it. Selecting text allows you to copy it, delete it, format it, or move it to another location on the slide."},{type:"paragraph",text:"To select text, click next to the text you want to select, then click and drag your mouse across the words."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_select_text.png",alt:"Selecting text in a PowerPoint text box"},{type:"paragraph",text:"Once the text is highlighted, PowerPoint knows that any commands you choose will apply to that selection."}]},{heading:"Copying and Pasting Text",blocks:[{type:"paragraph",text:"Copying text allows you to duplicate information without removing the original content from the slide."},{type:"paragraph",text:"First select the text you want to copy. Then click the Copy command in the Clipboard group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_copy.png",alt:"Copy command on the PowerPoint ribbon"},{type:"paragraph",text:"Next place the insertion point where you want the copied text to appear and click the Paste command."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_paste_command.png",alt:"Paste command on the PowerPoint ribbon"},{type:"paragraph",text:"The copied text will appear in the new location while the original text remains unchanged."}]},{heading:"Cutting and Pasting Text",blocks:[{type:"paragraph",text:"If you want to move text instead of copying it, you can use the Cut command. Cutting removes the selected text and places it on the clipboard."},{type:"paragraph",text:"Select the text you want to move, then click the Cut command on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_cut.png",alt:"Cut command on the PowerPoint ribbon"},{type:"paragraph",text:"Place the insertion point where the text should appear, then click Paste."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_paste.png",alt:"Pasting text into a new position"},{type:"paragraph",text:"The text will appear in its new location and will be removed from its original position."}]},{heading:"Dragging and Dropping Text",blocks:[{type:"paragraph",text:"Another quick way to move text is by dragging and dropping it. This allows you to move text directly without using the Ribbon commands."},{type:"paragraph",text:"First select the text you want to move. Then click and drag the selected text to a new location within the text box."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_drag_select_text.png",alt:"Dragging selected text in PowerPoint"},{type:"paragraph",text:"When you release the mouse, the text will move to the new location."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_dragged_text.png",alt:"Text moved to a new location on the slide"}]},{heading:"Formatting Text",blocks:[{type:"paragraph",text:"Formatting text helps emphasize important information and makes slides easier to read."},{type:"paragraph",text:"The Home tab contains several tools for formatting text, including options for font style, font size, color, and alignment."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_ribbon_commands.png",alt:"Font and paragraph commands in the PowerPoint ribbon"},{type:"paragraph",text:"You can also apply styles such as bold, italic, or underline to highlight important information for your audience."}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After editing and formatting the text, the slide will appear more organized and easier to read."},{type:"paragraph",text:"The example below shows how the slide should look after rearranging the list and formatting the text."},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_final_result.jpeg",alt:"Completed PowerPoint slide example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How do you select all text in a text box in PowerPoint?",options:["Right-click the text box and choose Select All","Click the text box, then press Ctrl + A","Double-click the text box border","Go to Home → Select → Select All Text"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Select slide 4.","Move the text 'Lower blood pressure' so it appears between 'Companionship' and 'Social opportunities'.","Use either Cut and Paste or Drag and Drop.","Select the list of benefits and apply italics formatting.","Select the title 'Did You Know?' remove the bold formatting and change the font size to 36 pt."]},{type:"image",src:"/images/powerpoint/module-2/text-basics/text-basics_final_result.jpeg",alt:"Final result for the text basics challenge"}]},{slug:"powerpoint-lists",title:"PowerPoint Lists",description:"Learn how to create bulleted and numbered lists to organize information clearly on slides.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/hL5XQGFdmDo",practiceFiles:[{name:"Lists Practice File",url:"/practice/powerpoint/module-2/lists/Powerpoint_Lists_Practice.pptx"}],sections:[{heading:"Bulleted Lists",blocks:[{type:"paragraph",text:"Bulleted lists are commonly used in PowerPoint to organize information into clear and easy-to-read points."},{type:"paragraph",text:"To add bullets, select the text you want to format and click the Bullets command in the Paragraph group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullet_command.png",alt:"Bullets command in the PowerPoint ribbon"},{type:"paragraph",text:"You can also click the drop-down arrow next to the Bullets command to choose from different bullet styles."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullets_dropdown.png",alt:"Bullet style dropdown menu"}]},{heading:"Choosing a Bullet Style",blocks:[{type:"paragraph",text:"PowerPoint includes several built-in bullet styles such as circles, squares, arrows, and checkmarks."},{type:"paragraph",text:"Selecting a style immediately updates the appearance of the list."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullet_style.png",alt:"Selecting a bullet style in PowerPoint"}]},{heading:"Customizing Bullets",blocks:[{type:"paragraph",text:"If you want more control over the appearance of your bullets, you can open the Bullets and Numbering dialog box."},{type:"paragraph",text:"From here you can change the bullet style, adjust the size, or select a different color."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_bullets_and_numbering.png",alt:"Bullets and Numbering dialog box"},{type:"paragraph",text:"You can also click Customize to choose symbols or other bullet characters."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_symbol_dialog.png",alt:"Symbol dialog used for custom bullets"}]},{heading:"Numbered Lists",blocks:[{type:"paragraph",text:"Numbered lists are useful when presenting steps, instructions, or information that should appear in a specific order."},{type:"paragraph",text:"To apply numbering, select the text and click the Numbering command on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_numbering_command.png",alt:"Numbering command in PowerPoint"},{type:"paragraph",text:"Click the drop-down arrow next to the Numbering button to choose from different numbering formats."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_number_options.png",alt:"Numbered list formatting options"}]},{heading:"Continuing Numbering",blocks:[{type:"paragraph",text:"When you create numbered lists across multiple slides or sections, PowerPoint can continue numbering automatically."},{type:"paragraph",text:"You can adjust where numbering starts by opening the Bullets and Numbering dialog box and changing the Start At value."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_continued_numbering.png",alt:"Changing numbering start value"},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_continued_numbering_displayed.png",alt:"Numbering continued across a list"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After applying bullets or numbering and customizing the formatting, your slide will look more organized and easier for your audience to read."},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_final_result.png",alt:"Final result of formatted lists on a PowerPoint slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"When should you use a numbered list on a slide?",options:["When you want to add visual variety with different bullet symbols","When the order of items does not matter","When the order of items matters","When you have more than five items to list"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Select the slide that contains the agenda list.","Convert the list into a numbered list.","Change the numbering so the list starts at 5.","Customize the bullet style for another list on the slide."]},{type:"image",src:"/images/powerpoint/module-2/lists/powerpoint-lists_final_result.png",alt:"Final result for the lists challenge"}]},{slug:"indents-and-line-spacing",title:"Indents and Line Spacing",description:"Learn how to adjust paragraph indentation and spacing to improve slide readability.",duration:"11 min",videoUrl:"https://www.youtube.com/embed/fhLlISfmGqA",practiceFiles:[{name:"Indents and Line Spacing Practice File",url:"/practice/powerpoint/module-2/indents/Powerpoint_IndentsLineSpacing_Practice.pptx"}],sections:[{heading:"Why Indents and Spacing Matter",blocks:[{type:"paragraph",text:"Indentation and line spacing help organize text so information is easier for your audience to read."},{type:"paragraph",text:"Indentation creates hierarchy within lists and paragraphs, while line spacing controls the vertical distance between lines of text."}]},{heading:"Showing the Ruler",blocks:[{type:"paragraph",text:"The ruler provides visual controls that allow you to adjust indentation precisely."},{type:"paragraph",text:"If the ruler is not visible, go to the View tab and check the Ruler option."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_show_ruler.png",alt:"Turning on the ruler in PowerPoint"}]},{heading:"Understanding Indent Markers",blocks:[{type:"paragraph",text:"The ruler contains several markers that control how text is indented."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_first_line_marker.png",alt:"First line indent marker"},{type:"paragraph",text:"The first-line indent marker controls where the first line of a paragraph begins."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker.png",alt:"Hanging indent marker"},{type:"paragraph",text:"The hanging indent marker controls the indentation of every line except the first."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker.png",alt:"Left indent marker"},{type:"paragraph",text:"The left indent marker moves the entire paragraph inward."}]},{heading:"Adjusting Indentation",blocks:[{type:"paragraph",text:"You can adjust bullet alignment by dragging the indent markers on the ruler."},{type:"paragraph",text:"This allows you to control how far bullet points and text appear from the left side of the slide."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker_example.png",alt:"Example of adjusting the left indent marker"},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_left_indent_marker_example_dragged.png",alt:"Left indent marker dragged"}]},{heading:"Using Hanging Indents",blocks:[{type:"paragraph",text:"The hanging indent marker controls how lines wrap after the first line of text."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker_example.png",alt:"Hanging indent marker example"},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_hanging_indent_marker_example_dragged.png",alt:"Dragging the hanging indent marker"}]},{heading:"Creating Multilevel Lists",blocks:[{type:"paragraph",text:"Indentation can also be used to create multilevel lists that organize information into main topics and subtopics."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_list_multilevel.png",alt:"Multilevel bullet list example"}]},{heading:"Adjusting Line Spacing",blocks:[{type:"paragraph",text:"Line spacing controls how much vertical space appears between lines of text."},{type:"paragraph",text:"To change line spacing, select the text and click the Line Spacing button in the Paragraph group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_size.png",alt:"Line spacing menu"},{type:"paragraph",text:"You can select common spacing options such as 1.0, 1.5, or 2.0."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_example.png",alt:"Line spacing example"}]},{heading:"Using Line Spacing Options",blocks:[{type:"paragraph",text:"For more precise control, open Line Spacing Options from the dropdown menu."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_options.png",alt:"Line spacing options dialog box"},{type:"paragraph",text:"You can adjust spacing before and after paragraphs to improve readability."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_line_spacing_adjusted.png",alt:"Adjusted line spacing"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After adjusting indentation and line spacing, the slide will appear more organized and easier to read."},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_final_result.png",alt:"Completed PowerPoint slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does increasing line spacing do?",options:["Increases the font size of the selected text","Adds more space between lines of text, improving readability","Moves the text box higher on the slide","Changes the indent level of bullet points"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Navigate to the slide containing the agenda.","Select the bulleted list.","Change the line spacing using Line Spacing Options.","Show the ruler if it is not already visible.","Adjust the left indent marker to align the bullet points."]},{type:"image",src:"/images/powerpoint/module-2/indents/indents-spacing_final_result.png",alt:"Final result of the indents and spacing challenge"}]},{slug:"using-find-and-replace",title:"Using Find & Replace in PowerPoint",description:"Learn how to quickly locate text in your presentation and replace it with new content using the Find and Replace tools.",duration:"7 min",videoUrl:"https://www.youtube.com/embed/TEqzwdC4x58",practiceFiles:[{name:"Find and Replace Practice File",url:"/practice/powerpoint/module-2/find-replace/Powerpoint_FindReplace_Practice.pptx"}],sections:[{heading:"Finding Text",blocks:[{type:"paragraph",text:"The Find tool allows you to search for specific words or phrases within your presentation."},{type:"paragraph",text:"This is useful when working with presentations that contain many slides or repeated information."},{type:"paragraph",text:"To use Find, go to the Home tab and click the Find command in the Editing group."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_find_command.png",alt:"Find command in PowerPoint"},{type:"paragraph",text:"The Find dialog box will appear where you can enter the word or phrase you want to locate."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_find_next.png",alt:"Find dialog box in PowerPoint"}]},{heading:"Locating Text",blocks:[{type:"paragraph",text:"After entering the search text, click Find Next to move through the presentation and locate each occurrence."},{type:"paragraph",text:"When PowerPoint finds the text, it will highlight the matching word or phrase on the slide."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_text_found.jpeg",alt:"Highlighted search result in PowerPoint"}]},{heading:"Using Replace",blocks:[{type:"paragraph",text:"The Replace feature allows you to search for text and replace it with different text automatically."},{type:"paragraph",text:"This tool is especially useful when you need to update names, dates, or repeated information across multiple slides."},{type:"paragraph",text:"To open Replace, click the Replace command in the Editing group on the Home tab."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_command.png",alt:"Replace command in PowerPoint"},{type:"paragraph",text:"The Replace dialog box allows you to enter both the text you want to find and the text you want to replace it with."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_dialog.png",alt:"Replace dialog box"}]},{heading:"Replacing Text",blocks:[{type:"paragraph",text:"Once the text is found, you can click Replace to change the highlighted occurrence."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_execute.png",alt:"Replacing text in PowerPoint"},{type:"paragraph",text:"If you want PowerPoint to replace every occurrence of the text in the presentation, click Replace All."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_replace_finished.jpeg",alt:"PowerPoint confirmation after replacing text"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After replacing the text, the updated content will appear throughout the presentation."},{type:"paragraph",text:"This allows you to quickly update repeated information without manually editing each slide."},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_final_result.png",alt:"Completed slide after replacing text"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the main use of Replace in PowerPoint?",options:["To format all instances of a word with bold or italic","To delete a word or phrase from every slide","To swap one word or phrase for another throughout the whole presentation","To move text from one slide to another"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the presentation:"},{type:"list",ordered:!0,items:["Open the presentation.","Use the Find command to search for the text '2015-2016'.","Use Replace to change it to '2016-2017'.","Click Replace All to update every occurrence.","Confirm the changes when PowerPoint displays the replacement message."]},{type:"image",src:"/images/powerpoint/module-2/find-replace/find-replace_final_result.png",alt:"Final result of the Find and Replace challenge"}]}],level:"Beginner",estimatedMinutes:46},{moduleNumber:3,moduleSlug:"module-3",title:"Slide Design & Themes",emoji:"\uD83C\uDFA8",description:"Learn how to improve the visual appearance of your presentation using themes and layouts.",lessons:[{slug:"applying-themes",title:"Applying Themes",description:"Learn how to quickly change the design of your presentation using built-in PowerPoint themes.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/_gYShFl6i94",practiceFiles:[{name:"Applying Themes Practice File",url:"/practice/powerpoint/module-3/themes/Powerpoint_Themes_Practice.pptx"}],sections:[{heading:"What is a Theme?",blocks:[{type:"paragraph",text:"A theme is a predefined combination of colors, fonts, layouts, and visual effects that control the overall appearance of a presentation."},{type:"paragraph",text:"PowerPoint presentations use a theme by default. Even if you never choose one manually, the Office theme is already applied when you create a new presentation."},{type:"paragraph",text:"Applying a theme allows you to instantly change the design of every slide while keeping the presentation consistent and professional."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_example.png",alt:"Two slides showing different PowerPoint themes applied"}]},{heading:"Theme Elements",blocks:[{type:"paragraph",text:"Every PowerPoint theme includes a set of design elements that work together to control the appearance of your slides."},{type:"paragraph",text:"These elements ensure that colors, fonts, and design effects remain consistent throughout the entire presentation."},{type:"paragraph",text:"The three main theme elements are theme colors, theme fonts, and theme effects."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_theme_colors.png",alt:"Theme colors menu in PowerPoint"},{type:"paragraph",text:"Theme colors define the color palette used throughout the presentation."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_theme_fonts.png",alt:"Theme fonts shown in PowerPoint font menu"},{type:"paragraph",text:"Theme fonts determine the default fonts used for headings and body text."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_theme_effects.png",alt:"Theme effects and shape styles in PowerPoint"},{type:"paragraph",text:"Theme effects control the appearance of shapes, SmartArt graphics, and other design elements."}]},{heading:"Applying a Theme",blocks:[{type:"paragraph",text:"All themes in PowerPoint are located on the Design tab in the Themes group."},{type:"paragraph",text:"You can apply a theme at any time, and PowerPoint will automatically update every slide in the presentation."},{type:"paragraph",text:"To apply a theme, open the Design tab and locate the Themes group."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_more_themes.png",alt:"Themes group on the PowerPoint Design tab"},{type:"paragraph",text:"Click the More arrow to view the complete gallery of available themes."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_desired_themes.png",alt:"PowerPoint theme gallery"},{type:"paragraph",text:"Select the theme you want and it will immediately be applied to the entire presentation."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_applied_theme.png",alt:"Theme applied to PowerPoint presentation"}]},{heading:"Using Theme Variants",blocks:[{type:"paragraph",text:"After applying a theme, you can change the appearance of that theme by choosing a variant."},{type:"paragraph",text:"Variants adjust the color scheme while keeping the same overall theme layout and design."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_variant_theme.png",alt:"Theme variants options in PowerPoint"},{type:"paragraph",text:"This allows you to quickly explore different design options without changing the entire theme."}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After applying a theme and selecting a variant, your slides will have a consistent design and professional appearance."},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_final_result.jpeg",alt:"Final presentation with applied theme"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does applying a theme to a presentation do?",options:["Changes only the font used in the presentation","Adds animations to every slide automatically","Changes the overall visual design including colors, fonts, and backgrounds","Replaces all slide content with placeholder text"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Select the Design tab.","Open the Themes gallery.","Apply the Gallery theme.","Select a different theme variant."]},{type:"image",src:"/images/powerpoint/module-3/themes/applying-themes_final_result.jpeg",alt:"Final result after applying a theme"}]},{slug:"modifying-themes",title:"Modifying Themes",description:"Learn how to customize PowerPoint themes by changing theme colors, fonts, effects, and background styles.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/UH7Gzjd3rGA",practiceFiles:[{name:"Modifying Themes Practice File",url:"/practice/powerpoint/module-3/modifying/Powerpoint_ModifyingThemes_Practice.pptx"}],sections:[{heading:"Modifying PowerPoint Themes",blocks:[{type:"paragraph",text:"PowerPoint themes control the overall appearance of your presentation, including colors, fonts, and visual effects."},{type:"paragraph",text:"If you like the general design of a theme but want to adjust certain elements, you can modify the theme instead of choosing a completely different one."},{type:"paragraph",text:"You can change theme colors, fonts, effects, and background styles while keeping the overall layout of the theme."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_variant_dropdown.png",alt:"Variants dropdown menu in PowerPoint"}]},{heading:"Changing Theme Colors",blocks:[{type:"paragraph",text:"If you don't like the colors of a theme, you can quickly apply a different color set while keeping the rest of the theme unchanged."},{type:"paragraph",text:"Theme colors control the color palette used for text, shapes, charts, and other design elements in your presentation."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_variant_colors.png",alt:"Theme color options in PowerPoint"},{type:"paragraph",text:"To change theme colors, open the Design tab, click the Variants drop-down arrow, select Colors, and choose the desired color set."}]},{heading:"Customizing Theme Colors",blocks:[{type:"paragraph",text:"If none of the built-in color sets match your design needs, you can create your own custom theme colors."},{type:"paragraph",text:"Custom colors allow you to control the exact colors used for text backgrounds, accents, and hyperlinks."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_customize_colors.png",alt:"Customize theme colors dialog box"},{type:"paragraph",text:"Open Design → Variants → Colors → Customize Colors, then choose new colors and give your custom theme a name before saving it."}]},{heading:"Changing Theme Fonts",blocks:[{type:"paragraph",text:"Theme fonts define the default fonts used for headings and body text across the entire presentation."},{type:"paragraph",text:"Changing theme fonts helps keep text consistent throughout all slides."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_variant_font.png",alt:"Theme fonts menu in PowerPoint"},{type:"paragraph",text:"To change fonts, open the Design tab, click Variants, select Fonts, and choose a font pair from the list."}]},{heading:"Customizing Theme Fonts",blocks:[{type:"paragraph",text:"If you want to use specific fonts, you can create your own custom theme font combination."},{type:"paragraph",text:"This allows you to choose one font for headings and another for body text."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_customize_fonts.png",alt:"Customize fonts dialog box in PowerPoint"},{type:"paragraph",text:"Select Design → Variants → Fonts → Customize Fonts, choose the heading and body fonts, then save the custom font theme."}]},{heading:"Changing Theme Effects",blocks:[{type:"paragraph",text:"Theme effects control the appearance of shapes, SmartArt graphics, and other visual objects in your presentation."},{type:"paragraph",text:"Changing theme effects can adjust elements such as shadows, glows, reflections, and shape styles."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_theme_effects.jpeg",alt:"Theme effects options in PowerPoint"},{type:"paragraph",text:"To apply a different effect style, open the Design tab, click Variants, select Effects, and choose the desired effect."}]},{heading:"Changing Background Styles",blocks:[{type:"paragraph",text:"You can also change the background style of your slides to further customize the appearance of your presentation."},{type:"paragraph",text:"Background styles depend on the current theme and color settings."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_background_styles.png",alt:"Background styles options in PowerPoint"},{type:"paragraph",text:"Open Design → Variants → Background Styles and choose a new background. For additional options, select Format Background."}]},{heading:"Saving a Custom Theme",blocks:[{type:"paragraph",text:"After customizing colors, fonts, and effects, you can save your theme and reuse it in future presentations."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_save_current_theme.jpeg",alt:"Save current theme option in PowerPoint"},{type:"paragraph",text:"Open the Themes gallery on the Design tab and select Save Current Theme."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_save_dialog.png",alt:"Save theme dialog box"},{type:"paragraph",text:"Enter a name for the theme and click Save. The theme will appear in the Custom section of the theme gallery."}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After modifying theme colors, fonts, effects, and background styles, your presentation will have a customized and consistent design."},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_final_result.png",alt:"Final presentation after modifying theme"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which element of a theme controls the color palette used throughout the presentation?",options:["Theme effects","Theme fonts","Background styles","Theme colors"],correctIndex:3}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Change the theme colors.","Customize the fonts so the heading font is Garamond and the body font is Arial.","Change the background style.","Optional: Save your customized theme."]},{type:"image",src:"/images/powerpoint/module-3/modifying/modifying-themes_final_result.png",alt:"Final result after modifying a theme"}]},{slug:"slide-master-view",title:"Slide Master View",description:"Learn how to use Slide Master view to make global design changes, create custom layouts, manage placeholders, and keep an entire presentation consistent.",duration:"16 min",videoUrl:"https://www.youtube.com/embed/h6ARCTypPTg",practiceFiles:[{name:"Slide Master View Practice File",url:"/practice/powerpoint/module-3/slide-master-view/Powerpoint_SlideMaster_Practice.pptx"}],sections:[{heading:"What Slide Master View Does",blocks:[{type:"paragraph",text:"Slide Master view allows you to control the overall design and layout structure of an entire presentation. Instead of editing slides one by one, you can update the master and its layouts so that design changes appear everywhere they are used."},{type:"paragraph",text:"This is especially useful when you want consistent branding, repeated logos, matching fonts, and reusable slide layouts throughout a presentation."}]},{heading:"Opening Slide Master View",blocks:[{type:"paragraph",text:"To begin working with slide masters, go to the View tab and select Slide Master. PowerPoint will switch from the normal editing view into the master editing workspace."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_ribbon_view.png",alt:"View tab with Slide Master command in PowerPoint"},{type:"paragraph",text:"Once Slide Master view opens, the left pane will display the large master slide at the top and the related layouts below it."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slide_master_select.png",alt:"Slide Master selected in the left pane"}]},{heading:"Understanding the Master Slide and Layouts",blocks:[{type:"paragraph",text:"The top slide in Slide Master view is the master slide. It controls global elements such as theme fonts, background styling, and repeated objects like logos."},{type:"paragraph",text:"The smaller slides beneath it are layouts. Each layout controls the structure of a specific slide type such as title slides, content slides, or image-based slides."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slide_master.png",alt:"Slide Master view showing hierarchy"},{type:"paragraph",text:"When you apply a layout to a slide, that slide inherits all formatting and structure from that layout."}]},{heading:"Editing Master Text and Branding",blocks:[{type:"paragraph",text:"You can format text on the master or layouts just like regular slides, including font style, size, and alignment."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_text_formatting.png",alt:"Formatting text in Slide Master"},{type:"paragraph",text:"You can also insert logos or branding elements so they automatically appear on multiple slides."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_resize_move_logo.png",alt:"Logo placement"}]},{heading:"Using Theme Fonts in Slide Master",blocks:[{type:"paragraph",text:"Slide Master view works closely with themes. Changing theme fonts will update text across all layouts instantly."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_theme_font.png",alt:"Theme fonts"},{type:"paragraph",text:"This ensures consistency and helps maintain a professional appearance."}]},{heading:"Inserting and Managing Placeholders",blocks:[{type:"paragraph",text:"Placeholders define where content such as text, images, charts, and media will appear on a slide."},{type:"paragraph",text:"Use Insert Placeholder from the Slide Master tab to add placeholders to layouts."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_placeholders.png",alt:"Insert placeholder menu"},{type:"paragraph",text:"Once placed, you can resize and position placeholders to create structured layouts."}]},{heading:"Creating a Custom Layout",blocks:[{type:"paragraph",text:"You can create your own layouts to standardize how slides are structured across a presentation."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_ribbon.png",alt:"Slide Master ribbon"},{type:"paragraph",text:"Custom layouts are useful for things like product slides, team slides, or image-focused content."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_select_layout.png",alt:"Selecting layout"}]},{heading:"Renaming Layouts",blocks:[{type:"paragraph",text:"Renaming layouts makes them easier to identify and reuse later."},{type:"paragraph",text:"Click Rename and assign a meaningful name such as Product Slide."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_rename_layout.png",alt:"Rename layout"},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_rename_dialog.png",alt:"Rename dialog"}]},{heading:"Showing and Hiding Master Elements",blocks:[{type:"paragraph",text:"You can control whether titles, footers, and background elements appear on specific layouts."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_titles_footers.png",alt:"Footer options"}]},{heading:"Applying Custom Layouts to Slides",blocks:[{type:"paragraph",text:"Apply layouts from the Home tab to instantly update slide structure and formatting."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_use_custom_layout.png",alt:"Applying layout"}]},{heading:"Saving the Theme",blocks:[{type:"paragraph",text:"Save your customized theme to reuse it in future presentations."},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_save_current_theme.png",alt:"Save theme"},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_save_theme.png",alt:"Save dialog"}]},{heading:"Closing Slide Master View",blocks:[{type:"paragraph",text:"Click Close Master View to return to the normal editing environment."}]},{heading:"Completed Presentation Example",blocks:[{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slides_updated.jpeg",alt:"Final slides"}]},{heading:"Pro Tip",blocks:[{type:"callout",variant:"success",text:"If you find yourself repeating the same formatting changes across multiple slides, switch to Slide Master view. One change there updates every slide automatically."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does Slide Master control?",options:["Only one slide","The entire presentation design","Animations only"],correctIndex:1},{type:"knowledge-check",question:"What is a layout?",options:["A color theme","A slide structure template","A font style"],correctIndex:1},{type:"knowledge-check",question:"Why are placeholders important?",options:["To lock slides","To define content areas","To animate slides"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Go to the View tab and open Slide Master view.","Select one of the layouts and rename it Product Slide.","Insert a Picture placeholder on a custom layout.","Move and resize the logo so it is aligned consistently on the layout.","Change the theme font used for the layout.","Return to Normal view.","Apply the custom Product Slide layout to an existing slide.","Save the current theme for future use."]},{type:"image",src:"/images/powerpoint/module-3/slide-master-view/slide-master-view_slides_updated.jpeg",alt:"Final result"}]}],level:"Beginner",estimatedMinutes:35},{moduleNumber:4,moduleSlug:"module-4",title:"Managing Slides & Presentations",emoji:"\uD83D\uDCC2",description:"Organize slides, manage presentation structure, print slides, and present to an audience.",lessons:[{slug:"managing-slides",title:"Managing Slides",description:"Learn how to organize slides using slide views, notes, and sections to manage large presentations more effectively.",duration:"11 min",videoUrl:"https://www.youtube.com/embed/UmOJXAr_riE",practiceFiles:[{name:"Managing Slides Practice File",url:"/practice/powerpoint/module-4/managing-slides/Powerpoint_ManagingSlides_Practice.pptx"}],sections:[{heading:"Slide Views",blocks:[{type:"paragraph",text:"PowerPoint includes several slide views that help you work with slides in different ways."},{type:"paragraph",text:"The slide view buttons are located in the bottom-right corner of the PowerPoint window."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_slide_views.png",alt:"Slide view buttons in PowerPoint"},{type:"paragraph",text:"Each view provides a different way to work with slides, including editing, organizing, and presenting your presentation."},{type:"paragraph",text:"As presentations grow larger, switching to the right view becomes more important. Instead of doing everything in one workspace, PowerPoint gives you different ways to focus on structure, content, notes, and delivery."}]},{heading:"Normal View",blocks:[{type:"paragraph",text:"Normal View is the default editing view used when creating and editing slides."},{type:"paragraph",text:"This view displays the current slide in the center, slide thumbnails on the left, and the notes pane below the slide."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_normal_view.png",alt:"Normal view in PowerPoint"},{type:"paragraph",text:"You can also drag slides in the navigation pane to quickly change their order."},{type:"paragraph",text:"Normal View is best when you are actively building content, editing text, inserting media, and making detailed slide changes. It is the main work area most users spend the majority of their time in."}]},{heading:"Slide Sorter View",blocks:[{type:"paragraph",text:"Slide Sorter View displays all slides as thumbnails so you can easily rearrange them."},{type:"paragraph",text:"This view is helpful when organizing presentations with many slides."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_thumbnail.jpeg",alt:"Slide sorter view showing slide thumbnails"},{type:"paragraph",text:"To move a slide, simply click and drag it to a new position."},{type:"paragraph",text:"Slide Sorter View is especially useful when you want to look at the overall flow of a presentation. Instead of focusing on one slide at a time, you can step back and evaluate the sequence of ideas across the full deck."}]},{heading:"Reading View and Slide Show View",blocks:[{type:"paragraph",text:"Reading View shows the presentation in a window while still allowing access to PowerPoint tools."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_reading_view.png",alt:"Reading view in PowerPoint"},{type:"paragraph",text:"Slide Show View displays the presentation exactly as the audience will see it."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_slide_show_view.png",alt:"Slide show view in PowerPoint"},{type:"paragraph",text:"Reading View is useful when you want to preview slides without fully entering presentation mode. Slide Show View is better when you want to rehearse or present the deck as a finished product."}]},{heading:"Outline View",blocks:[{type:"paragraph",text:"Outline View displays the text from your slides in outline form."},{type:"paragraph",text:"This makes it easier to review or edit the text from multiple slides at once."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_outline_view.png",alt:"Outline view command"},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_outline_edit.png",alt:"Editing text in outline view"},{type:"paragraph",text:"Outline View is ideal when you want to focus on the presentation’s message rather than its design. It helps you see whether your slides are logically organized and whether the text communicates your ideas clearly."}]},{heading:"Adding Notes",blocks:[{type:"paragraph",text:"You can add notes to slides using the Notes pane below the slide."},{type:"paragraph",text:"Notes are often used as speaker notes to help presenters remember what to say."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_notes_pane.png",alt:"Opening the notes pane"},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_notes.png",alt:"Typing notes in the notes pane"},{type:"paragraph",text:"Speaker notes are not usually shown to the audience during a presentation, so they can include reminders, talking points, or extra detail that supports your delivery."}]},{heading:"Notes Page View",blocks:[{type:"paragraph",text:"You can also view notes in Notes Page view."},{type:"paragraph",text:"This view shows the slide at the top with a large area below it where you can edit notes."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_notes_page_view.png",alt:"Notes page view"},{type:"paragraph",text:"Notes Page View gives you more room to work with presenter notes than the standard Notes pane. This can be helpful when a slide needs more detailed speaking guidance."}]},{heading:"Creating Slide Sections",blocks:[{type:"paragraph",text:"When presentations contain many slides, sections can help organize them into groups."},{type:"paragraph",text:"To create a section, select a slide, click the Section command on the Home tab, and choose Add Section."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_add_section.png",alt:"Add section command"},{type:"paragraph",text:"A new Untitled Section will appear in the slide navigation pane."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_untitled_section.png",alt:"Untitled section in slide pane"},{type:"paragraph",text:"Sections are especially useful for large presentations because they break the deck into smaller parts. Instead of managing one long slide list, you can organize slides by topic, audience, or stage of the presentation."}]},{heading:"Renaming Sections",blocks:[{type:"paragraph",text:"You can rename a section to better describe the slides it contains."},{type:"paragraph",text:"Click the Section command and choose Rename Section."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_rename_section.png",alt:"Rename section command"},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_rename_dialog.png",alt:"Rename section dialog"},{type:"paragraph",text:"Clear section names make a presentation easier to navigate, especially when you revisit the file later or share it with another presenter."}]},{heading:"Collapsing and Removing Sections",blocks:[{type:"paragraph",text:"Sections can be collapsed in the slide navigation pane to hide slides inside them."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_collapse_section.png",alt:"Collapsed slide section"},{type:"paragraph",text:"If you no longer need a section, you can remove it using the Section command."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_remove_section.png",alt:"Remove section command"},{type:"paragraph",text:"Collapsing sections helps reduce clutter in the navigation pane so you can focus on the part of the presentation you are currently editing. Removing a section deletes the grouping, but it does not automatically delete the slides inside it."}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"After organizing slides into sections and adding notes, the presentation becomes easier to navigate and manage."},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_final_result.png",alt:"Completed slide organization"},{type:"paragraph",text:"A well-organized presentation saves time during editing, makes it easier to prepare for delivery, and helps you stay in control as your slide deck grows."}]},{heading:"Pro Tip",blocks:[{type:"callout",variant:"success",text:"When a presentation starts getting long, do not wait until the end to organize it. Add sections as you build so the file stays clean and manageable from the start."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which view is best for rearranging slides quickly?",options:["Reading View","Slide Sorter View","Notes Page View","Slide Show View"],correctIndex:1},{type:"knowledge-check",question:"What are slide notes mainly used for?",options:["Changing the design of a slide","Adding speaker reminders and talking points","Animating slide transitions","Creating new sections"],correctIndex:1},{type:"knowledge-check",question:"What is the main benefit of using sections?",options:["They automatically animate slides","They print slides faster","They organize large presentations into groups","They replace slide layouts"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Create a section for the first slide and name it Introduction.","Create a section named Dogs beginning with the slide 'Man's Best Friend'.","Create a section named Cats & More beginning with the slide 'The Little Things in Life'.","Move the slide titled 'Pogo' so it appears in the Dogs section.","Switch to Outline View.","Add a note on slide 4 that says 'Move before slide 3 or delete'.","Switch back to Normal View."]},{type:"image",src:"/images/powerpoint/module-4/managing-slides/managing-slides_final_result.png",alt:"Final challenge result"}]},{slug:"printing-presentations",title:"Printing Presentations",description:"Learn how to print slides, handouts, and notes pages, and understand PowerPoint’s print settings for different presentation needs.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/fzuHplbKD9A",practiceFiles:[{name:"Printing Practice File",url:"/practice/powerpoint/module-4/printing/Powerpoint_Printing_Practice.pptx"}],sections:[{heading:"Accessing the Print Screen",blocks:[{type:"paragraph",text:"To print a presentation, open the File tab to enter Backstage view, then select Print. This opens the print workspace where you can preview and adjust all print settings."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_tab.png",alt:"Print option selected in PowerPoint File tab"},{type:"paragraph",text:"The Print screen shows a live preview of your slides on the right and printing options on the left."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_pane.png",alt:"Print pane with preview and settings"}]},{heading:"Understanding Print Settings",blocks:[{type:"paragraph",text:"PowerPoint provides several print settings that allow you to control how your presentation will appear when printed."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_options.png",alt:"Print settings options in PowerPoint"},{type:"paragraph",text:"You can choose the number of copies, select a printer, and decide whether to print all slides or a specific range."},{type:"paragraph",text:"Additional settings allow you to control slide layout, orientation, and whether the presentation prints in color or grayscale."}]},{heading:"Print Layout Types",blocks:[{type:"paragraph",text:"One of the most important decisions when printing is choosing the correct layout. PowerPoint offers several formats depending on how the presentation will be used."},{type:"paragraph",text:"Full Page Slides print one slide per page and are ideal for reviewing or sharing individual slides."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_full_page.png",alt:"Full page slide printing example"},{type:"paragraph",text:"Handouts allow you to print multiple slides per page. This is useful for audiences who want to follow along during a presentation."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_handout.png",alt:"Handout layout with multiple slides per page"},{type:"paragraph",text:"Notes Pages include each slide along with speaker notes beneath it. This is helpful when presenting or reviewing detailed talking points."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_notes_page.png",alt:"Notes page with slide and speaker notes"},{type:"paragraph",text:"Outline view prints only the text from your slides, making it useful for reviewing the structure of your presentation."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_outline.png",alt:"Outline view showing text-only slide content"},{type:"tip",text:"If you're presenting to an audience, print handouts with 3 slides per page so viewers can take notes during your presentation."}]},{heading:"Using Print Preview",blocks:[{type:"paragraph",text:"Before printing, always review the print preview to ensure your slides appear correctly. This helps avoid issues such as incorrect layouts or cut-off content."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_layout.png",alt:"Print preview showing slide layout"}]},{heading:"Printing Your Presentation",blocks:[{type:"paragraph",text:"Once your settings are configured, click the Print button to print your presentation."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_print_command.png",alt:"Print button in PowerPoint"}]},{heading:"Completed Output Example",blocks:[{type:"paragraph",text:"A properly printed presentation should match your selected layout and provide a clear, readable format for your audience."},{type:"image",src:"/images/powerpoint/module-4/printing/printing_final_result.png",alt:"Final printed presentation example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which print layout includes space for audience notes beside each slide?",options:["Full Page Slides","Notes Pages","Handouts","Outline"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Go to File and select Print.","Change the print layout to Handouts (3 slides per page).","Preview the print layout.","Switch to Notes Pages view.","Return to Handouts layout.","Print the presentation or export it as a PDF."]},{type:"image",src:"/images/powerpoint/module-4/printing/printing_final_result.png",alt:"Final printed handout example"}]},{slug:"presenting-your-slide-show",title:"Presenting Your Slide Show",description:"Learn how to deliver your presentation using Slide Show view, navigation tools, Presenter View, and interactive presentation features.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/7-2oM3AGHQM",practiceFiles:[{name:"Presenting Practice File",url:"/practice/powerpoint/module-4/presenting/PowerPoint_Presenting_Practice.pptx"}],sections:[{heading:"Starting a Slide Show",blocks:[{type:"paragraph",text:"To present your slides, you must enter Slide Show view. This mode displays your presentation in full screen, just as your audience will see it."},{type:"paragraph",text:"You can start a slide show in several ways depending on your situation."},{type:"list",items:["Press F5 to start from the beginning","Use the Slide Show tab → From Beginning","Use From Current Slide to start from your current position","Click the Slide Show button in the bottom-right corner"]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_start_command.png",alt:"Starting a slideshow in PowerPoint"},{type:"tip",text:"Use 'From Current Slide' when practicing or presenting updates so you don’t restart the entire presentation every time."}]},{heading:"Navigating Slides",blocks:[{type:"paragraph",text:"While presenting, you can move between slides using several methods."},{type:"list",items:["Click the mouse to move forward","Press the spacebar or arrow keys","Use on-screen navigation arrows"]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_advance_arrows.png",alt:"Slide navigation arrows"},{type:"paragraph",text:"Using multiple navigation methods ensures you can present smoothly whether using a keyboard, mouse, or remote clicker."}]},{heading:"Ending a Slide Show",blocks:[{type:"paragraph",text:"To end your presentation, you can press the Esc key at any time."},{type:"paragraph",text:"You can also right-click during the presentation and select End Show from the menu."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_end_show.png",alt:"End slideshow option"},{type:"paragraph",text:"At the end of the final slide, PowerPoint will display a message indicating the presentation has finished."}]},{heading:"Using Presentation Tools",blocks:[{type:"paragraph",text:"During a presentation, you can access additional tools by right-clicking or using the Slide Options menu."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_right_clicking.png",alt:"Right-click presentation menu"},{type:"paragraph",text:"These tools allow you to navigate slides, access settings, and control your presentation without exiting Slide Show view."}]},{heading:"Jumping Between Slides",blocks:[{type:"paragraph",text:"You can jump to any slide instantly by selecting 'See All Slides' during your presentation."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_thumbnail_versions.png",alt:"Slide thumbnails during presentation"},{type:"paragraph",text:"This is especially useful when answering audience questions or navigating a presentation out of order."}]},{heading:"Using Drawing Tools",blocks:[{type:"paragraph",text:"PowerPoint includes drawing tools that allow you to annotate slides during a presentation."},{type:"list",items:["Pen for writing","Highlighter for emphasis","Different colors for visibility"]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_pen_tool.png",alt:"Pen tool menu"},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_pen_tool_drawing.png",alt:"Drawing on slide"},{type:"tip",text:"Use drawing tools to emphasize key data points while speaking—it keeps your audience engaged and focused."}]},{heading:"Using the Laser Pointer",blocks:[{type:"paragraph",text:"The laser pointer allows you to highlight areas without permanently marking the slide."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_laser_pointer.png",alt:"Laser pointer option"},{type:"paragraph",text:"This is useful when you want to guide attention without adding annotations."}]},{heading:"Presenter View",blocks:[{type:"paragraph",text:"Presenter View allows you to see additional information while your audience only sees the slides."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_presenter_view.png",alt:"Presenter View"},{type:"paragraph",text:"Presenter View includes tools like a timer, slide previews, notes, and navigation controls."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_presenter_view_example.png",alt:"Presenter View interface labeled"},{type:"tip",text:"Always use Presenter View when available—it allows you to stay organized and deliver a more professional presentation."}]},{heading:"Setting Up a Slide Show",blocks:[{type:"paragraph",text:"PowerPoint allows you to configure how your presentation behaves using the Set Up Slide Show dialog box."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_setup_slideshow_ribbon.png",alt:"Set up slideshow button"},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_setup_show_dialog.png",alt:"Set up slideshow dialog"},{type:"paragraph",text:"You can choose presentation type, slide range, and how slides advance."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_advance_slide_timing.png",alt:"Slide timing settings"}]},{heading:"Completed Presentation Example",blocks:[{type:"paragraph",text:"A well-delivered presentation uses navigation tools, annotations, and Presenter View to guide the audience effectively."},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_final_result.jpeg",alt:"Final presentation example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which feature allows you to view notes and upcoming slides while the audience sees only the presentation?",options:["Slide Sorter View","Presenter View","Reading View","Outline View"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Start the slide show from the beginning.","Navigate to slide 8.","Use the pen tool to circle key data points.","Switch to Presenter View.","Use the laser pointer to highlight content.","End the slide show properly."]},{type:"image",src:"/images/powerpoint/module-4/presenting/presenting_final_result.jpeg",alt:"Final challenge result"}]}],level:"Beginner",estimatedMinutes:30},{moduleNumber:5,moduleSlug:"module-5",title:"Images & Objects",emoji:"\uD83D\uDDBC️",description:"Insert pictures, format images, work with shapes, and align objects to create visually engaging slides.",lessons:[{slug:"inserting-pictures",title:"Inserting Pictures",description:"Learn how to insert pictures from your computer, online sources, screenshots, and screen clippings, then resize and position them on your slides.",duration:"13 min",videoUrl:"https://www.youtube.com/embed/I-xlLwC4ERc",practiceFiles:[{name:"Inserting Pictures Practice File",url:"/practice/powerpoint/module-5/inserting-pictures/Powerpoint_InsertingPictures_Practice.pptx"}],sections:[{heading:"Why Pictures Matter",blocks:[{type:"paragraph",text:"Pictures play a critical role in making presentations more engaging and easier to understand. Instead of relying only on text, visuals help communicate ideas faster and more clearly."},{type:"paragraph",text:"In professional presentations, images are used to reinforce key points, illustrate concepts, and maintain audience attention."},{type:"callout",variant:"info",text:"A strong presentation doesn’t just tell—it shows. Use visuals to support your message, not replace it."}]},{heading:"Inserting a Picture from Your Computer",blocks:[{type:"paragraph",text:"To insert a picture saved on your computer, go to the Insert tab and select Pictures from the Images group."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_insert.png",alt:"Insert Pictures command"},{type:"paragraph",text:"This opens a file browser where you can locate and select your image."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_onedrive_pics.jpeg",alt:"Selecting an image from computer"},{type:"paragraph",text:"Once inserted, the image will appear directly on your slide and can be adjusted as needed."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_inserted_picture.png",alt:"Inserted image on slide"}]},{heading:"Using Content Placeholders",blocks:[{type:"paragraph",text:"Many slide layouts include content placeholders that allow you to insert images quickly without using the Ribbon."},{type:"paragraph",text:"Clicking the picture icon inside the placeholder lets you insert an image while keeping it aligned with the slide layout."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_placeholder_insert.png",alt:"Insert picture from placeholder"},{type:"paragraph",text:"You can also insert online images directly from the placeholder using the Online Pictures icon."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_placeholder.png",alt:"Online pictures placeholder icon"}]},{heading:"Inserting Online Pictures",blocks:[{type:"paragraph",text:"If you don’t already have an image saved, PowerPoint allows you to search for pictures online directly within the application."},{type:"paragraph",text:"Go to the Insert tab and select Online Pictures to begin searching."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_pics_ribbon.png",alt:"Online Pictures command"},{type:"paragraph",text:"A search window will appear where you can browse categories or type keywords to find specific images."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_pictures.jpeg",alt:"Online picture categories"},{type:"paragraph",text:"For example, searching for a topic like 'exercise' or 'healthy food' will return relevant images."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_pics_selection.jpeg",alt:"Search results"},{type:"paragraph",text:"Select the image you want and click Insert. PowerPoint will automatically place it on your slide."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_online_displayed.png",alt:"Inserted online picture"},{type:"tip",text:"The more specific your search term, the better your results."}]},{heading:"Resizing, Moving, and Rotating Pictures",blocks:[{type:"paragraph",text:"Once a picture is inserted, you can adjust it to fit your slide layout."},{type:"paragraph",text:"To move an image, click and drag it to a new position."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_move_picture.png",alt:"Moving image"},{type:"paragraph",text:"To resize an image, drag one of the corner handles. This keeps the image proportional."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_resize_picture.png",alt:"Resizing image"},{type:"paragraph",text:"To rotate an image, drag the circular rotation handle above the picture."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_rotate_picture.png",alt:"Rotating image"},{type:"callout",variant:"warning",text:"Avoid stretching images using side handles—this will distort the picture."}]},{heading:"Inserting Screenshots",blocks:[{type:"paragraph",text:"PowerPoint allows you to capture screenshots of open windows directly into your slide."},{type:"paragraph",text:"Go to Insert → Screenshot and choose from available windows."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screenshot.png",alt:"Screenshot command"},{type:"paragraph",text:"The selected window will be inserted onto your slide."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screenshot_displayed.png",alt:"Screenshot inserted"}]},{heading:"Using Screen Clipping",blocks:[{type:"paragraph",text:"Screen Clipping allows you to capture a specific portion of your screen instead of an entire window."},{type:"paragraph",text:"Select Screen Clipping, then click and drag to capture only the area you need."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screen_clipping.png",alt:"Screen clipping tool"},{type:"paragraph",text:"This is especially useful when you want to highlight a specific part of a website or application."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_screen_clipping_displayed.png",alt:"Screen clipping result"}]},{heading:"Completed Slide Examples",blocks:[{type:"paragraph",text:"By combining images, layout positioning, and resizing, you can create visually appealing slides."},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_final_result.jpeg",alt:"Final slide example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which tool allows you to capture only part of your screen?",options:["Screenshot","Screen Clipping","Online Pictures","Insert Object"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["Select the last slide.","Use the Online Pictures command to insert a picture of your favorite form of exercise.","Resize your picture so it takes up a majority of the slide without covering the title.","When you're finished, your slide should look something like this:"]},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_challenge_example.jpeg",alt:"Exercise slide result"},{type:"list",ordered:!0,start:6,items:["Insert a new slide with a Title Only layout.","In the Title placeholder, type Learn More at Fitness.gov.","Open https://odphp.health.gov/pcfsn in your browser, then insert a screen clipping of the website onto the slide you just created.","When you're finished, your slide should look something like this:"]},{type:"image",src:"/images/powerpoint/module-5/inserting-pictures/inserting-pictures_final_result.jpeg",alt:"Exercise slide result"}]},{slug:"formatting-pictures",title:"Formatting Pictures",description:"Learn how to enhance and customize images using picture styles, corrections, color adjustments, artistic effects, cropping, and compression tools in PowerPoint.",duration:"14 min",videoUrl:"https://www.youtube.com/embed/LD52XcAhL3s",practiceFiles:[{name:"Formatting Pictures Practice File",url:"/practice/powerpoint/module-5/formatting-pictures/Powerpoint_FormattingPictures_Practice.pptx"}],sections:[{heading:"Introduction to Formatting Pictures",blocks:[{type:"paragraph",text:"PowerPoint provides a wide range of tools that allow you to enhance and customize your images. These tools help you improve clarity, adjust colors, apply styles, and make your visuals more professional."},{type:"paragraph",text:"All picture formatting tools are located under the Picture Tools Format tab, which appears when you select an image."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_ribbon_command.png",alt:"Picture Tools Format tab"},{type:"callout",variant:"info",text:"Think of formatting as polishing your image—this is where your presentation starts to look professional instead of basic."}]},{heading:"Cropping Pictures",blocks:[{type:"paragraph",text:"Cropping allows you to remove unwanted parts of an image so you can focus on the most important content."},{type:"paragraph",text:"Select your image, go to the Format tab, and click Crop. Drag the black handles to trim the image."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_crop.png",alt:"Crop tool"},{type:"paragraph",text:"Once you’re done adjusting, click Crop again to apply the changes."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_image_adjustments.png",alt:"Cropped image result"}]},{heading:"Cropping to a Shape",blocks:[{type:"paragraph",text:"You can also crop images into shapes to better match your slide design."},{type:"paragraph",text:"Click the Crop dropdown, choose Crop to Shape, and select a shape like a rounded rectangle or circle."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_crop_to_shape.png",alt:"Crop to shape menu"},{type:"paragraph",text:"This instantly transforms your image into the selected shape."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_image_cropped_to_shape.png",alt:"Cropped to shape result"}]},{heading:"Adding Picture Borders",blocks:[{type:"paragraph",text:"Borders help your images stand out and match your presentation’s theme."},{type:"paragraph",text:"Select your image, click Picture Border, then choose a color, thickness, or style."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_picture_border.png",alt:"Picture border options"},{type:"paragraph",text:"You can customize the border to match your slide’s color scheme."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_picture_border_example.png",alt:"Border applied example"}]},{heading:"Image Corrections",blocks:[{type:"paragraph",text:"Corrections allow you to adjust brightness, contrast, and sharpness to improve image clarity."},{type:"paragraph",text:"Use this when your image looks too dark, too bright, or slightly blurry."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_corrections.png",alt:"Corrections menu"}]},{heading:"Adjusting Image Color",blocks:[{type:"paragraph",text:"The Color tool allows you to modify saturation, tone, and recolor your image."},{type:"paragraph",text:"This is useful when you want to match your image with your presentation’s theme or create a specific mood."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_color.png",alt:"Color adjustments"}]},{heading:"Applying Artistic Effects",blocks:[{type:"paragraph",text:"Artistic Effects allow you to transform your image into stylized versions like sketches, paintings, or blur effects."},{type:"paragraph",text:"These are best used sparingly to enhance visual storytelling without distracting your audience."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_artistic_effects.png",alt:"Artistic effects options"}]},{heading:"Using Picture Styles",blocks:[{type:"paragraph",text:"Picture Styles provide quick, pre-designed visual enhancements like frames, shadows, and reflections."},{type:"paragraph",text:"These styles can instantly upgrade the appearance of your image with just one click."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_picture_styles.png",alt:"Picture styles gallery"}]},{heading:"Compressing Pictures",blocks:[{type:"paragraph",text:"Large images can make your presentation file size too big, especially when sharing via email."},{type:"paragraph",text:"PowerPoint allows you to compress images to reduce file size by lowering resolution and removing cropped areas."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_compress_pictures.png",alt:"Compress pictures command"},{type:"paragraph",text:"For sharing presentations, choosing Email resolution creates the smallest file size."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_compress_email.png",alt:"Compression settings"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"By combining cropping, styles, borders, and adjustments, you can transform basic images into polished, professional visuals."},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_final_result.jpeg",alt:"Final formatted slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which tool helps reduce presentation file size?",options:["Picture Styles","Crop","Compress Pictures","Corrections"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["On slide 7, select the treadmill picture.","Crop the picture so it's slightly smaller and the treadmills take up a majority of the frame.","Change the style of the picture.","Apply a correction to the picture (for example, increase the brightness).","Compress your picture and choose Email as your target output.","When you're finished, your slide should look something like this:"]},{type:"image",src:"/images/powerpoint/module-5/formatting-pictures/formatting-pictures_final_result.jpeg",alt:"Final challenge result"}]},{slug:"shapes-in-powerpoint",title:"Shapes in PowerPoint",description:"Learn how to insert, format, resize, rotate, and customize shapes to make your slides more visually engaging and professional.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/lwBSCkmhwJA",practiceFiles:[{name:"Shapes in PowerPoint Practice File",url:"/practice/powerpoint/module-5/shapes/Powerpoint_Shapes_Practice.pptx"}],sections:[{heading:"Why Shapes Matter",blocks:[{type:"paragraph",text:"Shapes are more than decorative objects. In PowerPoint, they can be used to highlight important ideas, create visual emphasis, build diagrams, and make slides feel more polished and intentional."},{type:"paragraph",text:"A simple shape can help direct attention to key content or add personality to a slide. In this lesson, shapes are used to support a wellness presentation by turning plain slides into more visually appealing ones."},{type:"callout",variant:"info",text:"Shapes are one of the fastest ways to add structure and visual interest to a slide without needing outside graphics."}]},{heading:"Inserting a Shape",blocks:[{type:"paragraph",text:"To insert a shape, go to the Insert tab and click Shapes. PowerPoint includes lines, rectangles, arrows, stars, banners, callouts, and many other built-in shape options."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_select_shape.png",alt:"Shapes menu on the Insert tab in PowerPoint"},{type:"paragraph",text:"After selecting a shape, click and drag on the slide to draw it. The size and proportions of the shape will depend on how far you drag."},{type:"paragraph",text:"In this example, a sun shape is inserted onto the slide as a starting point for a visual callout."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_sizing_shape.png",alt:"A newly inserted sun shape on a PowerPoint slide"}]},{heading:"Resizing and Rotating Shapes",blocks:[{type:"paragraph",text:"Once a shape is inserted, you can resize it using the sizing handles around the border. Drag a corner handle to scale the shape larger or smaller."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_sizing_shape.png",alt:"Resizing a shape in PowerPoint"},{type:"paragraph",text:"To rotate a shape, drag the circular rotation handle above it. This allows you to angle the shape to better fit your design."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_rotate_shape.png",alt:"Rotating a shape in PowerPoint"},{type:"paragraph",text:"Resizing and rotating are basic but important adjustments. Even a simple angle change can make a shape look more dynamic and eye-catching."}]},{heading:"Using the Yellow Adjustment Handle",blocks:[{type:"paragraph",text:"Some shapes include one or more yellow adjustment handles. These allow you to modify the appearance of the shape itself."},{type:"paragraph",text:"For example, with the sun shape, the yellow handle changes the length and spacing of the rays. Other shapes may use this handle to alter corners, arrowheads, banner folds, or other design details."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_yellow_handles.png",alt:"Yellow adjustment handle on a shape in PowerPoint"},{type:"tip",text:"If a shape looks close to what you want but not quite right, check for a yellow handle before replacing it with a different shape."}]},{heading:"Applying Shape Styles",blocks:[{type:"paragraph",text:"PowerPoint includes built-in Shape Styles that instantly apply combinations of fill colors, outlines, and effects."},{type:"paragraph",text:"To use them, select the shape and go to the Drawing Tools Format tab. In the Shape Styles group, choose a preset style from the gallery."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_shape_style.png",alt:"Shape Styles gallery on the Format tab"},{type:"paragraph",text:"Applying a style is a quick way to improve the appearance of a shape without manually adjusting every setting."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_style_selected.png",alt:"A selected style applied to a sun shape"}]},{heading:"Changing Shape Fill",blocks:[{type:"paragraph",text:"Shape Fill controls the interior color or appearance of a shape. You can apply a solid fill, gradient, texture, picture fill, or choose No Fill."},{type:"paragraph",text:"To change the fill, select the shape, go to the Format tab, and click Shape Fill."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_select_color.png",alt:"Shape Fill color options in PowerPoint"},{type:"paragraph",text:"You can use one of the theme colors for consistency, or choose More Fill Colors for additional customization."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_more_fill_colors.png",alt:"More fill color options in PowerPoint"},{type:"paragraph",text:"In this example, changing the fill color helps transform the sun from a simple green shape into a brighter, more attention-grabbing graphic."}]},{heading:"Changing Shape Outline",blocks:[{type:"paragraph",text:"Shape Outline controls the border around a shape. You can change its color, thickness, dashes, or remove it entirely."},{type:"paragraph",text:"To change the outline, select the shape and click Shape Outline on the Format tab."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_formatting_options.png",alt:"Shape Outline menu with color and weight options"},{type:"paragraph",text:"Increasing the outline weight makes the border thicker and more visible. Removing the outline creates a cleaner, flatter look."},{type:"paragraph",text:"In this lesson, outline changes help define the shape and make it coordinate more effectively with the slide theme."}]},{heading:"Applying Shape Effects",blocks:[{type:"paragraph",text:"Shape Effects add visual enhancements such as shadows, glows, reflections, bevels, and 3-D rotation."},{type:"paragraph",text:"To apply an effect, select the shape, go to Shape Effects, and choose the effect you want to use."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_shape_effects.png",alt:"Shape Effects menu in PowerPoint"},{type:"paragraph",text:"Glow effects are especially useful when you want a shape to stand out from the background."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_shape_options.png",alt:"Format Shape pane showing glow options"},{type:"callout",variant:"warning",text:"Effects can make a shape pop, but too many effects at once can make a slide feel cluttered or dated. Use them on purpose."}]},{heading:"Editing and Changing a Shape",blocks:[{type:"paragraph",text:"You are not locked into the original shape you insert. PowerPoint allows you to change a shape into a different one while keeping much of its formatting."},{type:"paragraph",text:"Select the shape, go to Edit Shape, and choose Change Shape. Then select a new shape from the gallery."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_edit_shape.png",alt:"Edit Shape and Change Shape menu in PowerPoint"},{type:"paragraph",text:"This is useful when you like the color, size, and effects you already applied, but want the object to take on a different form."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_new_shape.png",alt:"A changed shape on the slide after using Change Shape"}]},{heading:"Adding Text to a Shape",blocks:[{type:"paragraph",text:"You can type directly inside most shapes. Simply select the shape and start typing, or right-click and choose Edit Text."},{type:"paragraph",text:"Once text is added, you can format it using the usual font, color, size, alignment, and WordArt options."},{type:"paragraph",text:"Adding text makes shapes especially useful for labels, callouts, banners, and highlighted messages on a slide."}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"After inserting a shape, adjusting its size, rotating it, changing its fill and outline, applying effects, and adding text, the slide becomes much more visually dynamic."},{type:"paragraph",text:"In this example, a plain shape evolves into a bold visual element that reinforces the message of the slide."},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_final_result.png",alt:"Completed slide showing a fully formatted shape with text"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which handle allows you to rotate a shape in PowerPoint?",options:["The yellow adjustment handle","The corner sizing handle","The circular rotation handle above the shape","The center point of the shape"],correctIndex:2},{type:"knowledge-check",question:"Which command lets you turn one shape into a different shape without starting over?",options:["Shape Fill","Shape Effects","Picture Border","Edit Shape → Change Shape"],correctIndex:3}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["Select slide 6.","Insert a Folded Corner shape onto the slide.","Rotate the shape so it is slightly angled.","Change the shape fill to a gold or yellow color.","Change the outline settings or remove the outline to improve the appearance.","Apply a shadow or glow effect to make the shape stand out.","Type a short wellness message inside the shape, such as Make stress relief a priority!","Optional: Use Edit Shape → Change Shape to transform the object into a different shape while keeping the formatting."]},{type:"image",src:"/images/powerpoint/module-5/shapes/shapes_final_result.png",alt:"Final challenge result for the shapes lesson"}]},{slug:"aligning-grouping-objects",title:"Aligning, Ordering, and Grouping Objects",description:"Learn how to align objects, distribute them evenly, group and ungroup items, control object layering, and rotate objects to create cleaner, more professional slides.",duration:"13 min",videoUrl:"https://www.youtube.com/embed/2GyjYgr-tSM",practiceFiles:[{name:"Aligning & Grouping Practice File",url:"/practice/powerpoint/module-5/aligning-grouping/Powerpoint_Aligning_Practice.pptx"}],sections:[{heading:"Why Object Arrangement Matters",blocks:[{type:"paragraph",text:"A slide can have great colors, strong images, and useful content, but still look messy if the objects are poorly arranged. In PowerPoint, pictures, shapes, and text boxes can be aligned, spaced, layered, grouped, and rotated so the slide looks intentional instead of random."},{type:"paragraph",text:"This lesson focuses on the arrangement tools that help you clean up your layouts. These tools are especially useful when working with multiple pictures or overlapping objects."},{type:"callout",variant:"info",text:"Design is not only about what you place on a slide. It is also about where you place it and how each object relates to the others."}]},{heading:"Aligning Objects",blocks:[{type:"paragraph",text:"When you move objects manually, PowerPoint displays alignment guides and spacing guides to help you line them up. These guides are useful, but they are not always enough when several objects need to line up perfectly."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_single_object.jpeg",alt:"Pictures on a slide with alignment guides visible"},{type:"paragraph",text:"To align two or more objects, first select them together. Hold the Shift key while clicking each object so PowerPoint knows they should be treated as a set."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_two_or_more.jpeg",alt:"Selecting multiple pictures in PowerPoint"},{type:"paragraph",text:"Once the objects are selected, open the Format tab and click the Align command. Then choose Align Selected Objects so PowerPoint aligns the objects relative to one another instead of to the slide itself."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_to_slide_option.png",alt:"Align Selected Objects option in PowerPoint"},{type:"paragraph",text:"After that, open the Align menu again and choose one of the six alignment options. These include Align Left, Align Center, Align Right, Align Top, Align Middle, and Align Bottom."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_bottom.png",alt:"Align Bottom option in the Align menu"},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_middle.png",alt:"Align Middle option in the Align menu"},{type:"paragraph",text:"In this example, the pictures are aligned so they share a consistent position. This immediately makes the slide feel cleaner and easier to read."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_aligned.jpeg",alt:"Objects aligned evenly on a slide"}]},{heading:"Aligning Objects to the Slide",blocks:[{type:"paragraph",text:"Sometimes you do not want objects aligned to each other. Instead, you want them aligned to a specific area of the slide, such as the top, middle, or bottom."},{type:"paragraph",text:"To do this, open the Align menu and switch from Align Selected Objects to Align to Slide."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_align_to_slide_checked.png",alt:"Align to Slide checked in the Align menu"},{type:"paragraph",text:"Once Align to Slide is selected, choose an alignment command such as Align Middle or Align Bottom. PowerPoint will position the selected objects relative to the slide itself."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_middle_aligned.jpeg",alt:"Objects aligned to the middle of the slide"},{type:"paragraph",text:"This is especially helpful when you want several objects to sit neatly across a slide without guessing at their vertical position."},{type:"tip",text:"Use Align Selected Objects when objects should line up with each other. Use Align to Slide when objects should line up with the slide."}]},{heading:"Distributing Objects Evenly",blocks:[{type:"paragraph",text:"Even after objects are aligned, they may still have uneven spacing between them. Distribution commands solve that problem by placing equal distance between each selected object."},{type:"paragraph",text:"If your objects are arranged in a row, use Distribute Horizontally. If they are arranged in a column, use Distribute Vertically."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_distribute_horizontal.png",alt:"Distribute Horizontally option in PowerPoint"},{type:"paragraph",text:"You can use distribution with either Align to Slide or Align Selected Objects, depending on whether the spacing should be based on the full slide or just the selected items."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_distributed.jpeg",alt:"Pictures distributed evenly across a slide"},{type:"paragraph",text:"This is one of the fastest ways to make a row of pictures or icons look professionally arranged."}]},{heading:"Grouping Objects",blocks:[{type:"paragraph",text:"Grouping lets you combine multiple objects into one object. After grouping, the objects can be moved or resized together instead of one at a time."},{type:"paragraph",text:"This is useful when you have finished arranging several objects and want them to stay together as a unit."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_group_ribbon.png",alt:"Group command on the PowerPoint Format tab"},{type:"paragraph",text:"Select the objects you want to group, then go to Format and choose Group. PowerPoint will place a single selection box around the entire set."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_grouped_objects.jpeg",alt:"Objects grouped into one selection box"},{type:"paragraph",text:"Once grouped, the pictures behave like one larger object. You can move them together, resize them together, and rotate them together."},{type:"callout",variant:"warning",text:"Placeholders cannot be grouped. If the Group command is disabled, one or more of the selected items may still be inside a placeholder."},{type:"paragraph",text:"If that happens, reinsert the images using the Pictures command on the Insert tab instead of the placeholder picture icon."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_pictures_command.png",alt:"Pictures command on the Insert tab"}]},{heading:"Ungrouping Objects",blocks:[{type:"paragraph",text:"If you need to edit one object inside a group, you can ungroup the set. This separates the objects so each item can be selected individually again."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_ungroup_command.png",alt:"Ungroup command in PowerPoint"},{type:"paragraph",text:"After ungrouping, the objects return to individual items and can be moved, resized, or reformatted independently."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_ungroupped.jpeg",alt:"Objects after being ungrouped"}]},{heading:"Ordering Objects and Understanding Layers",blocks:[{type:"paragraph",text:"When objects overlap on a slide, their order determines what appears in front and what appears behind. PowerPoint stacks objects in levels based on the order in which they were inserted."},{type:"paragraph",text:"In this example, a large arrow shape sits on top of the pictures. That means it is currently on a higher layer than the images behind it."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_single_object_overlap.jpeg",alt:"Large arrow shape overlapping pictures"},{type:"paragraph",text:"To change the order by one level, select the object and use Bring Forward or Send Backward on the Format tab."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_send_backward.png",alt:"Send Backward command on the Format tab"},{type:"paragraph",text:"This is useful when you want gradual control over layering and only need to move the object one step."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_objects_reordered.jpeg",alt:"Object reordered behind some slide content"}]},{heading:"Sending Objects to the Back and Using the Selection Pane",blocks:[{type:"paragraph",text:"If an object needs to move behind several other objects, it is usually faster to use the drop-down menu and select Send to Back instead of clicking Send Backward multiple times."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_send_to_back.png",alt:"Send to Back option in PowerPoint"},{type:"paragraph",text:"After sending the arrow backward, the pictures become more visible and the design begins to make more sense visually."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_reordered_send_back.jpeg",alt:"Arrow moved behind pictures on a slide"},{type:"paragraph",text:"When several objects overlap, selecting the right one can become difficult. The Selection Pane gives you a list of all objects on the slide so you can select and reorder them more precisely."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_selection_pane.jpeg",alt:"Selection Pane showing slide objects"},{type:"paragraph",text:"This is especially helpful in layered slides where clicking directly on the object is difficult."}]},{heading:"Rotating Objects",blocks:[{type:"paragraph",text:"In addition to aligning and ordering objects, PowerPoint also allows you to rotate them. Rotation is useful when an image or shape needs to face a different direction or better match the design of the slide."},{type:"paragraph",text:"Select the object, go to the Format tab, click Rotate, and choose the option you want. You can rotate left, rotate right, or flip the object horizontally or vertically."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_rotate.jpeg",alt:"Rotate menu in PowerPoint"},{type:"paragraph",text:"In this lesson, the food image is rotated so it better fits the final slide layout and makes the arrangement feel more dynamic."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_object_rotated.jpeg",alt:"Object rotated on the slide"}]},{heading:"Completed Slide Examples",blocks:[{type:"paragraph",text:"Once alignment, distribution, grouping, ordering, and rotation are all working together, the slide becomes much cleaner and easier to follow."},{type:"paragraph",text:"This example shows how orderly spacing and correct layering make the design feel more intentional and professional."},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_final_result.jpeg",alt:"Completed final slide after aligning and arranging objects"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which PowerPoint command spaces selected objects evenly across a slide?",options:["Align Middle","Distribute Horizontally","Send Backward","Group"],correctIndex:1},{type:"knowledge-check",question:"If the Group command is unavailable, what is a likely reason?",options:["The objects are too large","The file is read-only","One of the selected objects is inside a placeholder","You must rotate the objects first"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Download and open the practice presentation."},{type:"list",ordered:!0,items:["On the last slide, select the picture of the hamburger and Rotate Left 90\xb0.","Hold down the Shift key and select all three food pictures. Make sure you do not select the green diamonds.","Check Align to Slide under the Align command, then Align to Middle.","With the pictures still selected, Distribute Horizontally.","Select the first green diamond and send it behind the breakfast picture.","When you're finished, your slide should look like this:"]},{type:"image",src:"/images/powerpoint/module-5/aligning-grouping/alignment_final_result.jpeg",alt:"Final challenge result for aligning, ordering, and grouping objects"}]}],level:"Beginner",estimatedMinutes:50},{moduleNumber:6,moduleSlug:"module-6",title:"Animations & Multimedia",emoji:"\uD83C\uDFAC",description:"Apply slide transitions, animate text and objects, and embed audio and video into your presentation.",lessons:[{slug:"applying-transitions",title:"Applying Slide Transitions",description:"Learn how to add visual effects between slides, preview transitions, and control timing in PowerPoint.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/Ey1atEavZ-M",practiceFiles:[{name:"Applying Transitions Practice File",url:"/practice/powerpoint/module-6/transitions/Powerpoint_Transitions_Practice.pptx"}],sections:[{heading:"What are Slide Transitions?",blocks:[{type:"paragraph",text:"A slide transition is a visual effect that occurs when moving from one slide to the next during a presentation."},{type:"paragraph",text:"Transitions can be simple effects like fading between slides or more dynamic animations that add movement and energy to your presentation."},{type:"paragraph",text:"When used appropriately, transitions can give your presentation a polished and professional appearance."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_subtle.png",alt:"Examples of subtle transitions in PowerPoint"}]},{heading:"Transition Categories",blocks:[{type:"paragraph",text:"PowerPoint groups transitions into three categories: Subtle, Exciting, and Dynamic Content."},{type:"paragraph",text:"Subtle transitions use simple animations and are the most commonly used for professional presentations."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_subtle.png",alt:"Subtle transitions in PowerPoint"},{type:"paragraph",text:"Exciting transitions contain more complex animations. These can add visual interest but should be used sparingly."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_exciting.png",alt:"Exciting transitions in PowerPoint"},{type:"paragraph",text:"Dynamic Content transitions animate only slide elements instead of the entire slide, helping maintain visual continuity between slides."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_dynamic_content.png",alt:"Dynamic content transitions in PowerPoint"}]},{heading:"Applying a Transition",blocks:[{type:"paragraph",text:"Transitions are applied from the Transitions tab on the PowerPoint ribbon."},{type:"paragraph",text:"To apply a transition, first select the slide that you want the transition to appear on."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_desired_slide.png",alt:"Selecting a slide to apply a transition"},{type:"paragraph",text:"Open the Transitions tab and locate the Transition to This Slide group."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_more_dropdown.png",alt:"Transitions gallery in PowerPoint"},{type:"paragraph",text:"Click a transition to apply it to the selected slide. PowerPoint will automatically preview the transition."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_preview_ribbon.png",alt:"Preview transition button in PowerPoint"}]},{heading:"Previewing Transitions",blocks:[{type:"paragraph",text:"You can preview transitions at any time to see how they will appear during your slideshow."},{type:"paragraph",text:"Click the Preview button on the Transitions tab to watch the effect."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_preview_ribbon.png",alt:"Preview button on the transitions tab"},{type:"paragraph",text:"You can also preview the transition by clicking the Play Animations button beside a slide in the slide navigation pane."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_play_animations.png",alt:"Play animations preview in slide pane"}]},{heading:"Applying Transitions to All Slides",blocks:[{type:"paragraph",text:"If you want every slide to use the same transition, you can apply it to all slides at once."},{type:"paragraph",text:"After selecting a transition, click Apply to All in the Timing group."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_apply_to_all.png",alt:"Apply to All button in PowerPoint"}]},{heading:"Changing Transition Effects",blocks:[{type:"paragraph",text:"Some transitions allow you to customize the direction or style of the effect."},{type:"paragraph",text:"Click Effect Options to choose different variations such as From Left, From Right, From Top, or From Bottom."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_effect_options.png",alt:"Effect options menu for transitions"}]},{heading:"Adjusting Duration and Sound",blocks:[{type:"paragraph",text:"You can control how fast a transition plays by adjusting the duration setting."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_duration_timing.png",alt:"Transition duration setting"},{type:"paragraph",text:"PowerPoint also allows you to add sound effects to transitions. However, these should be used sparingly to avoid distracting the audience."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_add_sound.png",alt:"Transition sound options"}]},{heading:"Automatically Advancing Slides",blocks:[{type:"paragraph",text:"Normally slides advance when you click the mouse during a presentation."},{type:"paragraph",text:"You can configure slides to automatically advance after a set amount of time."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_after_timing.png",alt:"Automatic slide timing settings"},{type:"paragraph",text:"This feature is useful for presentations that run automatically, such as kiosk displays or trade show presentations."}]},{heading:"Removing Transitions",blocks:[{type:"paragraph",text:"If you decide you no longer want a transition on a slide, you can remove it easily."},{type:"paragraph",text:"Select the slide, open the Transitions tab, and choose None from the transition gallery."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_remove_transition.png",alt:"Removing a transition in PowerPoint"}]},{heading:"Completed Slideshow Example",blocks:[{type:"paragraph",text:"When transitions are applied consistently and used in moderation, they can improve the flow and professionalism of your presentation."},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_final_result.gif",alt:"Example slideshow with transitions applied"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a slide transition?",options:["An animation that moves text onto a slide","A sound effect that plays during a presentation","A visual effect that plays when moving from one slide to the next","A way to hide certain slides during a presentation"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice presentation:"},{type:"list",ordered:!0,items:["Open the practice presentation.","Apply the Push transition to the first slide.","Change the Effect Options to push From Right.","Change the transition duration to 2 seconds.","Set slides to automatically advance after 3 seconds.","Click Apply to All."]},{type:"image",src:"/images/powerpoint/module-6/transitions/transitions_final_result.gif",alt:"Final slideshow with transitions applied"}]},{slug:"animating-text-and-objects",title:"Animating Text and Objects",description:"Learn how to apply animation effects to text and objects, customize timing, use the Animation Pane, and control the order animations play.",duration:"11 min",videoUrl:"",practiceFiles:[{name:"Animations Practice File",url:"/practice/powerpoint/module-6/animations/Powerpoint_Animations_Practice.pptx"}],sections:[{heading:"What Are Animations?",blocks:[{type:"paragraph",text:"Animations in PowerPoint control how individual objects — text, images, and shapes — appear, move, or disappear on a slide."},{type:"paragraph",text:"Unlike transitions, which affect the entire slide, animations target specific objects. This makes them useful for revealing bullet points one at a time or drawing attention to a key graphic."},{type:"callout",variant:"info",text:"Use animations purposefully. Too many competing effects on a single slide can distract your audience instead of helping them follow along."}]},{heading:"Animation Categories",blocks:[{type:"paragraph",text:"PowerPoint organizes animations into four categories based on what they do to an object."},{type:"list",ordered:!1,items:["Entrance — controls how an object appears on the slide (e.g., Fade, Fly In, Appear).","Emphasis — draws attention to an object that is already visible (e.g., Pulse, Spin, Grow/Shrink).","Exit — controls how an object leaves the slide (e.g., Fade Out, Fly Out).","Motion Paths — moves an object along a defined path on the slide."]},{type:"image",src:"/images/powerpoint/module-6/animations/animations_categories.png",alt:"Four animation categories in PowerPoint"}]},{heading:"Applying an Animation",blocks:[{type:"paragraph",text:"To apply an animation, select an object on the slide and open the Animations tab."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_tab.png",alt:"Animations tab on the PowerPoint ribbon"},{type:"paragraph",text:"Click an effect from the Animation gallery. PowerPoint will immediately preview the animation on your slide."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_gallery.png",alt:"Animation gallery showing entrance, emphasis, and exit effects"},{type:"paragraph",text:"A number badge appears next to the object, indicating its animation order on the slide."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_number_badge.png",alt:"Animation number badge on a slide object"}]},{heading:"Effect Options",blocks:[{type:"paragraph",text:"Many animations offer additional variations through Effect Options. For example, a text box can fade in all at once, or paragraph by paragraph."},{type:"paragraph",text:"Click Effect Options on the Animations tab to see the available choices for the selected animation."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_effect_options.png",alt:"Effect Options menu for animations"}]},{heading:"The Animation Pane",blocks:[{type:"paragraph",text:"The Animation Pane gives you a detailed list of every animation on the current slide and the order in which they play."},{type:"paragraph",text:"To open it, click Animation Pane on the Animations tab."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_pane_open.png",alt:"Animation Pane open in PowerPoint"},{type:"paragraph",text:"You can drag items up or down in the pane to reorder them, and click the Play All button at the top to preview the full sequence."}]},{heading:"Start, Duration, and Delay",blocks:[{type:"paragraph",text:"Every animation has three timing settings that control when and how fast it plays."},{type:"list",ordered:!1,items:["Start — On Click (default), With Previous (plays at the same time as the animation before it), or After Previous (plays automatically after the previous animation ends).","Duration — how long the animation takes to complete.","Delay — how many seconds to wait before the animation begins."]},{type:"image",src:"/images/powerpoint/module-6/animations/animations_timing_controls.png",alt:"Start, Duration, and Delay timing controls on the Animations tab"},{type:"tip",text:"Set multiple animations to With Previous or After Previous so the sequence plays automatically without requiring extra clicks."}]},{heading:"Reordering Animations",blocks:[{type:"paragraph",text:"To change the order that animations play, select an animation in the Animation Pane and use the Move Earlier or Move Later buttons on the Animations tab."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_reorder.png",alt:"Move Earlier and Move Later buttons for reordering animations"}]},{heading:"Removing an Animation",blocks:[{type:"paragraph",text:"To remove an animation, select the object on the slide or select the animation entry in the Animation Pane, then press the Delete key."},{type:"paragraph",text:"You can also select the object and choose None from the Animation gallery to clear all animations from that object."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_remove.png",alt:"Removing an animation in PowerPoint"}]},{heading:"Completed Slide Example",blocks:[{type:"paragraph",text:"When animations are applied consistently and sequenced correctly, they guide the audience through your content in a controlled and professional way."},{type:"image",src:"/images/powerpoint/module-6/animations/animations_final_result.gif",alt:"Slide demonstrating an animated sequence"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which animation start setting causes an animation to play automatically after the previous one ends?",options:["On Click","With Previous","After Previous","Delayed Start"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Select the title text box on slide 2.","Apply the Fly In entrance animation.","Change the Effect Options so the text flies in From Left.","Select the content placeholder on the same slide and apply the Fade entrance animation.","Change the Start setting to After Previous so it plays automatically after the title.","Open the Animation Pane to verify the sequence looks correct.","Preview the animations by clicking Play All."]},{type:"image",src:"/images/powerpoint/module-6/animations/animations_final_result.gif",alt:"Final animated slide result"}]},{slug:"working-with-audio",title:"Working with Audio",description:"Learn how to insert audio files into your presentation, control playback settings, trim audio clips, and configure music to play across multiple slides.",duration:"8 min",videoUrl:"",practiceFiles:[{name:"Working with Audio Practice File",url:"/practice/powerpoint/module-6/audio/Powerpoint_Audio_Practice.pptx"}],sections:[{heading:"Why Add Audio to a Presentation?",blocks:[{type:"paragraph",text:"Audio can enhance a presentation by adding background music, narration, or short sound clips that reinforce your message."},{type:"paragraph",text:"Common uses include background music for kiosk displays, recorded narration for self-running presentations, and sound cues that accompany specific slides."},{type:"callout",variant:"warning",text:"Use audio with purpose. Background music or sounds that don't match your content can distract your audience."}]},{heading:"Inserting Audio from Your Computer",blocks:[{type:"paragraph",text:"To add an audio file, go to the Insert tab and select Audio, then choose Audio on My PC."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_insert_ribbon.png",alt:"Audio command on the Insert tab"},{type:"paragraph",text:"Browse to and select your audio file. PowerPoint supports common formats including MP3 and WAV."},{type:"paragraph",text:"After inserting, a speaker icon appears on the slide along with a small audio player bar."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_icon_on_slide.png",alt:"Audio speaker icon and player bar on a slide"}]},{heading:"The Audio Format and Playback Tabs",blocks:[{type:"paragraph",text:"When the audio icon is selected, two new tabs appear on the ribbon: Audio Format and Playback."},{type:"paragraph",text:"The Playback tab is where you configure most audio settings including start behavior, looping, and volume."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_playback_tab.png",alt:"Playback tab for audio in PowerPoint"}]},{heading:"Playback Settings",blocks:[{type:"paragraph",text:"The Start setting controls when audio begins playing. You can set it to In Click Sequence, Automatically, or When Clicked On."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_start_options.png",alt:"Audio start options in PowerPoint"},{type:"list",ordered:!1,items:["In Click Sequence — audio plays when you reach it during your click sequence.","Automatically — audio starts as soon as the slide appears.","When Clicked On — audio only plays when the audience clicks the icon."]},{type:"paragraph",text:"You can also enable Loop until Stopped to repeat the audio continuously, and Hide During Show to keep the speaker icon invisible during the presentation."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_loop_hide.png",alt:"Loop until Stopped and Hide During Show options"}]},{heading:"Playing Audio Across Slides",blocks:[{type:"paragraph",text:"By default, audio stops when you move to the next slide. To have music continue across multiple slides, check Play Across Slides in the Playback tab."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_play_across_slides.png",alt:"Play Across Slides option in PowerPoint"},{type:"tip",text:"Combine Play Across Slides with Hide During Show and Loop until Stopped for seamless background music throughout a presentation."}]},{heading:"Trimming Audio",blocks:[{type:"paragraph",text:"If an audio clip is longer than you need, you can trim it without leaving PowerPoint."},{type:"paragraph",text:"Click Trim Audio on the Playback tab. Drag the green start marker and red end marker to define the portion you want to keep."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_trim_dialog.png",alt:"Trim Audio dialog with start and end markers"},{type:"paragraph",text:"Click OK to apply the trim. The audio clip will now start and stop at the points you selected."}]},{heading:"Adjusting Volume",blocks:[{type:"paragraph",text:"Use the Volume button on the Playback tab to set the default playback level to Low, Medium, High, or Mute."},{type:"image",src:"/images/powerpoint/module-6/audio/audio_volume_control.png",alt:"Volume control on the Playback tab"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which setting keeps audio playing as you advance through multiple slides?",options:["Loop until Stopped","Hide During Show","Play Across Slides","When Clicked On"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Insert an audio file onto slide 1 using Audio on My PC.","Set the Start option to Automatically.","Enable Play Across Slides so the music continues as you advance slides.","Enable Hide During Show so the speaker icon is not visible during the presentation.","Enable Loop until Stopped.","Use Trim Audio to shorten the clip to approximately 30 seconds.","Preview your presentation from slide 1 to confirm the audio plays correctly."]}]},{slug:"working-with-video",title:"Working with Video",description:"Learn how to insert videos from your computer or online, control playback settings, trim clips, and format the video frame on your slides.",duration:"10 min",videoUrl:"",practiceFiles:[{name:"Working with Video Practice File",url:"/practice/powerpoint/module-6/video/Powerpoint_Video_Practice.pptx"}],sections:[{heading:"Why Embed Video in a Presentation?",blocks:[{type:"paragraph",text:"Videos can make a presentation far more engaging than static slides. A short clip can demonstrate a process, share a testimonial, or show a product in action."},{type:"paragraph",text:"Embedding video directly into your presentation keeps everything in one file, so you don't need to switch applications during a live presentation."},{type:"callout",variant:"info",text:"Keep embedded videos short. Long clips can increase file size significantly and may slow down your presentation."}]},{heading:"Inserting Video from Your Computer",blocks:[{type:"paragraph",text:"Go to the Insert tab, click Video, then select This Device."},{type:"image",src:"/images/powerpoint/module-6/video/video_insert_ribbon.png",alt:"Video command on the Insert tab"},{type:"paragraph",text:"Browse to your video file and click Insert. PowerPoint supports common formats including MP4, MOV, and AVI."},{type:"paragraph",text:"The video appears on the slide as a preview image with a playback bar beneath it."},{type:"image",src:"/images/powerpoint/module-6/video/video_on_slide.png",alt:"Inserted video on a slide with playback bar"}]},{heading:"Inserting an Online Video",blocks:[{type:"paragraph",text:"You can also embed a video from an online source such as YouTube without downloading it first."},{type:"paragraph",text:"Go to Insert → Video → Online Video. Paste the video URL into the search box and click Insert."},{type:"image",src:"/images/powerpoint/module-6/video/video_online_insert.png",alt:"Online Video dialog in PowerPoint"},{type:"callout",variant:"warning",text:"Online videos require an internet connection during your presentation. If connectivity is uncertain, use a locally saved video file instead."}]},{heading:"The Video Format and Playback Tabs",blocks:[{type:"paragraph",text:"When a video is selected, the Video Format and Playback tabs appear on the ribbon."},{type:"paragraph",text:"Video Format lets you apply styles, adjust borders, and crop the video frame. Playback controls how the video behaves during the presentation."},{type:"image",src:"/images/powerpoint/module-6/video/video_playback_tab.png",alt:"Playback tab for video in PowerPoint"}]},{heading:"Playback Settings",blocks:[{type:"paragraph",text:"The Start setting works the same as audio — In Click Sequence, Automatically, or When Clicked On."},{type:"paragraph",text:"Additional useful options include:"},{type:"list",ordered:!1,items:["Play Full Screen — expands the video to fill the entire screen during playback.","Hide While Not Playing — hides the video frame until it starts playing.","Loop until Stopped — repeats the video continuously.","Rewind after Playing — returns the video to the first frame when it ends."]},{type:"image",src:"/images/powerpoint/module-6/video/video_playback_options.png",alt:"Video playback options in PowerPoint"}]},{heading:"Trimming Video",blocks:[{type:"paragraph",text:"To use only part of a video, click Trim Video on the Playback tab."},{type:"image",src:"/images/powerpoint/module-6/video/video_trim_ribbon.png",alt:"Trim Video button on the Playback tab"},{type:"paragraph",text:"Drag the green start marker and the red end marker to define the clip you want to keep, then click OK."},{type:"image",src:"/images/powerpoint/module-6/video/video_trim_dialog.png",alt:"Trim Video dialog with start and end markers"},{type:"tip",text:"Trimming is non-destructive — the original video file is not modified. You can re-open the dialog and adjust the markers at any time."}]},{heading:"Adding a Video Poster Frame",blocks:[{type:"paragraph",text:"A poster frame is the still image shown on the video before it plays. By default, PowerPoint shows the first frame."},{type:"paragraph",text:"To set a custom poster frame, play the video to the frame you want, pause it, then click Poster Frame → Current Frame on the Video Format tab."},{type:"image",src:"/images/powerpoint/module-6/video/video_poster_frame.png",alt:"Poster Frame options on the Video Format tab"}]},{heading:"Formatting the Video Frame",blocks:[{type:"paragraph",text:"Just like images, videos can be styled with borders, shadows, and reflections using the Video Styles gallery on the Video Format tab."},{type:"image",src:"/images/powerpoint/module-6/video/video_styles_gallery.png",alt:"Video Styles gallery on the Video Format tab"},{type:"paragraph",text:"You can also resize and reposition the video frame on the slide the same way you would resize an image."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a video poster frame?",options:["The final frame that plays when the video ends","The still image displayed on the video before it plays","A picture inserted behind the video on the slide","A style applied to the video border"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["On slide 3, insert a video from your computer.","Resize and reposition the video so it fits neatly within the slide content area.","Set the Start option to Automatically.","Enable Rewind after Playing.","Use Trim Video to remove the first 5 seconds and last 5 seconds of the clip.","Apply a video style from the Video Format tab to give the frame a polished appearance.","Set a poster frame using a frame from inside the clip.","Preview the slide to confirm the video plays and rewinds correctly."]}]}],level:"Intermediate",estimatedMinutes:38},{moduleNumber:7,moduleSlug:"module-7",title:"Tables, Charts & SmartArt",emoji:"\uD83D\uDCCA",description:"Create and format tables, insert data-driven charts, and build professional diagrams using SmartArt.",lessons:[{slug:"inserting-tables",title:"Inserting Tables",description:"Learn how to create and insert tables in PowerPoint, add and remove rows and columns, merge cells, and apply table styles to organize data clearly.",duration:"10 min",videoUrl:"",practiceFiles:[{name:"Tables Practice File",url:"/practice/powerpoint/module-7/tables/Powerpoint_Tables_Practice.pptx"}],sections:[{heading:"When to Use Tables",blocks:[{type:"paragraph",text:"Tables are useful whenever you need to present structured data in rows and columns — schedules, comparison charts, pricing tiers, contact lists, and similar content."},{type:"paragraph",text:"A well-formatted table helps an audience absorb organized information quickly without requiring them to read through long paragraphs."},{type:"callout",variant:"info",text:"Keep tables simple. Avoid cramming so much data into a table that it becomes difficult to read at presentation size."}]},{heading:"Inserting a Table",blocks:[{type:"paragraph",text:"Go to the Insert tab and click Table. A grid appears where you can drag to choose the number of columns and rows you need."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_insert_grid.png",alt:"Table insertion grid on the Insert tab"},{type:"paragraph",text:"Release the mouse to insert the table. PowerPoint places it on the slide and opens the Table Design and Layout tabs."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_inserted.png",alt:"Blank table inserted on a slide"},{type:"tip",text:"If you need more rows or columns than the grid allows, select Insert Table from the Table menu to enter exact numbers."}]},{heading:"Entering and Navigating Table Content",blocks:[{type:"paragraph",text:"Click inside any cell to begin typing. Press Tab to move to the next cell, or Shift+Tab to move backwards."},{type:"paragraph",text:"Pressing Tab in the last cell of the last row automatically adds a new row to the table."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_data_entered.png",alt:"Table with data entered across multiple cells"}]},{heading:"Adding and Removing Rows and Columns",blocks:[{type:"paragraph",text:"To add a row or column, click inside the table near where you want to insert. Then open the Layout tab and use the Insert Above, Insert Below, Insert Left, or Insert Right buttons."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_insert_row_col.png",alt:"Insert row and column options on the Layout tab"},{type:"paragraph",text:"To delete a row or column, click inside it, then use the Delete Rows or Delete Columns button on the Layout tab."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_delete_row_col.png",alt:"Delete row and column options on the Layout tab"}]},{heading:"Merging and Splitting Cells",blocks:[{type:"paragraph",text:"Merging combines multiple adjacent cells into a single cell. This is commonly used for header rows that span all columns."},{type:"paragraph",text:"Select the cells you want to merge, then click Merge Cells on the Layout tab."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_merge_cells.png",alt:"Merge Cells button on the Layout tab"},{type:"paragraph",text:"To reverse a merge, select the merged cell and click Split Cells. Enter the number of rows and columns you want to split it into."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_split_cells.png",alt:"Split Cells dialog in PowerPoint"}]},{heading:"Resizing Columns and Rows",blocks:[{type:"paragraph",text:"You can resize columns and rows by dragging the border between cells. Position your cursor over the border until it changes to a resize arrow, then drag."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_resize_column.png",alt:"Resizing a table column by dragging"},{type:"paragraph",text:"For precise sizing, enter exact values in the Width and Height fields on the Layout tab."},{type:"paragraph",text:"Use Distribute Columns or Distribute Rows on the Layout tab to make all columns or rows the same size instantly."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_distribute.png",alt:"Distribute Rows and Columns options"}]},{heading:"Applying Table Styles",blocks:[{type:"paragraph",text:"The Table Design tab offers a gallery of pre-built styles that apply colors, shading, and borders matching your presentation's theme."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_style_gallery.png",alt:"Table Design style gallery in PowerPoint"},{type:"paragraph",text:"Use the Table Style Options checkboxes — such as Header Row, Banded Rows, and Total Row — to emphasize specific parts of the table."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_style_options.png",alt:"Table Style Options checkboxes"}]},{heading:"Aligning Text in Cells",blocks:[{type:"paragraph",text:"Text inside table cells can be aligned horizontally (left, center, right) and vertically (top, middle, bottom) using the alignment buttons on the Layout tab."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_text_alignment.png",alt:"Text alignment options on the Table Layout tab"},{type:"tip",text:"Center-aligning text both horizontally and vertically in header cells gives tables a cleaner, more polished look."}]},{heading:"Completed Table Example",blocks:[{type:"paragraph",text:"A formatted table with a styled header row, banded rows, and properly aligned content is much easier to read during a presentation than raw data."},{type:"image",src:"/images/powerpoint/module-7/tables/tables_final_result.png",alt:"Completed and formatted table on a slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What happens when you press Tab in the last cell of a table?",options:["The table is deselected","A new column is inserted to the right","The cursor moves back to the first cell","A new row is added at the bottom of the table"],correctIndex:3},{type:"knowledge-check",question:"Which Table Style Option emphasizes alternating rows with different shading?",options:["Header Row","Total Row","Banded Rows","First Column"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a new slide with a Title and Content layout.","Add the title: Quarterly Schedule.","Insert a table with 4 columns and 5 rows.","Type Quarter, Region, Sales Rep, and Status as the header row content.","Fill in at least three more rows with sample data.","Merge the top-left cell with the cell to its right to create a wide header.","Apply a table style that includes banded rows.","Distribute the columns evenly so they are all the same width.","When finished, your table should look organized and easy to read at presentation size."]},{type:"image",src:"/images/powerpoint/module-7/tables/tables_final_result.png",alt:"Completed table challenge result"}]},{slug:"inserting-charts",title:"Inserting Charts",description:"Learn how to insert charts into PowerPoint, choose the right chart type, edit chart data, and format your chart to communicate information visually.",duration:"11 min",videoUrl:"",practiceFiles:[{name:"Charts Practice File",url:"/practice/powerpoint/module-7/charts/Powerpoint_Charts_Practice.pptx"}],sections:[{heading:"Why Use Charts in Presentations?",blocks:[{type:"paragraph",text:"Charts transform raw numbers into visuals that are far easier to interpret at a glance. A bar chart comparing sales figures communicates instantly what a table of numbers takes time to process."},{type:"paragraph",text:"In professional presentations, charts are among the most effective tools for presenting data-driven arguments and trends."},{type:"callout",variant:"info",text:"Choose your chart type based on what you want to communicate, not just what looks interesting. The wrong chart type can mislead your audience."}]},{heading:"Common Chart Types",blocks:[{type:"paragraph",text:"PowerPoint includes many chart types. These are the most commonly used in business presentations:"},{type:"list",ordered:!1,items:["Column and Bar — compare values across categories. Column charts are vertical; bar charts are horizontal.","Line — show trends over time. Best when data has a clear sequence like months or years.","Pie — show proportions of a whole. Use only when you have a small number of categories.","Area — similar to line charts but filled with color, emphasizing volume."]},{type:"image",src:"/images/powerpoint/module-7/charts/charts_types_overview.png",alt:"Common chart types in PowerPoint"}]},{heading:"Inserting a Chart",blocks:[{type:"paragraph",text:"Go to the Insert tab and click Chart."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_insert_ribbon.png",alt:"Chart command on the Insert tab"},{type:"paragraph",text:"The Insert Chart dialog opens. Choose a chart type from the left panel and select a specific subtype from the top row, then click OK."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_insert_dialog.png",alt:"Insert Chart dialog with chart types"},{type:"paragraph",text:"A sample chart appears on your slide alongside a small Excel-style spreadsheet where you enter your actual data."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_data_sheet.png",alt:"Sample chart and data spreadsheet side by side"}]},{heading:"Editing Chart Data",blocks:[{type:"paragraph",text:"Replace the placeholder data in the spreadsheet with your own numbers. The chart on the slide updates automatically as you type."},{type:"paragraph",text:"Column headers become the chart's legend labels. Row headers become the category labels along the axis."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_data_entered.png",alt:"Updated chart data and resulting chart"},{type:"paragraph",text:"Close the spreadsheet when you're done. To edit the data again later, right-click the chart and select Edit Data."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_edit_data_menu.png",alt:"Edit Data option in the right-click menu"}]},{heading:"Chart Design and Format Tabs",blocks:[{type:"paragraph",text:"When a chart is selected, the Chart Design and Format tabs appear on the ribbon. These tabs contain all chart customization tools."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_design_tab.png",alt:"Chart Design tab on the PowerPoint ribbon"}]},{heading:"Applying a Chart Style",blocks:[{type:"paragraph",text:"The Chart Design tab includes a Chart Styles gallery with pre-built color and shading combinations that coordinate with your theme."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_style_gallery.png",alt:"Chart Styles gallery on the Chart Design tab"},{type:"paragraph",text:"Click Change Colors to select a different color palette for your chart's data series."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_change_colors.png",alt:"Change Colors options for a chart"}]},{heading:"Changing the Chart Layout",blocks:[{type:"paragraph",text:"Quick Layouts on the Chart Design tab let you change what elements appear on the chart — such as the title, legend, gridlines, and data labels."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_quick_layout.png",alt:"Quick Layout options on the Chart Design tab"},{type:"paragraph",text:"You can also use Add Chart Element to turn individual elements on or off, such as axis titles, data labels, and the legend."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_add_element.png",alt:"Add Chart Element menu"}]},{heading:"Changing the Chart Type",blocks:[{type:"paragraph",text:"If you decide that a different chart type would represent your data better, you don't have to start over."},{type:"paragraph",text:"Click Change Chart Type on the Chart Design tab, select the new type, and click OK. Your data transfers to the new chart format."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_change_type.png",alt:"Change Chart Type option on the Chart Design tab"}]},{heading:"Completed Chart Example",blocks:[{type:"paragraph",text:"A well-chosen chart type with a matching style and clear labels can make even complex data easy to understand at a glance."},{type:"image",src:"/images/powerpoint/module-7/charts/charts_final_result.png",alt:"Completed formatted chart on a slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which chart type is best suited for showing a trend over a period of time?",options:["Pie","Column","Line","Scatter"],correctIndex:2},{type:"knowledge-check",question:"How do you update the data in a chart after it has been inserted?",options:["Delete the chart and insert a new one","Right-click the chart and select Edit Data","Use the Format tab to enter new values","Double-click the chart legend"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a new slide with a Title and Content layout.","Add the title: Regional Sales — Q1.","Insert a Clustered Column chart.","Replace the placeholder data with four regions (North, South, East, West) and their sales figures.","Close the data spreadsheet.","Apply a chart style that uses your theme colors.","Use Add Chart Element to add data labels above each column.","Remove the chart legend since the data labels make it redundant.","Review the result and ensure the chart is clearly readable at slide size."]},{type:"image",src:"/images/powerpoint/module-7/charts/charts_final_result.png",alt:"Completed chart challenge result"}]},{slug:"using-smartart",title:"Using SmartArt",description:"Learn how to insert SmartArt graphics, choose the right layout for your content, add and edit text, and apply styles to create professional diagrams.",duration:"9 min",videoUrl:"",practiceFiles:[{name:"SmartArt Practice File",url:"/practice/powerpoint/module-7/smartart/Powerpoint_SmartArt_Practice.pptx"}],sections:[{heading:"What is SmartArt?",blocks:[{type:"paragraph",text:"SmartArt lets you transform a list of items into a professional-looking diagram without any design experience."},{type:"paragraph",text:"Instead of placing text and shapes manually, SmartArt handles the layout automatically. You just choose a structure and type your content."},{type:"callout",variant:"info",text:"SmartArt works best when your content has a clear relationship — a sequence of steps, a hierarchy, a cycle, or a set of interconnected ideas."}]},{heading:"SmartArt Categories",blocks:[{type:"paragraph",text:"PowerPoint organizes SmartArt layouts into categories based on the type of relationship they represent."},{type:"list",ordered:!1,items:["List — unordered or grouped items without a directional flow.","Process — steps in a sequence or workflow.","Cycle — a repeating process with no defined start or end.","Hierarchy — org charts and tree structures.","Relationship — connections and overlapping concepts, including Venn diagrams.","Matrix — how parts relate to a whole across two axes.","Pyramid — proportional or foundational relationships."]},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_categories.png",alt:"SmartArt layout categories in PowerPoint"}]},{heading:"Inserting SmartArt",blocks:[{type:"paragraph",text:"Go to the Insert tab and click SmartArt."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_insert_ribbon.png",alt:"SmartArt command on the Insert tab"},{type:"paragraph",text:"The Choose a SmartArt Graphic dialog opens. Select a category on the left, then pick a layout from the center panel. A preview and description appear on the right."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_choose_dialog.png",alt:"Choose a SmartArt Graphic dialog"},{type:"paragraph",text:"Click OK. The SmartArt graphic appears on your slide with placeholder text."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_inserted.png",alt:"SmartArt graphic inserted on a slide"}]},{heading:"Adding Text to SmartArt",blocks:[{type:"paragraph",text:"You can type directly into the shapes, or use the Text Pane on the left side of the graphic for easier editing."},{type:"paragraph",text:"To open the Text Pane, click the small arrow on the left edge of the SmartArt border or click Text Pane on the SmartArt Design tab."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_text_pane.png",alt:"SmartArt Text Pane open for editing"},{type:"paragraph",text:"Each bullet in the Text Pane corresponds to a shape in the graphic. Press Enter to add a new item and Tab to create a sub-level item."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_text_entered.png",alt:"SmartArt with text entered across all shapes"}]},{heading:"Adding and Removing Shapes",blocks:[{type:"paragraph",text:"SmartArt automatically sizes its shapes based on how many items you have. To add a shape, click Add Shape on the SmartArt Design tab."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_add_shape.png",alt:"Add Shape button on the SmartArt Design tab"},{type:"paragraph",text:"To remove a shape, click it in the graphic and press Delete."}]},{heading:"Changing the SmartArt Layout",blocks:[{type:"paragraph",text:"If the layout you chose doesn't quite fit your content, you can switch to a different one without retyping your text."},{type:"paragraph",text:"On the SmartArt Design tab, click a different layout in the Layouts gallery. Your content transfers to the new structure automatically."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_layout_gallery.png",alt:"SmartArt layout gallery on the Design tab"}]},{heading:"Applying SmartArt Styles and Colors",blocks:[{type:"paragraph",text:"The SmartArt Styles gallery offers pre-built visual treatments including flat, polished, and 3D looks that coordinate with your theme."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_styles_gallery.png",alt:"SmartArt Styles gallery"},{type:"paragraph",text:"Click Change Colors to choose a color variation that matches your presentation's palette."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_change_colors.png",alt:"Change Colors options for SmartArt"}]},{heading:"Converting a Bulleted List to SmartArt",blocks:[{type:"paragraph",text:"If you already have a bulleted text placeholder, you can convert it directly into SmartArt without starting over."},{type:"paragraph",text:"Select the text placeholder, right-click, and choose Convert to SmartArt. Then select a layout from the mini gallery that appears."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_convert_from_text.png",alt:"Convert to SmartArt option in the right-click menu"},{type:"tip",text:"Converting a list to SmartArt is one of the fastest ways to make a plain slide look more polished."}]},{heading:"Completed SmartArt Example",blocks:[{type:"paragraph",text:"A well-chosen SmartArt layout with consistent colors and readable text can replace several plain bullet-point slides."},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_final_result.png",alt:"Completed SmartArt graphic on a slide"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which SmartArt category is most appropriate for showing the steps in a workflow?",options:["Cycle","Hierarchy","Process","Matrix"],correctIndex:2},{type:"knowledge-check",question:"How do you add a new item to a SmartArt graphic using the Text Pane?",options:["Click Insert → Shape","Press Enter in the Text Pane to create a new bullet","Drag a shape from the Format tab","Type directly in the slide title"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Navigate to the slide with the bulleted list about the onboarding process.","Select the text placeholder containing the bulleted items.","Right-click and use Convert to SmartArt to turn it into a Process graphic.","Open the Text Pane and add one more step at the end.","Apply a SmartArt style that gives the shapes a polished, 3D appearance.","Use Change Colors to apply an accent color palette from your theme.","Resize the SmartArt graphic so it fills the lower portion of the slide without covering the title."]},{type:"image",src:"/images/powerpoint/module-7/smartart/smartart_final_result.png",alt:"Completed SmartArt challenge result"}]}],level:"Intermediate",estimatedMinutes:30},{moduleNumber:8,moduleSlug:"module-8",title:"Review & Presenting",emoji:"\uD83C\uDFA4",description:"Spell-check your work, collaborate with comments, deliver your presentation using Presenter View, and share or export your file.",lessons:[{slug:"checking-spelling-and-comments",title:"Checking Spelling & Using Comments",description:"Learn how to run a spell check, use the built-in thesaurus, add and review comments, and use Track Changes tools to collaborate and polish your presentation before delivery.",duration:"8 min",videoUrl:"",practiceFiles:[{name:"Review Practice File",url:"/practice/powerpoint/module-8/review/Powerpoint_Review_Practice.pptx"}],sections:[{heading:"Why Review Before You Present?",blocks:[{type:"paragraph",text:"Spelling errors and unclear slide content can undermine your credibility with an audience. A final review ensures your presentation is polished, accurate, and ready to deliver."},{type:"paragraph",text:"PowerPoint's Review tab contains all the tools you need to check spelling, look up synonyms, and collaborate with colleagues using comments."},{type:"image",src:"/images/powerpoint/module-8/review/review_tab_ribbon.png",alt:"Review tab on the PowerPoint ribbon"}]},{heading:"Running Spell Check",blocks:[{type:"paragraph",text:"PowerPoint checks spelling as you type, marking errors with a red wavy underline. You can also run a full spell check when you're ready to review everything at once."},{type:"paragraph",text:"Go to the Review tab and click Spelling. PowerPoint will scan your entire presentation and stop at each error."},{type:"image",src:"/images/powerpoint/module-8/review/review_spelling_ribbon.png",alt:"Spelling button on the Review tab"},{type:"paragraph",text:"The Spelling pane shows the flagged word along with suggested corrections. You can choose to change the word, ignore it once, or ignore all occurrences."},{type:"image",src:"/images/powerpoint/module-8/review/review_spelling_pane.png",alt:"Spelling pane with suggestions in PowerPoint"},{type:"tip",text:"Right-click any underlined word directly on the slide to see spelling suggestions without opening the full Spelling pane."}]},{heading:"Using the Thesaurus",blocks:[{type:"paragraph",text:"The Thesaurus helps you find more precise or varied word choices for your slide content."},{type:"paragraph",text:"Select a word on your slide, then click Thesaurus on the Review tab. The Thesaurus pane opens with a list of synonyms."},{type:"image",src:"/images/powerpoint/module-8/review/review_thesaurus_pane.png",alt:"Thesaurus pane showing synonyms for a selected word"},{type:"paragraph",text:"Hover over a synonym and click the arrow to insert it directly as a replacement for the selected word."}]},{heading:"Adding Comments",blocks:[{type:"paragraph",text:"Comments let you add notes to specific parts of a slide without affecting the slide content itself. This is useful for your own reminders or for collaborating with a colleague."},{type:"paragraph",text:"To add a comment, select the object or text you want to comment on, go to the Review tab, and click New Comment."},{type:"image",src:"/images/powerpoint/module-8/review/review_new_comment.png",alt:"New Comment button on the Review tab"},{type:"paragraph",text:"A comments pane opens where you can type your note. A small comment icon appears on the slide near the object you commented on."},{type:"image",src:"/images/powerpoint/module-8/review/review_comment_icon.png",alt:"Comment icon visible on a slide"}]},{heading:"Reviewing and Replying to Comments",blocks:[{type:"paragraph",text:"To read all comments in a presentation, open the Comments pane from the Review tab. Use the Previous and Next buttons to navigate between comments."},{type:"image",src:"/images/powerpoint/module-8/review/review_comments_pane.png",alt:"Comments pane showing all comments in the presentation"},{type:"paragraph",text:"You can reply to any comment by clicking inside it and typing your response. This creates a threaded conversation visible to anyone who opens the file."}]},{heading:"Resolving and Deleting Comments",blocks:[{type:"paragraph",text:"Once a comment has been addressed, you can resolve it to mark it as done without deleting it, or delete it entirely."},{type:"paragraph",text:"To delete a comment, select it in the Comments pane and click Delete on the Review tab. To delete all comments in the presentation, use the Delete All Comments in Presentation option."},{type:"image",src:"/images/powerpoint/module-8/review/review_delete_comment.png",alt:"Delete comment options on the Review tab"},{type:"callout",variant:"warning",text:"Always delete or resolve comments before delivering a presentation to a live audience. Comment icons visible on slides can distract your viewers."}]},{heading:"Comparing Presentations",blocks:[{type:"paragraph",text:"If a colleague has sent back a revised version of your file, the Compare tool lets you merge their changes into your version and review each one."},{type:"paragraph",text:"Click Compare on the Review tab, select the revised file, and PowerPoint highlights every difference between the two versions."},{type:"image",src:"/images/powerpoint/module-8/review/review_compare_ribbon.png",alt:"Compare button on the Review tab"},{type:"paragraph",text:"Use the Revisions pane to accept or reject individual changes, then click End Review when finished."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What should you do with all comments before presenting to a live audience?",options:["Print them as handouts","Convert them to footnotes","Delete or resolve them so they are not visible on slide","Move them to the Notes pane"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Run a full Spell Check from the Review tab and correct any errors found.","On slide 2, select the word in the title and use the Thesaurus to find and apply a stronger synonym.","Add a comment to slide 3 noting that the chart data needs to be updated.","Navigate to slide 4 and reply to the existing comment with a short confirmation.","Delete all comments from the presentation so it is ready to present."]}]},{slug:"presenting-your-slideshow",title:"Presenting Your Slideshow",description:"Learn how to start a slide show, navigate slides during a presentation, use Presenter View, draw on slides, and use the laser pointer to guide your audience.",duration:"10 min",videoUrl:"",practiceFiles:[{name:"Presenting Practice File",url:"/practice/powerpoint/module-8/presenting/Powerpoint_Presenting_Practice.pptx"}],sections:[{heading:"Starting a Slide Show",blocks:[{type:"paragraph",text:"When you're ready to present, PowerPoint offers several ways to start your slide show."},{type:"list",ordered:!1,items:["From Beginning — starts the presentation from the first slide (F5).","From Current Slide — starts from whichever slide is currently selected (Shift+F5).","Custom Slide Show — presents a subset of slides in a custom order."]},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_start_options.png",alt:"Slide Show start options on the Slide Show tab"},{type:"paragraph",text:"You can also click the Slide Show view button in the lower-right corner of the PowerPoint window to start from the current slide."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_view_button.png",alt:"Slide Show view button in the status bar"}]},{heading:"Navigating During a Presentation",blocks:[{type:"paragraph",text:"During a slide show, you can advance slides using the mouse, arrow keys, spacebar, or Page Down. Go back with the left arrow key or Page Up."},{type:"paragraph",text:"Right-click anywhere during the presentation to access a shortcut menu with navigation options, including Go to Slide, which lets you jump directly to any slide."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_right_click_menu.png",alt:"Right-click navigation menu during a slide show"},{type:"tip",text:"Press a slide number followed by Enter to jump directly to that slide (e.g., press 5 then Enter to go to slide 5)."}]},{heading:"Using Presenter View",blocks:[{type:"paragraph",text:"Presenter View is a professional presenting mode that shows your slide on the audience's screen while you see a private view with the current slide, upcoming slide, speaker notes, and a timer."},{type:"paragraph",text:"Enable it by checking Use Presenter View on the Slide Show tab before starting."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_presenter_view_toggle.png",alt:"Use Presenter View checkbox on the Slide Show tab"},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_presenter_view.png",alt:"Presenter View layout showing current slide, next slide, and speaker notes"},{type:"callout",variant:"info",text:"Presenter View requires two displays — your laptop screen and a projector or external monitor. It only works when PowerPoint detects a second screen."}]},{heading:"Speaker Notes",blocks:[{type:"paragraph",text:"Speaker notes appear in the Notes pane below each slide and are visible only to you in Presenter View. Use them to store reminders, talking points, or key statistics."},{type:"paragraph",text:"To add notes, click in the Notes pane at the bottom of Normal View and type your content."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_notes_pane.png",alt:"Notes pane below a slide in Normal View"},{type:"paragraph",text:"You can also print speaker notes as handouts using File → Print → Notes Pages."}]},{heading:"Using the Laser Pointer",blocks:[{type:"paragraph",text:"During a slide show, you can simulate a laser pointer to draw your audience's attention to specific areas of a slide."},{type:"paragraph",text:"Hold Ctrl and press the left mouse button to activate the laser pointer. Move the mouse to point to any area on the slide."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_laser_pointer.png",alt:"Laser pointer active during a presentation"}]},{heading:"Drawing on Slides During a Presentation",blocks:[{type:"paragraph",text:"PowerPoint's Pen and Highlighter tools let you draw or annotate on slides during a presentation."},{type:"paragraph",text:"Right-click during the slide show, choose Pointer Options, and then select Pen or Highlighter."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_pen_tool.png",alt:"Pointer Options menu with Pen and Highlighter options"},{type:"paragraph",text:"At the end of the show, PowerPoint asks if you want to keep your ink annotations. You can keep them on the slides or discard them."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_keep_ink.png",alt:"Dialog asking whether to keep ink annotations"},{type:"tip",text:"Press E to erase all pen marks on the current slide during a live presentation."}]},{heading:"Hiding Slides",blocks:[{type:"paragraph",text:"Sometimes you create slides with extra content that you only want to show if an audience member asks. Hidden slides stay in the file but are skipped automatically during the normal slide show."},{type:"paragraph",text:"Right-click a slide in the slide panel and select Hide Slide, or use the Hide Slide button on the Slide Show tab."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_hide_slide.png",alt:"Hide Slide option in the right-click menu"},{type:"paragraph",text:"Hidden slides are indicated with a strikethrough number in the slide panel. To jump to a hidden slide during a presentation, type its number and press Enter."}]},{heading:"Ending a Slide Show",blocks:[{type:"paragraph",text:"Press Escape at any time to exit the slide show and return to the Normal editing view."},{type:"paragraph",text:"If you have reached the last slide, a black end screen appears. Press Escape or click the screen to exit."},{type:"image",src:"/images/powerpoint/module-8/presenting/presenting_end_of_show.png",alt:"End of slide show black screen"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What keyboard shortcut starts a slide show from the beginning?",options:["Ctrl+P","F5","Shift+F5","Ctrl+F5"],correctIndex:1},{type:"knowledge-check",question:"What does Presenter View show that the audience screen does not?",options:["The slide theme","All slide animations","Speaker notes, the next slide, and a timer","The file name and save location"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Add brief speaker notes to at least three slides.","Hide the last slide in the presentation.","Start the slide show From Beginning using F5.","Advance through the first three slides using the spacebar.","Right-click and use Go to Slide to jump directly to slide 5.","Activate the Pen tool and circle one key item on the slide.","Press E to erase your ink marks.","Press Escape to exit the slide show.","Confirm that the last slide is still hidden by checking the slide panel."]}]},{slug:"sharing-and-exporting",title:"Sharing and Exporting Presentations",description:"Learn how to share your presentation via OneDrive, export it as a PDF, create a video from your slides, and package your file for delivery on another computer.",duration:"9 min",videoUrl:"",practiceFiles:[],sections:[{heading:"Why Sharing and Exporting Matter",blocks:[{type:"paragraph",text:"A great presentation needs to reach your audience in the right format. Sometimes that means sharing a live editable file; other times you need a locked PDF or a self-contained video that can play anywhere."},{type:"paragraph",text:"PowerPoint provides several options for getting your file out of your computer and into the hands of your audience."}]},{heading:"Sharing via OneDrive",blocks:[{type:"paragraph",text:"The Share button in the upper-right corner of PowerPoint lets you invite people to view or edit your presentation using OneDrive."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_share_button.png",alt:"Share button in the upper-right corner of PowerPoint"},{type:"paragraph",text:"Before sharing, PowerPoint may ask you to save the file to OneDrive if it hasn't been saved there already."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_onedrive_prompt.png",alt:"Prompt to save file to OneDrive before sharing"},{type:"paragraph",text:"Enter email addresses, choose whether recipients can edit or only view, and optionally add a message before clicking Send."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_share_pane.png",alt:"Share pane with email invitation fields"},{type:"tip",text:"Use Can View instead of Can Edit when sharing with clients or stakeholders who should not modify the presentation."}]},{heading:"Sending as an Email Attachment",blocks:[{type:"paragraph",text:"To attach the presentation directly to an email, go to File → Share → Email and choose one of the send options."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_email_options.png",alt:"Email sharing options in Backstage view"},{type:"list",ordered:!1,items:["Send as Attachment — attaches the editable .pptx file.","Send as PDF — converts and attaches a PDF version.","Send as XPS — attaches an XPS document (similar to PDF)."]}]},{heading:"Exporting as a PDF",blocks:[{type:"paragraph",text:"A PDF version of your presentation preserves formatting exactly as you designed it and can be opened on any device without PowerPoint installed."},{type:"paragraph",text:"Go to File → Export → Create PDF/XPS. Choose a location, confirm the file name, and click Publish."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_export_pdf.png",alt:"Create PDF/XPS dialog in PowerPoint"},{type:"paragraph",text:"Click Options before publishing to control what is included — all slides, a range of slides, or hidden slides."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_pdf_options.png",alt:"PDF options dialog showing slide range settings"},{type:"callout",variant:"info",text:"PDF is the best format to use when you need recipients to view but not edit your presentation."}]},{heading:"Creating a Video from Your Presentation",blocks:[{type:"paragraph",text:"PowerPoint can export your entire presentation — including animations and transitions — as a standalone video file that plays without PowerPoint."},{type:"paragraph",text:"Go to File → Export → Create a Video. Choose the display quality, set how long each slide appears, and click Create Video."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_create_video.png",alt:"Create a Video export options in PowerPoint"},{type:"paragraph",text:"PowerPoint will render the video and save it as an MP4 or WMV file. This can be shared, uploaded to a website, or played at a kiosk."},{type:"tip",text:"For most purposes choose Full HD (1080p). Use Presentation HD (720p) only if file size is a concern."}]},{heading:"Packaging a Presentation for Delivery",blocks:[{type:"paragraph",text:"If you need to present on a computer that may not have PowerPoint — or if your presentation uses linked media files — use Package Presentation for CD."},{type:"paragraph",text:"Go to File → Export → Package Presentation for CD. This bundles your presentation, all linked media, and the PowerPoint Viewer into a single folder you can copy to a USB drive."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_package_for_cd.png",alt:"Package Presentation for CD dialog"},{type:"callout",variant:"warning",text:"Despite the name, you do not need an actual CD. Copy to Folder saves everything to a location you choose, such as a USB drive or a network folder."}]},{heading:"Marking a Presentation as Final",blocks:[{type:"paragraph",text:"Mark as Final signals to recipients that the presentation is complete and discourages further editing. It sets the file to read-only and displays an information banner."},{type:"paragraph",text:"Go to File → Info → Protect Presentation → Mark as Final."},{type:"image",src:"/images/powerpoint/module-8/sharing/sharing_mark_as_final.png",alt:"Mark as Final option in Backstage view"},{type:"callout",variant:"warning",text:"Mark as Final is not a security feature. Any recipient can click Edit Anyway to remove the restriction and modify the file."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which export format preserves slide formatting and can be opened without PowerPoint?",options:[".pptx",".docx","PDF",".xlsx"],correctIndex:2},{type:"knowledge-check",question:"What is the primary purpose of Package Presentation for CD?",options:["To compress the file for email","To bundle the presentation and media into a portable folder for use on other computers","To convert the presentation to a video","To share the file on OneDrive"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Open the practice presentation and complete the following tasks:"},{type:"list",ordered:!0,items:["Export the presentation as a PDF. Make sure only slides 1 through 5 are included.","Export the presentation as a Full HD (1080p) video with each slide set to display for 5 seconds.","Use Package Presentation for CD to copy the file to a folder on your Desktop named Presentation Package.","Open the resulting folder and confirm it contains the presentation file and any associated media.","Return to PowerPoint, go to File → Info, and Mark the presentation as Final."]}]}],level:"Intermediate",estimatedMinutes:27}],excel:[{moduleNumber:1,moduleSlug:"module-1",title:"Excel Fundamentals",emoji:"\uD83D\uDCCA",description:"Interface navigation, workbook basics, formatting, and spreadsheet setup.",lessons:[{slug:"getting-started-with-excel",title:"Getting Started with Excel",description:"Learn your way around the Excel interface, including the Ribbon, Backstage view, Quick Access Toolbar, workbook views, and zoom controls.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/lgIWIPDJuPo",practiceFiles:[],sections:[{heading:"The Excel Interface",blocks:[{type:"paragraph",text:"When you open Excel, you’ll see a workbook made up of rows, columns, and cells. The active cell is highlighted and ready for data entry."},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_interface_start.png",alt:"Excel interface overview"}]},{heading:"Understanding the Ribbon",blocks:[{type:"paragraph",text:"The Ribbon contains tabs like Home, Insert, Page Layout, Formulas, Data, Review, and View. Each tab contains groups of related commands."},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_ribbon_tabs2.png",alt:"Excel ribbon tabs"},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_ribbon_group.png",alt:"Ribbon command groups"}]},{heading:"Backstage View",blocks:[{type:"paragraph",text:"Click the File tab to open Backstage view. From here, you can save, open, print, share, and manage your workbook."},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_backstage_file.png",alt:"File tab backstage view"},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_backstage_view.png",alt:"Backstage view screen"}]},{heading:"Quick Access Toolbar",blocks:[{type:"paragraph",text:"The Quick Access Toolbar lets you quickly access frequently used commands like Save, Undo, and Redo. You can customize it to add more tools."},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_quick_access_menu.png",alt:"Quick access customization menu"},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_quick_access_added.png",alt:"Quick access toolbar with new command"}]},{heading:"Using the Tell Me Box",blocks:[{type:"paragraph",text:"The Tell Me box helps you quickly find commands. Simply type what you want to do, and Excel will suggest tools and actions."},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_tell_me.png",alt:"Tell Me search box"},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_tell_me_type.png",alt:"Typing into Tell Me"}]},{heading:"Workbook Views & Zoom",blocks:[{type:"paragraph",text:"Excel includes different worksheet views, such as Normal view and Page Break view. You can also adjust zoom levels using the zoom slider."},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_views_buttons.png",alt:"View buttons"},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_views_normal.png",alt:"Normal view"},{type:"image",src:"/images/excel/module-1/getting-started/getting_started_views_page_break.png",alt:"Page break view"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Where are most Excel commands found?",options:["The status bar at the bottom of the screen","The formula bar above the worksheet","The Ribbon at the top of the screen","The Quick Access Toolbar"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Identify the active cell in a new workbook.","Switch between Ribbon tabs.","Open Backstage view and return to the workbook.","Add a command to the Quick Access Toolbar.","Use the Tell Me box to find a command.","Switch between Normal view and Page Break view.","Adjust the zoom level."]}]},{slug:"understanding-onedrive-for-excel",title:"Understanding OneDrive for Excel",description:"Learn how to sign in to Excel, connect to your Microsoft account, and use OneDrive to save and access workbooks from anywhere.",duration:"8 min",sections:[{heading:"Signing In to Excel",blocks:[{type:"paragraph",text:"To use OneDrive features, sign in to Excel using your Microsoft account. Click the Sign In button in the upper-right corner."},{type:"image",src:"/images/excel/module-1/onedrive/2015-11-17_09-35-16.png",alt:"Excel sign in button"}]},{heading:"Saving to OneDrive",blocks:[{type:"paragraph",text:"Click File → Save As. If you are signed in, you will see OneDrive listed as a save location."},{type:"image",src:"/images/excel/module-1/onedrive/2015-11-16_13-50-49.png",alt:"Save As screen showing OneDrive"},{type:"paragraph",text:"Saving to OneDrive allows you to access your files from any device and protects against data loss."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What allows you to access your Excel files from any device?",options:["Enabling AutoRecover in Excel Options","Saving your workbook to OneDrive","Keeping Excel open in the background","Using the Quick Access Toolbar"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Sign in to Excel with a Microsoft account.","Save a workbook to OneDrive.","Locate your file in OneDrive online.","Use the Share button to generate a link."]}]},{slug:"creating-and-opening-workbooks",title:"Creating and Opening Workbooks",description:"Learn how to create new workbooks, open existing files, use templates, pin recent files, and understand Compatibility Mode in Excel.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/EBGrJckHadw",practiceFiles:[{name:"Creating & Opening Practice File",url:"/practice/excel/module-1/creating-opening/Excel_CreatingOpening_Practice.xls"}],sections:[{heading:"Creating a New Workbook",blocks:[{type:"paragraph",text:"To create a new workbook, click File → New. You can select a Blank Workbook or choose from available templates."},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_new.png",alt:"New workbook screen"},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_template_new.png",alt:"Template selection screen"}]},{heading:"Searching for Templates",blocks:[{type:"paragraph",text:"Excel allows you to search for online templates. Simply type a keyword like 'budget' into the search bar."},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_template_search.png",alt:"Searching templates"},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_template_preview.png",alt:"Template preview"}]},{heading:"Opening Existing Workbooks",blocks:[{type:"paragraph",text:"Click File → Open to access recent workbooks, OneDrive files, or browse your computer."},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_open_recent.png",alt:"Open recent files screen"},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_open_dialog.png",alt:"Open dialog box"}]},{heading:"Pinning Recent Files",blocks:[{type:"paragraph",text:"You can pin frequently used workbooks so they always appear at the top of your Recent list."},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_pin_pushpin.png",alt:"Pin icon"},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_pin_open.png",alt:"Pinned file example"}]},{heading:"Understanding Compatibility Mode",blocks:[{type:"paragraph",text:"If you open an older Excel file, you may see Compatibility Mode in the title bar. Some newer features are disabled until the file is converted."},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_compatibility_example.png",alt:"Compatibility mode example"},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_compatibility_convert.png",alt:"Convert file option"},{type:"image",src:"/images/excel/module-1/creating-opening/creating_opening_compatibility_dialog.png",alt:"Compatibility dialog box"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a template in Excel?",options:["A locked workbook that cannot be edited","A saved chart format you can reuse","A pre-formatted workbook you can use as a starting point","A file that contains only formulas"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Create a new blank workbook.","Search for and preview a template.","Open a recent workbook.","Pin a file to the Recent list.","Open an older Excel file and convert it from Compatibility Mode."]}]},{slug:"saving-exporting-and-sharing",title:"Saving, Exporting & Sharing Workbooks",description:"Learn how to save workbooks, use AutoRecover, export to PDF, change file types, and share files using OneDrive.",duration:"14 min",practiceFiles:[{name:"Saving & Sharing Practice File",url:"/practice/excel/module-1/saving-sharing/Excel_SavingSharing_Practice.xlsx"}],sections:[{heading:"Saving a Workbook",blocks:[{type:"paragraph",text:"Click File → Save or Save As to store your workbook. You can save to OneDrive, your computer, or another location."},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_onedrive.png",alt:"Saving to OneDrive"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_save_dialog.png",alt:"Save dialog box"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_save_quick_access.png",alt:"Quick access save button"}]},{heading:"Changing Save Locations & Options",blocks:[{type:"paragraph",text:"You can adjust default save locations and other settings in File → Options → Save."},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_change_location_options.png",alt:"Excel save options"}]},{heading:"Recovering Unsaved Workbooks",blocks:[{type:"paragraph",text:"Excel uses AutoRecover to save temporary versions of your work. If Excel closes unexpectedly, you can recover unsaved files."},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_autorecover_manage.png",alt:"Recover unsaved workbooks"}]},{heading:"Exporting as PDF or Other File Types",blocks:[{type:"paragraph",text:"You can export your workbook as a PDF or change the file type using File → Export."},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_export_menu.png",alt:"Export menu"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_export_publish.png",alt:"Publish as PDF"},{type:"paragraph",text:"Excel by default will only export active worksheet. If you have multiple worksheets and want them saved to the same PDF file, click Options in the Save As dialog box. Select Entire Workbook, then click Ok"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_export_entire_wb.png",alt:"Publish as PDF"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_export_types_change.png",alt:"Change file type"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_export_types_file_type.png",alt:"Workbook file types"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_export_types_type.png",alt:"Selecting file type"},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_export_types_save_as.png",alt:"Save as different file type"}]},{heading:"Sharing Workbooks",blocks:[{type:"paragraph",text:"Use File → Share to send your workbook through OneDrive. You can generate links and control permissions."},{type:"image",src:"/images/excel/module-1/saving-sharing/saving_sharing_share_pane.png",alt:"Share option"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What format should you use to share a workbook that others cannot edit?",options:["CSV (.csv)","Excel Macro-Enabled Workbook (.xlsm)","PDF (.pdf)","Excel 97-2003 Workbook (.xls)"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Save a workbook to OneDrive.","Change the default save location in Options.","Recover an unsaved workbook.","Export a workbook as a PDF.","Save a workbook as a CSV file.","Share a workbook using OneDrive."]}]}],level:"Beginner",estimatedMinutes:40},{moduleNumber:2,moduleSlug:"module-2",title:"Cells, Formatting & Basic Formulas",emoji:"\uD83E\uDDEE",description:"Cell formatting, number formats, worksheet structure, and basic formulas.",lessons:[{slug:"cell-basics",title:"Cell Basics",description:"Learn how to insert and delete cells and cell content, drag and drop cells, use the fill handle, and use cut, copy, and paste.",duration:"12 min",videoUrls:["https://www.youtube.com/embed/6mSKsaquTAM","https://www.youtube.com/embed/Ww56q-BSSXw"],practiceFiles:[{name:"Cell Basics Practice File",url:"/practice/excel/module-2/cell-basics/Excel_CellBasics_Practice.xlsx"}],sections:[{heading:"Understanding Cells and Ranges",blocks:[{type:"paragraph",text:"A cell is the intersection of a row and column. A range is a group of selected cells."},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_intro_cell.png",alt:"Excel cell example"},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_select_range.png",alt:"Selecting a range in Excel"}]},{heading:"Insert and Delete Cells",blocks:[{type:"paragraph",text:"You can insert new cells or delete existing ones to reorganize worksheet data."},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_insert_select.png",alt:"Insert cells"},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_delete_select.png",alt:"Delete cells"}]},{heading:"Cut, Copy & Paste",blocks:[{type:"paragraph",text:"Use Cut, Copy, and Paste to move or duplicate data."},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_copy_command.png",alt:"Copy command in Excel"},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_paste_done.png",alt:"Pasting in Excel"}]},{heading:"Using the Fill Handle",blocks:[{type:"paragraph",text:"The fill handle allows you to quickly copy data or create series."},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_fill_select.png",alt:"Fill handle selection"},{type:"image",src:"/images/excel/module-2/cell-basics/cellb_fill_done.png",alt:"Fill handle result"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does the fill handle do in Excel?",options:["Deletes the contents of selected cells","Formats cells with a fill color","Copies content or continues a pattern into adjacent cells","Inserts a new row below the selected cell"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a new row.","Delete a selected cell.","Copy and paste data.","Use the fill handle to extend a series."]}]},{slug:"modifying-columns-rows-and-cells",title:"Modifying Columns, Rows, and Cells",description:"Learn how to resize, insert, delete, hide, move, and format rows and columns in Excel.",duration:"15 min",videoUrl:"https://www.youtube.com/embed/9s0OdXiuqL0",practiceFiles:[{name:"Modifying Columns and Rows Practice File",url:"/practice/excel/module-2/modifying/excel_modifyingcells_practice.xlsx"}],sections:[{heading:"Resizing Columns",blocks:[{type:"paragraph",text:"You can manually resize columns by dragging the boundary between column headers or use AutoFit to automatically adjust the width."},{type:"image",src:"/images/excel/module-2/modifying/mod_colwidth_select.png",alt:"Selecting column boundary"},{type:"image",src:"/images/excel/module-2/modifying/mod_colwidth_during.png",alt:"Dragging to resize column"},{type:"image",src:"/images/excel/module-2/modifying/mod_colwidth_auto_start.png",alt:"AutoFit column width option"},{type:"image",src:"/images/excel/module-2/modifying/mod_colwidth_auto_done.png",alt:"AutoFit result"}]},{heading:"Resizing Rows",blocks:[{type:"paragraph",text:"Row height can be adjusted manually or through the Row Height command."},{type:"image",src:"/images/excel/module-2/modifying/mod_rowheight_start.png",alt:"Selecting row boundary"},{type:"image",src:"/images/excel/module-2/modifying/mod_rowheight_during.png",alt:"Dragging to resize row"},{type:"image",src:"/images/excel/module-2/modifying/mod_rowheight_done.png",alt:"Resized row"}]},{heading:"Wrap Text",blocks:[{type:"paragraph",text:"Wrap Text allows content to appear on multiple lines within a single cell instead of expanding the column width."},{type:"image",src:"/images/excel/module-2/modifying/mod_wrap_command.png",alt:"Wrap Text command"},{type:"image",src:"/images/excel/module-2/modifying/mod_wrap_done.png",alt:"Wrapped text result"}]},{heading:"Inserting Rows and Columns",blocks:[{type:"paragraph",text:"You can insert new rows or columns using the Insert command from the Home tab."},{type:"image",src:"/images/excel/module-2/modifying/mod_insertrow_select.png",alt:"Selecting row before inserting"},{type:"image",src:"/images/excel/module-2/modifying/mod_insertrow_command.png",alt:"Insert row command"},{type:"image",src:"/images/excel/module-2/modifying/mod_insertrow_done.png",alt:"Inserted row result"},{type:"image",src:"/images/excel/module-2/modifying/mod_insertcol_command.png",alt:"Insert column command"},{type:"image",src:"/images/excel/module-2/modifying/mod_insertcol_done.png",alt:"Inserted column result"}]},{heading:"Deleting Rows and Columns",blocks:[{type:"paragraph",text:"Rows and columns can be deleted using the Delete command or right-click menu."},{type:"image",src:"/images/excel/module-2/modifying/mod_delete_select.png",alt:"Selecting row to delete"},{type:"image",src:"/images/excel/module-2/modifying/mod_delete_command.png",alt:"Delete command"},{type:"image",src:"/images/excel/module-2/modifying/mod_delete_done.png",alt:"Deleted row result"}]},{heading:"Hiding and Unhiding Rows and Columns",blocks:[{type:"paragraph",text:"Rows and columns can be hidden to temporarily remove them from view without deleting data."},{type:"image",src:"/images/excel/module-2/modifying/mod_hide_command.png",alt:"Hide command"},{type:"image",src:"/images/excel/module-2/modifying/mod_hide_hidden.png",alt:"Hidden column"},{type:"image",src:"/images/excel/module-2/modifying/mod_hide_unhidden.png",alt:"Unhidden column"}]},{heading:"Moving Rows and Columns",blocks:[{type:"paragraph",text:"Rows and columns can be moved using Cut and Insert Cut Cells."},{type:"image",src:"/images/excel/module-2/modifying/mod_move_select.png",alt:"Selecting row to move"},{type:"image",src:"/images/excel/module-2/modifying/mod_move_cut.png",alt:"Cut command"},{type:"image",src:"/images/excel/module-2/modifying/mod_move_done.png",alt:"Moved row result"}]},{heading:"Merge & Center vs Center Across Selection",blocks:[{type:"paragraph",text:"Merge & Center combines cells into one. Center Across Selection centers text without merging cells."},{type:"image",src:"/images/excel/module-2/modifying/mod_merge_select.png",alt:"Merge select"},{type:"image",src:"/images/excel/module-2/modifying/mod_merge_more.png",alt:"Merge options"},{type:"image",src:"/images/excel/module-2/modifying/mod_centeracross_dialog.png",alt:"Center Across Selection dialog"}]},{heading:"Selecting All Cells",blocks:[{type:"paragraph",text:"Click the Select All button to highlight the entire worksheet at once."},{type:"image",src:"/images/excel/module-2/modifying/mod_selectall.png",alt:"Select All button"},{type:"image",src:"/images/excel/module-2/modifying/mod_selectall_done.png",alt:"Entire worksheet selected"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does AutoFit do to a column?",options:["Applies a preset width of 10 characters","Hides the column from view","Adjusts the column width to fit the widest content","Merges the column with the one to its right"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["AutoFit a column width.","Resize a row manually.","Insert a new row.","Delete a column.","Hide and unhide a column.","Move a row using Cut.","Use Wrap Text on a long address.","Use Center Across Selection on a title."]}]},{slug:"formatting-cells",title:"Formatting Cells in Excel",description:"Learn how to format fonts, apply colors, borders, alignment, cell styles, and enhance worksheet presentation.",duration:"20 min",videoUrls:["https://www.youtube.com/embed/etAMC0KRuBE","https://www.youtube.com/embed/LHSJJvkVrvA"],practiceFiles:[{name:"Formatting Cells Practice File",url:"/practice/excel/module-2/formatting/Excel_FormattingCells_Practice.xlsx"}],sections:[{heading:"Changing Font Type",blocks:[{type:"paragraph",text:"You can change the font type from the Font group on the Home tab."},{type:"image",src:"/images/excel/module-2/formatting/font type select cells.png",alt:"Selecting cells for font change"},{type:"image",src:"/images/excel/module-2/formatting/font type dropdown menu.png",alt:"Font dropdown menu"},{type:"image",src:"/images/excel/module-2/formatting/font type after change.png",alt:"Font after change"}]},{heading:"Changing Font Size",blocks:[{type:"paragraph",text:"You can choose a font size from the dropdown or use the Increase and Decrease Font Size buttons."},{type:"image",src:"/images/excel/module-2/formatting/font-size-select-cells.png",alt:"Selecting cells for font size change"},{type:"image",src:"/images/excel/module-2/formatting/font-size-dropdown-menu.png",alt:"Font size dropdown"},{type:"image",src:"/images/excel/module-2/formatting/font-size-increase-and-decrease.png",alt:"Increase and decrease font size buttons"},{type:"image",src:"/images/excel/module-2/formatting/font-size-after-size-change.png",alt:"Font size applied"}]},{heading:"Bold, Italic, and Underline",blocks:[{type:"paragraph",text:"Use Bold, Italic, and Underline to emphasize important text."},{type:"image",src:"/images/excel/module-2/formatting/font-biu-buttons.png",alt:"BIU buttons"},{type:"image",src:"/images/excel/module-2/formatting/biu-select-cells.png",alt:"Selecting cells for BIU"},{type:"image",src:"/images/excel/module-2/formatting/biu-after-change.png",alt:"BIU applied"}]},{heading:"Changing Font Color",blocks:[{type:"paragraph",text:"Font color can be changed using Theme Colors or Standard Colors."},{type:"image",src:"/images/excel/module-2/formatting/font color select cells.png",alt:"Selecting cells for font color"},{type:"image",src:"/images/excel/module-2/formatting/font color dropdown menu.png",alt:"Font color dropdown"},{type:"image",src:"/images/excel/module-2/formatting/font color after change.png",alt:"Font color applied"}]},{heading:"Applying Fill Color",blocks:[{type:"paragraph",text:"Fill color changes the background color of selected cells."},{type:"image",src:"/images/excel/module-2/formatting/fill-color-select-cells2.png",alt:"Selecting cells for fill color"},{type:"image",src:"/images/excel/module-2/formatting/fill-color-after-change3.png",alt:"Fill color applied"}]},{heading:"Applying Borders",blocks:[{type:"paragraph",text:"Borders help define data tables and improve readability."},{type:"image",src:"/images/excel/module-2/formatting/borders-select-cells2.png",alt:"Selecting cells for borders"},{type:"image",src:"/images/excel/module-2/formatting/borders-after-change2.png",alt:"Borders applied"}]},{heading:"Using Cell Styles",blocks:[{type:"paragraph",text:"Excel provides built-in cell styles for quick formatting."},{type:"image",src:"/images/excel/module-2/formatting/cell-style-select-cells2.png",alt:"Selecting cells for cell style"},{type:"image",src:"/images/excel/module-2/formatting/cell-style-dropdown-menu.png",alt:"Cell style dropdown"},{type:"image",src:"/images/excel/module-2/formatting/cell-style-after-change.png",alt:"Cell style applied"}]},{heading:"Horizontal Alignment",blocks:[{type:"paragraph",text:"Horizontal alignment positions text left, center, or right within a cell."},{type:"image",src:"/images/excel/module-2/formatting/horizontal-align-select-cells.png",alt:"Selecting cells for horizontal alignment"},{type:"image",src:"/images/excel/module-2/formatting/horizontal-align-after-change.png",alt:"Horizontal alignment applied"}]},{heading:"Vertical Alignment",blocks:[{type:"paragraph",text:"Vertical alignment positions text at the top, middle, or bottom of a cell."},{type:"image",src:"/images/excel/module-2/formatting/vertical-align-buttons.png",alt:"Vertical alignment buttons"},{type:"image",src:"/images/excel/module-2/formatting/vertical-align-select-cells.png",alt:"Selecting cells for vertical alignment"},{type:"image",src:"/images/excel/module-2/formatting/vertical-align-after-change.png",alt:"Vertical alignment applied"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which formatting option applies color to the background of a cell?",options:["Font Color","Cell Style","Fill Color","Border Color"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Change the font type and size of the worksheet title.","Apply Bold formatting to the header row.","Change the font color of the title.","Apply fill color to the header row.","Add borders to the entire data table.","Center-align column headers horizontally.","Apply Middle Align vertically.","Apply a built-in cell style."]},{type:"image",src:"/images/excel/module-2/formatting/formatting cells challenge screenshot.png",alt:"Formatting challenge example"}]},{slug:"understanding-number-formats",title:"Understanding Number Formats in Excel",description:"Learn how to apply Date, Currency, Percentage, and Decimal number formats, and understand how formatting affects calculations.",duration:"18 min",videoUrls:["https://www.youtube.com/embed/fjyOG7Ls7BA","https://www.youtube.com/embed/LLmSAQ2PgVc"],practiceFiles:[{name:"Number Formats Practice File",url:"/practice/excel/module-2/number-formats/Excel_NumberFormats_Practice.xlsx"}],sections:[{heading:"General Format vs Specific Formats",blocks:[{type:"paragraph",text:"By default, Excel uses the General format. This does not apply any special formatting such as currency symbols, percentage signs, or date styling."},{type:"image",src:"/images/excel/module-2/number-formats/number_date_general.png",alt:"General format example"}]},{heading:"Applying Date Formats",blocks:[{type:"paragraph",text:"Dates can be formatted as Short Date, Long Date, or customized through the Format Cells dialog box."},{type:"image",src:"/images/excel/module-2/number-formats/number_date_format.png",alt:"Date dropdown menu"},{type:"image",src:"/images/excel/module-2/number-formats/number_date_longdate.png",alt:"Long date example"},{type:"image",src:"/images/excel/module-2/number-formats/number_date_dialog.png",alt:"Date format dialog box"}]},{heading:"Currency and Accounting Formats",blocks:[{type:"paragraph",text:"Currency format adds a currency symbol and decimal places. Accounting format aligns currency symbols and decimal points for professional financial reports."},{type:"image",src:"/images/excel/module-2/number-formats/number_formats_applying_menu_cropped.png",alt:"Currency from dropdown menu"},{type:"image",src:"/images/excel/module-2/number-formats/number_formats_applying_currency_cropped.png",alt:"Currency formatting applied"}]},{heading:"Decimal Places and Rounding",blocks:[{type:"paragraph",text:"Use Increase Decimal and Decrease Decimal to control how many decimal places are displayed."},{type:"image",src:"/images/excel/module-2/number-formats/number_formats_decimal_commands.png",alt:"Decimal commands"},{type:"image",src:"/images/excel/module-2/number-formats/number_format_decimal_rounding.png",alt:"Decimal rounding example"}]},{heading:"Understanding Percentage Format",blocks:[{type:"paragraph",text:"Percentage format multiplies a value by 100 and adds a percent symbol. For example, typing 0.05 and applying Percentage becomes 5%."},{type:"image",src:"/images/excel/module-2/number-formats/number_percent_intro.png",alt:"Percentage format example"},{type:"image",src:"/images/excel/module-2/number-formats/number_percent_compare_big.png",alt:"Percentage formatting comparison"},{type:"image",src:"/images/excel/module-2/number-formats/number_tip_percent_after.png",alt:"Percentage applied correctly"}]},{heading:"How Formatting Affects Calculations",blocks:[{type:"paragraph",text:"Formatting changes how data is displayed, but it does not change the underlying value. Understanding this is critical for accurate calculations."},{type:"image",src:"/images/excel/module-2/number-formats/number_tip_carryover.png",alt:"Formatting does not change actual value"},{type:"image",src:"/images/excel/module-2/number-formats/number_format_chart.png",alt:"Correct vs incorrect formatting comparison"}]},{heading:"Real-World Example: Customer Invoice",blocks:[{type:"paragraph",text:"In professional documents like invoices, proper number formatting ensures totals, tax rates, and currency values are displayed correctly."},{type:"image",src:"/images/excel/module-2/number-formats/invoice_final_example.png",alt:"Formatted invoice example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"If a cell is formatted as Percentage, what does the value 0.25 display as?",options:["0.25%","2.5%","25%","250%"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Format a column as Short Date.","Change a date to Long Date format.","Apply Currency formatting to a price column.","Adjust decimal places to two digits.","Format a tax rate as Percentage.","Create a properly formatted invoice total."]}]},{slug:"intro-to-formulas",title:"Intro to Formulas",description:"Learn how to create basic formulas in Excel using cell references, mathematical operators, and the fill handle.",duration:"15 min",videoUrl:"https://www.youtube.com/embed/xc14gFFyiTw",practiceFiles:[{name:"Intro to Formulas Practice File",url:"/practice/excel/module-2/formulas/Excel_IntroFormulas_Practice.xlsx"}],sections:[{heading:"What Is a Formula?",blocks:[{type:"paragraph",text:"A formula is an equation that performs calculations in a worksheet. All formulas in Excel must begin with an equals sign (=)."},{type:"paragraph",text:"Excel can add, subtract, multiply, divide, and calculate exponents using standard mathematical operators."},{type:"image",src:"/images/excel/module-2/formulas/simpform_graphic_operators4.png",alt:"Excel mathematical operators"}]},{heading:"Understanding Cell References",blocks:[{type:"paragraph",text:"Instead of typing numbers directly into formulas, Excel typically uses cell references. A cell reference identifies the location of data in the worksheet, such as A1 or D10."},{type:"paragraph",text:"Using references allows formulas to automatically update when the referenced data changes."},{type:"image",src:"/images/excel/module-2/formulas/formulas_understanding_1.png",alt:"Simple numbers in cells"},{type:"image",src:"/images/excel/module-2/formulas/formulas_understanding_2.png",alt:"Formula using cell references"},{type:"image",src:"/images/excel/module-2/formulas/formulas_understanding_3.png",alt:"Formula recalculated result"}]},{heading:"Common Formula Examples",blocks:[{type:"image",src:"/images/excel/module-2/formulas/simpform_graphic_formulas5.png",alt:"Common formula examples table"}]},{heading:"Creating a Basic Formula",blocks:[{type:"paragraph",text:"To create a formula, select the cell where you want the result to appear, type an equals sign (=), then enter the cell references and operator."},{type:"paragraph",text:"In this example, we calculate a total budget by adding two cells together."},{type:"image",src:"/images/excel/module-2/formulas/formulas_create_equals_sign.png",alt:"Typing equals sign in Excel"},{type:"image",src:"/images/excel/module-2/formulas/formulas_create_cell_reference.png",alt:"Selecting first cell reference"},{type:"image",src:"/images/excel/module-2/formulas/formulas_create_operator.png",alt:"Typing operator in formula"},{type:"image",src:"/images/excel/module-2/formulas/formulas_create_result.png",alt:"Final calculated result"}]},{heading:"Editing a Formula",blocks:[{type:"paragraph",text:"To modify a formula, select the cell and click inside the formula bar, or double-click the cell to edit directly."},{type:"image",src:"/images/excel/module-2/formulas/formulas_edit_click.png",alt:"Clicking formula bar"},{type:"image",src:"/images/excel/module-2/formulas/formulas_edit_edit.png",alt:"Editing formula reference"},{type:"image",src:"/images/excel/module-2/formulas/formulas_edit_enter.png",alt:"Press Enter to confirm formula"},{type:"image",src:"/images/excel/module-2/formulas/formulas_edit_result.png",alt:"Updated formula result"},{type:"image",src:"/images/excel/module-2/formulas/formulas_edit_cancel.png",alt:"Cancel formula edit"}]},{heading:"Using the Point-and-Click Method",blocks:[{type:"paragraph",text:"Instead of typing cell addresses manually, you can click the cells you want to include in the formula. This reduces errors and increases accuracy."},{type:"image",src:"/images/excel/module-2/formulas/formulas_pnc_select.png",alt:"Selecting first cell"},{type:"image",src:"/images/excel/module-2/formulas/formulas_pnc_click_1.png",alt:"Selecting second cell"},{type:"image",src:"/images/excel/module-2/formulas/formulas_pnc_click_2.png",alt:"Completing multiplication"},{type:"image",src:"/images/excel/module-2/formulas/formulas_pnc_result.png",alt:"Point and click result"}]},{heading:"Copying Formulas with the Fill Handle",blocks:[{type:"paragraph",text:"Formulas can be copied to adjacent cells using the fill handle. This small square appears in the bottom-right corner of a selected cell."},{type:"image",src:"/images/excel/module-2/formulas/formulas_fill_select2.png",alt:"Selecting cell with formula"},{type:"image",src:"/images/excel/module-2/formulas/formulas_fill_result.png",alt:"Formula copied using fill handle"}]},{heading:"Practical Invoice Example",blocks:[{type:"paragraph",text:"In real-world spreadsheets, formulas are often used to calculate totals such as invoices, budgets, or payroll."},{type:"image",src:"/images/excel/module-2/formulas/screen shot 2015-11-24 at 3.27.57 pm.png",alt:"Invoice example with calculated totals"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How must every Excel formula begin?",options:["With a plus sign (+)","With a cell reference like A1","With an equals sign (=)","With a function name like SUM"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks in the practice workbook:"},{type:"list",ordered:!0,items:["Create a formula in cell D4 that multiplies Quantity by Price per Unit.","Use the fill handle to copy the formula to remaining rows.","Edit one price value and verify that totals update automatically.","Create a formula that adds two budget values together.","Show all formulas using Ctrl + ` and then return to normal view."]}]}],level:"Beginner",estimatedMinutes:45},{moduleNumber:3,moduleSlug:"module-3",title:"Workbook Management, Printing & Basic Calculations",emoji:"\uD83D\uDCC4",description:"Multiple worksheets, find & replace, spell check, view tools, professional printing, and introduction to formulas.",lessons:[{slug:"working-with-multiple-worksheets",title:"Working with Multiple Worksheets",description:"Learn how to insert, rename, move, copy, group, and organize worksheets within a workbook.",videoUrl:"https://www.youtube.com/embed/qRShQc-v3LI",practiceFiles:[{name:"Multiple Worksheets Practice File",url:"/practice/excel/module-3/multiple-worksheets/Excel_MultipleSheets_Practice.xlsx"}],sections:[{heading:"Introduction",blocks:[{type:"paragraph",text:"Every workbook contains at least one worksheet by default. When working with large amounts of data, you can create multiple worksheets to better organize your information and make it easier to manage."},{type:"paragraph",text:"You can also group worksheets together to make changes to multiple sheets at the same time."}]},{heading:"Insert a New Worksheet",blocks:[{type:"list",ordered:!0,items:["Locate and select the New Sheet (+) button near the bottom-right corner of the Excel window.","A new blank worksheet will appear."]},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_new.png",alt:"New worksheet button"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_new_done.png",alt:"New worksheet inserted"}]},{heading:"Copy a Worksheet",blocks:[{type:"paragraph",text:"Excel allows you to duplicate an existing worksheet without copying and pasting content manually."},{type:"list",ordered:!0,items:["Right-click the worksheet you want to copy.","Select Move or Copy.","Choose where the sheet should appear.","Check Create a copy and click OK."]},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_copy_rightclick.png",alt:"Right-click move or copy"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_copy_dialog.png",alt:"Move or copy dialog box"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_copy_done.png",alt:"Copied worksheet"}]},{heading:"Rename a Worksheet",blocks:[{type:"list",ordered:!0,items:["Right-click the worksheet tab.","Select Rename.","Type the desired name and press Enter."]},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_rename_rightclick.png",alt:"Rename worksheet option"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_rename_done.png",alt:"Worksheet renamed"}]},{heading:"Move a Worksheet",blocks:[{type:"list",ordered:!0,items:["Click and drag the worksheet tab.","Release when the black arrow appears in the desired location."]},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_move_icon.png",alt:"Drag worksheet tab"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_move_done.png",alt:"Worksheet moved"}]},{heading:"Change Worksheet Tab Color",blocks:[{type:"list",ordered:!0,items:["Right-click the worksheet tab.","Hover over Tab Color.","Select the desired color."]},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_color_rightclick.png",alt:"Tab color menu"}]},{heading:"Delete a Worksheet",blocks:[{type:"list",ordered:!0,items:["Right-click the worksheet tab.","Select Delete."]},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_delete_rightclick.png",alt:"Delete worksheet option"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_delete_done.png",alt:"Delete worksheet done"}]},{heading:"Switching Between Worksheets",blocks:[{type:"paragraph",text:"You can click worksheet tabs to switch between sheets. For large workbooks, right-click the scroll arrows in the lower-left corner to see a list of all worksheets."},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_scroll_list.png",alt:"Worksheet navigation list"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_scroll_list_dialog.png",alt:"Worksheet navigation list"}]},{heading:"Grouping and Ungrouping Worksheets",blocks:[{type:"paragraph",text:"Grouping worksheets allows you to make changes to multiple sheets at the same time."},{type:"list",ordered:!0,items:["Hold the Ctrl key.","Click each worksheet tab you want to group.","Release Ctrl once selected."]},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_group_select.png",alt:"Grouped worksheets selected"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_group_during.png",alt:"Grouped worksheets active"},{type:"paragraph",text:"To ungroup worksheets, right-click any grouped tab and select Ungroup Sheets."},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_ungroup_rightclick.png",alt:"Ungroup sheets option"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How do you rename a worksheet tab in Excel?",options:["Go to File → Rename Sheet","Press F2 while the sheet is selected","Double-click the tab and type a new name","Use the Format menu on the Home tab"],correctIndex:2}]}],challenge:[{type:"list",ordered:!0,items:["Insert a new worksheet and rename it Q1 Summary.","Move the Expenses Summary worksheet to the far right.","Move the Q1 Summary worksheet so it appears between March and April.","Create a copy of the Expenses Summary worksheet using Move or Copy.","Change the January tab color to blue and the February tab color to red.","Group the worksheets September, October, and November."]},{type:"paragraph",text:"When you're finished, your workbook should resemble the example below:"},{type:"image",src:"/images/excel/module-3/multiple-worksheets/sheets_group_done.png",alt:"Completed worksheet layout"}]},{slug:"find-and-replace",title:"Using Find & Replace",description:"Search for specific data and quickly correct or replace repeated content throughout a worksheet or workbook.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/hmizmgOjNYo",practiceFiles:[{name:"Find and Replace Practice File",url:"/practice/excel/module-3/find-replace/Excel_FindReplace_Practice.xlsx"}],sections:[{heading:"Why Use Find & Replace?",blocks:[{type:"paragraph",text:"When working with large datasets, manually scanning for errors or repeated values can be time-consuming. Excel’s Find and Replace tools allow you to quickly locate and update content across a worksheet or an entire workbook."}]},{heading:"Using the Find Command",blocks:[{type:"paragraph",text:"To locate specific content, go to the Home tab, click Find & Select, then choose Find. You can also press Ctrl + F on your keyboard."},{type:"image",src:"/images/excel/module-3/find-replace/find-menu.png",alt:"Find command in Excel"},{type:"paragraph",text:"Enter the text you want to search for in the Find what field. Click Find Next to locate one instance at a time or Find All to display every match."},{type:"image",src:"/images/excel/module-3/find-replace/find-dialog.png",alt:"Find dialog box"},{type:"image",src:"/images/excel/module-3/find-replace/find-all-results.png",alt:"Find All results showing multiple matches"}]},{heading:"Advanced Search Options",blocks:[{type:"paragraph",text:"Click Options to expand advanced search settings such as Match Case, Match Entire Cell Contents, and choosing whether to search within the current sheet or the entire workbook."},{type:"image",src:"/images/excel/module-3/find-replace/find-options.png",alt:"Find dialog expanded options"}]},{heading:"Using Replace",blocks:[{type:"paragraph",text:"If you need to correct repeated mistakes or update values, use Replace. From the Home tab, click Find & Select, then choose Replace."},{type:"image",src:"/images/excel/module-3/find-replace/replace-menu.png",alt:"Replace option in Excel"},{type:"paragraph",text:"Enter the text to find in the Find what field and the replacement text in the Replace with field. Use Replace to update one instance at a time."},{type:"image",src:"/images/excel/module-3/find-replace/replace-dialog.png",alt:"Replace dialog box"}]},{heading:"Using Replace All",blocks:[{type:"paragraph",text:"Replace All updates every matching instance automatically. Use this option carefully, as it does not allow you to review changes individually."},{type:"image",src:"/images/excel/module-3/find-replace/replace-all-selected.png",alt:"Replace All button selected"},{type:"image",src:"/images/excel/module-3/find-replace/replace-confirmation.png",alt:"Replacement confirmation message"},{type:"image",src:"/images/excel/module-3/find-replace/replace-before-after.png",alt:"Before and after comparison of replaced values"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which keyboard shortcut opens the Replace dialog in Excel?",options:["Ctrl + F","Ctrl + G","Ctrl + H","Ctrl + R"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice workbook:"},{type:"list",ordered:!0,items:["Change Crystal Lewis’s last name to Taylor using Find and Replace. Be careful to only change Crystal’s record.","Replace Bio with Biology. Do NOT change Biomedical Engineering.","Use Replace All to change Physics to Physical Science.","Verify your worksheet matches the final expected result."]},{type:"image",src:"/images/excel/module-3/find-replace/challenge-final.png",alt:"Final challenge worksheet result"}]},{slug:"checking-spelling",title:"Checking Spelling in Excel",description:"Learn how to use Excel’s Spell Check tool to identify and correct spelling errors before sharing a workbook.",duration:"4 min",practiceFiles:[{name:"Check Spelling Practice File",url:"/practice/excel/module-3/spelling/Excel_CheckSpelling_Practice.xlsx"}],sections:[{heading:"Why Use Spell Check?",blocks:[{type:"paragraph",text:"Before sharing a workbook, it’s important to check for spelling errors. Excel includes a built-in Spell Check tool that scans your worksheet for misspelled words."},{type:"paragraph",text:"Unlike Microsoft Word, Excel does not check grammar or spelling as you type. Spell Check must be run manually."}]},{heading:"Running Spell Check",blocks:[{type:"paragraph",text:"To begin spell check, go to the Review tab and click Spelling."},{type:"image",src:"/images/excel/module-3/spelling/spelling-review-tab.png",alt:"Spelling command on Review tab"},{type:"paragraph",text:"The Spelling dialog box will appear. Excel will highlight words that are not found in the dictionary and provide suggestions."},{type:"image",src:"/images/excel/module-3/spelling/spelling-dialog.png",alt:"Spelling dialog box with suggestions"}]},{heading:"Correcting Spelling Errors",blocks:[{type:"paragraph",text:"Select the correct spelling from the Suggestions list and click Change to fix the error. Use Change All to correct every instance of that word in the worksheet."}]},{heading:"Ignoring or Adding Words",blocks:[{type:"paragraph",text:"Spell Check may flag names or brand terms that are actually correct. You can choose Ignore Once, Ignore All, or Add to Dictionary."},{type:"list",ordered:!1,items:["Ignore Once – Skips this instance.","Ignore All – Skips all instances in the worksheet.","Add to Dictionary – Saves the word so Excel won’t flag it again."]}]},{heading:"Spell Check Complete",blocks:[{type:"paragraph",text:"After Excel finishes reviewing the worksheet, a confirmation message will appear."},{type:"image",src:"/images/excel/module-3/spelling/spelling-complete.png",alt:"Spell check complete message"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What happens when you click 'Add to Dictionary' in Spell Check?",options:["The word is deleted from the worksheet","The word is automatically corrected to the nearest suggestion","The word is saved so Excel won't flag it as an error again","All instances of the word are replaced with the first suggestion"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Run Spell Check from the Review tab.","Correct the misspelled words 'coffe' and 'medum'.","Ignore the spelling suggestion for the word 'Amanecer'.","Finish spell check and confirm the completion message appears."]},{type:"image",src:"/images/excel/module-3/spelling/spelling-challenge-final.png",alt:"Final invoice after spell check"}]},{slug:"page-layout-and-printing",title:"Page Layout and Printing",description:"Learn how to control margins, orientation, scaling, print area, print titles, and page breaks to produce professional printed reports.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/8XcFTeCu98k",practiceFiles:[{name:"Printing Practice File",url:"/practice/excel/module-3/page-layout-and-printing/Excel_PageLayoutPrint_Practice.xlsx"}],sections:[{heading:"Accessing the Print Pane",blocks:[{type:"paragraph",text:"To begin printing in Excel, select the File tab to open Backstage View, then choose Print. The Print pane allows you to preview and configure all print settings."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_pane_file_tab.png",alt:"File tab in Excel"},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_pane_print_pane.png",alt:"Excel Print pane"}]},{heading:"Choosing What to Print",blocks:[{type:"paragraph",text:"From the Settings section, you can choose to print Active Sheets, the Entire Workbook, or a Selection. Always verify the preview before printing."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_print_active_select.png",alt:"Print active sheets option"},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_print_entire_workbook.png",alt:"Print entire workbook option"},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_print_selection_select.png",alt:"Print selection option"}]},{heading:"Setting a Print Area",blocks:[{type:"paragraph",text:"To define exactly what prints, select the desired cells, go to the Page Layout tab, click Print Area, and choose Set Print Area."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_print_area.png",alt:"Set print area command"}]},{heading:"Changing Page Orientation",blocks:[{type:"paragraph",text:"Excel offers Portrait (vertical) and Landscape (horizontal) orientation. Landscape is best for wide data tables."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_orientation_preview.png",alt:"Landscape orientation preview"}]},{heading:"Using Scaling Options",blocks:[{type:"paragraph",text:"If your worksheet content is cut off, use scaling options such as 'Fit All Columns on One Page' or 'Fit Sheet on One Page'. Be aware that scaling reduces text size."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_fit_preview.png",alt:"Fit columns to one page preview"}]},{heading:"Adjusting Margins",blocks:[{type:"paragraph",text:"Margins control the spacing between your worksheet content and the page edge. Choose presets like Normal, Wide, or Narrow, or manually adjust margins in the preview pane."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_margins_preview.png",alt:"Margins dropdown"},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_margins_show.png",alt:"Show margins in preview"}]},{heading:"Using Print Titles",blocks:[{type:"paragraph",text:"Use Print Titles to repeat header rows or columns on every printed page. Go to Page Layout → Print Titles and specify rows to repeat at top and columns to repeat at left."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_print_titles_ribbon.png",alt:"Print titles ribbon command"},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_print_titles_setup_rows_callout.png",alt:"Rows to repeat at top field"},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_print_titles_setup_ok.png",alt:"Print titles setup confirmation"}]},{heading:"Adjusting Page Breaks",blocks:[{type:"paragraph",text:"Switch to Page Break Preview to manually control where printed pages divide. Drag the blue lines to reposition page breaks."},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_break_view.png",alt:"Page break preview mode"},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/layout_break_drag1.png",alt:"Dragging page break line"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does setting a print area do in Excel?",options:["Adds a colored border around the selected cells","Saves the selected cells as a separate file","Limits printing to only the selected cells","Automatically fits all columns to one page"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the East Coast worksheet.","Repeat row 1 at the top and column A at the left.","Move the page break so rows 1–40 print on the first page.","Change orientation to Landscape.","Set margins to Narrow.","Use Fit All Columns on One Page.","Verify the preview matches the expected layout."]},{type:"image",src:"/images/excel/module-3/page-layout-and-printing/printing and page layout challenge.png",alt:"Final expected print preview"}]},{slug:"comments-and-coauthoring",title:"Comments and Co-authoring",description:"Learn how to add, edit, delete, and manage comments, collaborate in real time, and restore previous versions of a workbook.",duration:"11 min",videoUrl:"https://www.youtube.com/embed/eK23Fzttlyo",practiceFiles:[{name:"Comments & Track Changes Practice File",url:"/practice/excel/module-3/comments/Excel_TrackChangesComments_Practice.xlsx"}],sections:[{heading:"Sharing a Workbook",blocks:[{type:"paragraph",text:"To collaborate with others, click the Share button in the top-right corner of Excel."},{type:"image",src:"/images/excel/module-3/comments/comments_share_button.png",alt:"Share button in Excel"},{type:"paragraph",text:"Upload the workbook to OneDrive if prompted. Then enter the recipient’s email address and choose whether they Can edit or Can view."},{type:"image",src:"/images/excel/module-3/comments/comments_share_onedrive.png",alt:"Upload to OneDrive prompt"},{type:"image",src:"/images/excel/module-3/comments/comments_share_email.png",alt:"Entering email address in Share pane"},{type:"image",src:"/images/excel/module-3/comments/comments_share_can_edit.png",alt:"Can Edit dropdown option"},{type:"image",src:"/images/excel/module-3/comments/comments_share_share.png",alt:"Click Share button"}]},{heading:"Adding Comments",blocks:[{type:"paragraph",text:"Comments allow you to leave feedback without changing the contents of a cell. Select a cell, go to the Review tab, and click New Comment."},{type:"image",src:"/images/excel/module-3/comments/track_comment_new.png",alt:"New Comment button on Review tab"},{type:"image",src:"/images/excel/module-3/comments/track_comment_type.png",alt:"Typing a comment"},{type:"paragraph",text:"Cells with comments display a red indicator in the corner. Select the cell to view the comment."},{type:"image",src:"/images/excel/module-3/comments/track_comment_indicator_close.png",alt:"Cell with comment indicator"}]},{heading:"Editing Comments",blocks:[{type:"paragraph",text:"To edit a comment, select the cell and click Edit Comment on the Review tab."},{type:"image",src:"/images/excel/module-3/comments/track_edit_click.png",alt:"Edit Comment button"},{type:"image",src:"/images/excel/module-3/comments/track_edit_type.png",alt:"Editing comment text"}]},{heading:"Showing and Hiding Comments",blocks:[{type:"paragraph",text:"To display every comment at once, click Show All Comments on the Review tab."},{type:"image",src:"/images/excel/module-3/comments/track_show_click.png",alt:"Show All Comments button"},{type:"image",src:"/images/excel/module-3/comments/track_show_comments.png",alt:"All comments displayed"},{type:"paragraph",text:"You can also show or hide a single comment by selecting the cell and clicking Show/Hide Comment."},{type:"image",src:"/images/excel/module-3/comments/track_show_one.png",alt:"Show or hide individual comment"}]},{heading:"Deleting Comments",blocks:[{type:"paragraph",text:"To remove a comment, select the cell and click Delete in the Comments group on the Review tab."},{type:"image",src:"/images/excel/module-3/comments/track_delete_select.png",alt:"Selecting comment to delete"},{type:"image",src:"/images/excel/module-3/comments/track_delete_click.png",alt:"Delete comment button"},{type:"image",src:"/images/excel/module-3/comments/track_delete_deleted.png",alt:"Comment deleted"}]},{heading:"Real-Time Co-authoring",blocks:[{type:"paragraph",text:"When a workbook is shared through OneDrive, multiple users can edit at the same time. Each collaborator appears with a unique color indicator."},{type:"image",src:"/images/excel/module-3/comments/comments_coauthor_hover.png",alt:"Co-author hover indicator"}]},{heading:"Restoring a Previous Version",blocks:[{type:"paragraph",text:"If changes were made that you want to undo, click the clock icon next to the Share button to open Version History."},{type:"image",src:"/images/excel/module-3/comments/comments_restore_clock.png",alt:"Version history clock icon"},{type:"image",src:"/images/excel/module-3/comments/comments_restore_version.png",alt:"Version history pane"},{type:"image",src:"/images/excel/module-3/comments/comments_restore_restore.png",alt:"Restore previous version"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What allows multiple people to edit an Excel file at the same time?",options:["Enabling Track Changes from the Review tab","Saving the file as a CSV and emailing it","Sharing via OneDrive and using co-authoring","Using the Protect Workbook feature"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Add four comments to different cells.","Edit one of the comments.","Delete one comment.","Use Show All Comments to display every comment.","Open Version History and review a previous version."]},{type:"image",src:"/images/excel/module-3/comments/comments_challenge.png",alt:"Final challenge worksheet with comments"}]},{slug:"inspecting-and-protecting-workbooks",title:"Inspecting and Protecting Workbooks",description:"Learn how to inspect your workbook for hidden information and protect it before sharing by using Document Inspector and Protect Workbook tools.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/fsXS_VSuBvs",practiceFiles:[{name:"Inspect and Protect Practice File",url:"/practice/excel/module-3/inspect-protect/Excel_InspectProtect_Practice.xlsx"}],sections:[{heading:"Why Inspect and Protect a Workbook?",blocks:[{type:"paragraph",text:"Before sharing a workbook, you should remove hidden personal information and discourage unwanted editing. Excel provides tools such as Document Inspector and Protect Workbook to help finalize your file."}]},{heading:"Using Document Inspector",blocks:[{type:"paragraph",text:"Click the File tab to open Backstage view. From the Info pane, select Check for Issues and then click Inspect Document."},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_inspector_info.png",alt:"Check for Issues and Inspect Document option"},{type:"paragraph",text:"Excel may prompt you to save your file before continuing. Click Yes to proceed."},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_inspector_warning.png",alt:"Save confirmation before running Document Inspector"},{type:"paragraph",text:"Leave all inspection options selected and click Inspect."},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_inspector_inspect.png",alt:"Document Inspector options window"}]},{heading:"Removing Hidden Information",blocks:[{type:"paragraph",text:"If the inspector finds comments or personal information, click Remove All next to each category."},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_inspector_results.png",alt:"Document Inspector results showing removable content"},{type:"paragraph",text:"When finished, click Close to return to your workbook."},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_inspector_close2.png",alt:"Close Document Inspector"}]},{heading:"Protecting the Workbook",blocks:[{type:"paragraph",text:"To discourage editing, go to File → Info → Protect Workbook and choose Mark as Final."},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_protect_info.png",alt:"Protect Workbook menu"},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_protect_save_dialog.png",alt:"Mark as Final confirmation dialog"},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_protect_message_dialog.png",alt:"Workbook marked as final message"},{type:"paragraph",text:"When a workbook is marked as final, a banner appears indicating that editing is discouraged."},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_protect_final.png",alt:"Workbook marked as final banner"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does Document Inspector help you do?",options:["Check formulas for calculation errors","Fix spelling mistakes throughout the workbook","Find and remove hidden or personal data before sharing","Verify that all cells have the correct number format"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the Inspect and Protect practice workbook.","Run Document Inspector and remove any comments or personal information found.","Close the inspector after removing issues.","Protect the workbook by selecting Mark as Final.","Verify that the 'Marked as Final' banner appears."]},{type:"image",src:"/images/excel/module-3/inspect-protect/inspecting_protect_final.png",alt:"Final workbook marked as final example"}]}],level:"Beginner",estimatedMinutes:45},{moduleNumber:4,moduleSlug:"module-4",title:"Complex Formulas, Functions & Cell References",emoji:"\uD83E\uDDE0",description:"Complex formulas, introduction to functions, and understanding absolute and relative cell references.",lessons:[{slug:"complex-formulas-order-of-operations",title:"Complex Formulas & Order of Operations",description:"Use PEMDAS and parentheses to control calculation order when building multi-step formulas such as subtotals and tax.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/J-W3thqtDpQ",practiceFiles:[{name:"Complex Formulas Practice File",url:"/practice/excel/module-4/complex-formulas/Excel_ComplexFormulas_Practice.xlsx"}],sections:[{heading:"Order of Operations (PEMDAS)",blocks:[{type:"paragraph",text:"When a formula includes multiple operators, Excel follows an order of operations. PEMDAS stands for Parentheses, Exponents, Multiplication, Division, Addition, and Subtraction."},{type:"paragraph",text:"If a result looks incorrect, it is often because Excel evaluated a part of the formula in a different order than you expected."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order1.png",alt:"Using the order of operations (PEMDAS) graphic",caption:"Excel evaluates formulas in this order unless parentheses change it."},{type:"paragraph",text:"Excel evaluates expressions inside parentheses first before moving on to other operations."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order2.png",alt:"Parentheses step highlighted"},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order3.png",alt:"Exponents step highlighted"},{type:"paragraph",text:"After parentheses, Excel evaluates exponents if present."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order4.png",alt:"Multiplication and division step highlighted"},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order5.png",alt:"Division step result"},{type:"paragraph",text:"Multiplication and division are evaluated next, working from left to right."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order6.png",alt:"Addition and subtraction step highlighted"},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order7.png",alt:"Final simplification step"},{type:"paragraph",text:"Finally, Excel performs addition and subtraction from left to right."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_order8.png",alt:"Final answer shown"}]},{heading:"Building a Subtotal Formula",blocks:[{type:"paragraph",text:"A subtotal often involves adding multiple calculations together. In this example, we multiply Unit Price by Quantity for each item, then add the results."},{type:"paragraph",text:"Click the subtotal cell first, then type an equals sign (=) to begin entering your formula."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_subtotal_cell.png",alt:"Subtotal cell selected"},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_subtotal_formula.png",alt:"Subtotal formula entered"},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_subtotal_parentheses.png",alt:"Subtotal formula improved with parentheses"},{type:"paragraph",text:"By adding parentheses, Excel performs the multiplication steps first before summing the results. If your subtotal seems too large or too small, check whether parentheses are controlling the order properly."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_subtotal_result.png",alt:"Subtotal result displayed"}]},{heading:"Calculating Tax Correctly",blocks:[{type:"paragraph",text:"To calculate tax, you typically add totals first, then multiply by the tax rate. Parentheses ensure Excel performs the addition before multiplying."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_tax_formula.png",alt:"Correct tax formula using parentheses"},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_tax_incorrect.png",alt:"Incorrect tax formula without parentheses",caption:"Without parentheses, Excel multiplies before adding, which changes the result."},{type:"paragraph",text:"If your tax calculation is incorrect, check whether Excel multiplied something before completing the addition."},{type:"image",src:"/images/excel/module-4/complex-formulas/complex_tax_result.png",alt:"Correct tax result displayed"}]},{heading:"Key Takeaways",blocks:[{type:"list",ordered:!1,items:["Excel follows PEMDAS automatically.","Use parentheses to control the order of calculations.","Multiplication and division happen before addition and subtraction.","If totals look wrong, check parentheses first."]}]},{heading:"Understanding Excel's Order of Operations (PEMDAS)",blocks:[{type:"paragraph",text:"Excel calculates complex formulas using a specific hierarchy known as the Order of Operations. If you do not understand this hierarchy, your formulas may return unexpected results."},{type:"paragraph",text:"Excel follows PEMDAS: Parentheses, Exponents, Multiplication, Division, Addition, and Subtraction."},{type:"image",src:"/images/excel/module-4/complex-formulas/pemdas-infographic.png",alt:"Excel Order of Operations PEMDAS infographic",caption:"Excel calculates formulas using PEMDAS. Multiplication and division are solved left-to-right, as are addition and subtraction."},{type:"paragraph",text:"When operators share the same priority level—such as multiplication and division—Excel evaluates them from left to right."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"In the formula =2+3*4, what is the result?",options:["20","14","24","11"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice workbook:"},{type:"list",ordered:!0,items:["Download the practice file above.","Click the Challenge worksheet tab in the bottom-left of the workbook."]},{type:"paragraph",text:"Click cell D7 first. Type an equals sign (=) to begin your formula."},{type:"paragraph",text:"In cell D7, create a formula that calculates the tax for the invoice. Use a sales tax rate of 7.5%. (You can enter 7.5% directly, or use 0.075.)"},{type:"paragraph",text:"In cell D8, calculate the total for the order. Use SUM to add cells D3:D7."},{type:"paragraph",text:"In cell D9, calculate the total after a 10% discount. A 10% discount means you pay 90% of the total."},{type:"paragraph",text:"If your totals look too high or too low, double-check your parentheses and percent formatting."},{type:"paragraph",text:"When you are finished, your spreadsheet should look like this:"},{type:"image",src:"/images/excel/module-4/complex-formulas/intro-formulas-final-result.png",alt:"Final expected results for complex formulas challenge"}]},{slug:"relative-and-absolute-cell-references",title:"Relative & Absolute Cell References",description:"Learn how relative, absolute, and mixed references behave when formulas are copied, and how to reference cells across worksheets.",duration:"25 min",videoUrl:"https://www.youtube.com/embed/iDg9s7BJ2m4",practiceFiles:[{name:"Cell References Practice File",url:"/practice/excel/module-4/relative-absolute/Excel_CellReferences_Practice.xlsx"}],sections:[{heading:"Understanding Relative References",blocks:[{type:"paragraph",text:"Relative references are Excel’s default behavior. When a formula is copied, the row and column references adjust automatically."},{type:"paragraph",text:"Click cell D4 first, then type an equals sign (=) to begin entering your formula."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_relative_cell.png",alt:"Selecting first cell for relative reference formula"},{type:"paragraph",text:"Enter the formula =B4*C4 to multiply Unit Price by Quantity."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_relative_formula.png",alt:"Relative reference formula entered"},{type:"image",src:"/images/excel/module-4/relative-absolute/references_relative_result.png",alt:"First relative reference result"},{type:"paragraph",text:"Use the fill handle to copy the formula downward."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_relative_handle.png",alt:"Dragging relative reference fill handle"},{type:"image",src:"/images/excel/module-4/relative-absolute/references_relative_fill.png",alt:"Relative reference copied down"},{type:"paragraph",text:"Notice how each row now references the corresponding unit price and quantity automatically."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_relative_check_v2.png",alt:"Relative references updated correctly"},{type:"paragraph",text:"Because the references were relative, Excel adjusted the row numbers automatically as the formula was copied."}]},{heading:"Locking a Cell with Absolute References",blocks:[{type:"paragraph",text:"If a formula uses a value that should not change — such as a tax rate — we must lock the reference."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_absolute_cell.png",alt:"Selecting cell for absolute reference formula"},{type:"paragraph",text:"Without locking the tax rate in E2, copying the formula causes incorrect results."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_absolute_error.png",alt:"Incorrect calculation without absolute reference"},{type:"paragraph",text:"Because the reference was not locked, Excel shifted the tax rate cell as the formula was copied."},{type:"paragraph",text:"If you ever see your tax rate changing as you copy a formula, it usually means the reference was not locked."},{type:"paragraph",text:"Add dollar signs to lock the reference. $E$2 locks both the column and row. You can also click the cell reference and press F4 to insert the dollar signs automatically."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_absolute_formula.png",alt:"Formula using $E$2 absolute reference"},{type:"paragraph",text:"Now copy the formula down using the fill handle."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_absolute_handle.png",alt:"Dragging absolute reference fill handle"},{type:"image",src:"/images/excel/module-4/relative-absolute/references_absolute_fill.png",alt:"Absolute reference copied correctly"},{type:"image",src:"/images/excel/module-4/relative-absolute/references_absolute_check_v2.png",alt:"Absolute reference remains locked"}]},{heading:"Final Result with Absolute Reference Applied",blocks:[{type:"paragraph",text:"After locking the tax rate and copying the formula down, every row calculates correctly."},{type:"paragraph",text:"The tax rate remains fixed while unit prices and quantities adjust normally."},{type:"image",src:"/images/excel/module-4/relative-absolute/references-absolute-final-result.png",alt:"Final correct results after applying absolute reference"}]},{heading:"Mixed References",blocks:[{type:"paragraph",text:"Excel allows partial locking of either rows or columns. This is called a mixed reference."},{type:"paragraph",text:"Mixed references are commonly used when building structured financial models or multiplication tables."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_absolute_graphic.png",alt:"Graphic showing relative, absolute, and mixed references"},{type:"list",ordered:!1,items:["$A$2 → Fully absolute (row and column locked)","A$2 → Row locked, column relative","$A2 → Column locked, row relative","A2 → Fully relative"]}]},{heading:"Referencing Cells Across Worksheets",blocks:[{type:"paragraph",text:"You can reference cells from another worksheet using the format SheetName!CellAddress."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_sheet_worksheet.png",alt:"Switching worksheets"},{type:"image",src:"/images/excel/module-4/relative-absolute/references_sheet_cell.png",alt:"Selecting cell in another worksheet"},{type:"paragraph",text:"When referencing another worksheet, Excel automatically inserts the sheet name followed by an exclamation point."},{type:"paragraph",text:"If the sheet name contains spaces, Excel will wrap it in single quotation marks. Example: ='Paper Goods'!E13"},{type:"image",src:"/images/excel/module-4/relative-absolute/references_sheet2_formula.png",alt:"Cross-sheet formula entered"},{type:"image",src:"/images/excel/module-4/relative-absolute/references_sheet2_result.png",alt:"Cross-sheet reference result"},{type:"paragraph",text:"If the sheet name or cell reference is incorrect, Excel will return a #REF! error."},{type:"image",src:"/images/excel/module-4/relative-absolute/references_sheet_error.png",alt:"Error when worksheet reference is incorrect"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which symbol makes a cell reference absolute in Excel?",options:["Ampersand (&)","Asterisk (*)","Hash (#)","Dollar sign ($)"],correctIndex:3}]}],challenge:[{type:"list",ordered:!0,items:["Download the Cell References practice workbook.","Click the Paper Goods tab at the bottom-left of the workbook."]},{type:"paragraph",text:"Click cell D4 and begin your formula with =."},{type:"paragraph",text:"In cell D4, enter a formula that multiplies the unit price in B4, the quantity in C4, and the tax rate in E2. Make sure to use an absolute reference for the tax rate ($E$2) because it must remain constant."},{type:"paragraph",text:"Use the fill handle to copy the formula to cells D5:D12."},{type:"paragraph",text:"Change the tax rate in cell E2 to 6.5%. If your totals did not update correctly, check whether E2 was locked properly using $E$2."},{type:"paragraph",text:"When you're finished, your workbook should look like this:"},{type:"image",src:"/images/excel/module-4/relative-absolute/references-absolute-final-result.png",alt:"Completed Paper Goods worksheet with updated tax rate"},{type:"list",ordered:!0,start:6,items:["Click the Catering Invoice tab.","Delete the value in cell C5 and replace it with a reference to the total cost of the paper goods (cell E13 on the Paper Goods worksheet).","Use the same steps to calculate the sales tax for each item on the Menu Order worksheet. The total in cell E14 should update.","In cell C4 of the Catering Invoice worksheet, create a reference to the updated total."]},{type:"paragraph",text:"When you're finished, the Catering Invoice worksheet should look like this:"},{type:"image",src:"/images/excel/module-4/relative-absolute/excel_2016_cell_ref_challenge_edited.png",alt:"Completed Catering Invoice worksheet"}]},{slug:"excel-functions",title:"Working with Functions",description:"Learn how to use Excel functions including SUM, AVERAGE, COUNT, MAX, MIN, COUNTA, and NETWORKDAYS. Understand syntax, arguments, and how to insert functions using AutoSum and the Function Library.",duration:"35 min",videoUrls:["https://www.youtube.com/embed/-9d4m79twdA","https://www.youtube.com/embed/4MxeY2m-hcI"],practiceFiles:[{name:"Functions Practice Workbook",url:"/practice/excel/module-4/functions/Excel_Functions_Practice.xlsx"}],sections:[{heading:"What Is a Function?",blocks:[{type:"paragraph",text:"A function is a predefined formula that performs calculations using specific values in a particular order."},{type:"paragraph",text:"Excel includes many common functions that can quickly calculate totals, averages, counts, maximum values, and minimum values."},{type:"image",src:"/images/excel/module-4/functions/functions_create.png",alt:"Basic SUM function example showing equals sign, function name, and argument"}]},{heading:"Understanding Function Syntax",blocks:[{type:"paragraph",text:"Functions must follow proper syntax: an equals sign (=), the function name, and one or more arguments inside parentheses."},{type:"paragraph",text:"Example: =SUM(A1:A20)"},{type:"paragraph",text:"Arguments can refer to individual cells or cell ranges. Multiple arguments are separated by commas."},{type:"image",src:"/images/excel/module-4/functions/functions_arguments.png",alt:"AVERAGE function example with cell range argument"}]},{heading:"Using the AutoSum Command",blocks:[{type:"paragraph",text:"The AutoSum command automatically inserts common functions such as SUM, AVERAGE, COUNT, MAX, and MIN."},{type:"image",src:"/images/excel/module-4/functions/functions_autosum.png",alt:"AutoSum command dropdown on Ribbon"},{type:"paragraph",text:"Select the cell that will contain the function, choose AutoSum, and Excel will automatically suggest a range."},{type:"image",src:"/images/excel/module-4/functions/functions_autosum_done.png",alt:"SUM function inserted and calculated"},{type:"paragraph",text:"You can also press Alt + = as a shortcut to quickly insert AutoSum."}]},{heading:"Entering a Function Manually",blocks:[{type:"paragraph",text:"If you know the function name, you can type it directly."},{type:"paragraph",text:"Click a cell, type =AVERAGE, and enter the range inside parentheses."},{type:"image",src:"/images/excel/module-4/functions/functions_average.png",alt:"Typing AVERAGE function manually"},{type:"image",src:"/images/excel/module-4/functions/functions_average_range.png",alt:"Selecting range C3:C9 inside AVERAGE"},{type:"image",src:"/images/excel/module-4/functions/functions_average_done.png",alt:"AVERAGE result displayed"}]},{heading:"The Function Library",blocks:[{type:"paragraph",text:"The Function Library on the Formulas tab organizes functions into categories such as Financial, Logical, Text, Date & Time, Lookup & Reference, and Math & Trig."},{type:"image",src:"/images/excel/module-4/functions/functions_formulas_tab.png",alt:"Formulas tab showing Function Library group"},{type:"image",src:"/images/excel/module-4/functions/functions_library.png",alt:"Function Library categories dropdown"}]},{heading:"Using COUNTA",blocks:[{type:"paragraph",text:"COUNTA counts the number of non-empty cells in a range. Unlike COUNT, it counts text as well as numbers."},{type:"image",src:"/images/excel/module-4/functions/functions_counta.png",alt:"Selecting COUNTA from Function Library"},{type:"image",src:"/images/excel/module-4/functions/functions_arguments_dialog.png",alt:"Function Arguments dialog for COUNTA"},{type:"image",src:"/images/excel/module-4/functions/functions_counta_done.png",alt:"COUNTA formula result"}]},{heading:"Using Insert Function & NETWORKDAYS",blocks:[{type:"paragraph",text:"The Insert Function command allows you to search for functions using keywords."},{type:"image",src:"/images/excel/module-4/functions/functions_insert_function_command.png",alt:"Insert Function button"},{type:"image",src:"/images/excel/module-4/functions/functions_insert_dialog.png",alt:"Insert Function search dialog"},{type:"paragraph",text:"In this example, we use NETWORKDAYS to calculate business days between two dates."},{type:"image",src:"/images/excel/module-4/functions/functions_arguments_done.png",alt:"NETWORKDAYS function arguments completed"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which function adds all values in the range A1:A10?",options:["=ADD(A1:A10)","=TOTAL(A1:A10)","=SUM(A1:A10)","=COUNT(A1:A10)"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks using the practice workbook:"},{type:"list",ordered:!0,items:["Download the Functions practice workbook.","Click the Challenge worksheet tab.","In cell F3, insert a function to calculate the average of the four scores in cells B3:E3.","Use the fill handle to copy the function from F3 to cells F4:F17.","In cell B18, use AutoSum to calculate the lowest score in B3:B17.","In cell B19, use the Function Library (More Functions > Statistical) to calculate the median of B3:B17.","In cell B20, create a function to calculate the highest score in B3:B17.","Copy the functions in B18:B20 across to C18:F20 using the fill handle."]},{type:"image",src:"/images/excel/module-4/functions/functions_final_result.png",alt:"Final practice result shown in worksheet"}]}],level:"Intermediate",estimatedMinutes:50},{moduleNumber:5,moduleSlug:"module-5",title:"Working with Data",emoji:"\uD83D\uDCCA",description:"Sorting, filtering, tables, charts, and conditional formatting.",lessons:[{slug:"basic-tips-working-with-data",title:"Basic Tips for Working with Data",description:"Learn how Excel helps you organize, sort, filter, summarize, and visualize large amounts of information efficiently.",duration:"6 min",sections:[{heading:"Introduction",blocks:[{type:"paragraph",text:"Excel workbooks are designed to store a large amount of information. Whether you are working with 20 rows or 20,000, Excel includes powerful tools to help you organize your data and quickly find what you need."},{type:"paragraph",text:"Instead of manually scanning thousands of cells, you can use built-in features like freezing panes, sorting, filtering, subtotals, tables, charts, and conditional formatting to work smarter."}]},{heading:"Freezing Rows and Columns",blocks:[{type:"paragraph",text:"When working with large datasets, header rows can scroll off the screen. Freezing panes keeps important rows or columns visible while you scroll."},{type:"paragraph",text:"This is especially useful for date headers, employee names, or product categories."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-freeze.png",alt:"Example of freezing top rows in Excel",caption:"Freezing panes allows header rows to remain visible while scrolling."}]},{heading:"Sorting Data",blocks:[{type:"paragraph",text:"Sorting reorganizes your worksheet so that data appears in a specific order. You can sort alphabetically, numerically, by date, or even by color."},{type:"paragraph",text:"For example, you might sort a customer list by last name or sales data from highest to lowest."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-sort.png",alt:"Sorting data example"}]},{heading:"Filtering Data",blocks:[{type:"paragraph",text:"Filters allow you to narrow down a worksheet to display only the information that meets certain criteria."},{type:"paragraph",text:"Instead of deleting rows, filtering temporarily hides data that does not match your selection."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-filter.png",alt:"Filtering dropdown menu example",caption:"Filtering shows only rows that match selected criteria."}]},{heading:"Summarizing Data with Subtotals",blocks:[{type:"paragraph",text:"The Subtotal command automatically groups data and calculates totals for each category."},{type:"paragraph",text:"This is useful when analyzing grouped information such as sales by region or inventory by category."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-summarize.png",alt:"Subtotal grouping example"}]},{heading:"Formatting Data as a Table",blocks:[{type:"paragraph",text:"Formatting data as a table improves both appearance and functionality. Tables include built-in filtering and sorting, and they automatically expand when new data is added."},{type:"paragraph",text:"Excel includes predefined table styles that make formatting fast and consistent."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-formatting.png",alt:"Formatting data as a table example"}]},{heading:"Visualizing Data with Charts",blocks:[{type:"paragraph",text:"Large datasets can be difficult to interpret at a glance. Charts transform raw numbers into visual comparisons and trends."},{type:"paragraph",text:"Charts are useful for identifying patterns, growth, declines, and performance differences."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-visualize.png",alt:"Excel chart example"}]},{heading:"Conditional Formatting",blocks:[{type:"paragraph",text:"Conditional formatting automatically changes the appearance of cells based on their values."},{type:"paragraph",text:"You can apply color scales, data bars, or icons to quickly highlight trends and outliers."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-conditional-format.png",alt:"Conditional formatting with icons example"}]},{heading:"Using Find and Replace",blocks:[{type:"paragraph",text:"When working with large worksheets, locating specific information can be time-consuming."},{type:"paragraph",text:"The Find feature searches your workbook instantly. Replace allows you to modify multiple instances of text at once."},{type:"image",src:"/images/excel/module-5/basic-tips-data/basic-tips-data-find-replace.png",alt:"Find and Replace dialog box"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which Excel feature highlights cells based on rules you define?",options:["Data Validation","Sparklines","Conditional Formatting","Cell Styles"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using a worksheet with at least 20 rows of data, complete the following:"},{type:"list",ordered:!0,items:["Freeze the top row so headers remain visible.","Sort one column alphabetically or numerically.","Apply a filter to display only specific rows.","Format the dataset as a table.","Create a chart to visualize one column of numeric data.","Apply conditional formatting to highlight the highest values.","Use Find and Replace to change one repeated value in the worksheet."]}]},{slug:"freezing-panes-view-options",title:"Freezing Panes and View Options",description:"Learn how to freeze rows and columns, split worksheets, and open multiple windows to compare data more effectively.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/zuhsUNBeNHw",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-5/freezing/Excel_FreezePanes_Practice.xlsx"}],sections:[{heading:"Why Freeze Panes and View Tools Matter",blocks:[{type:"paragraph",text:"As spreadsheets grow larger, important information like headers and identifiers can disappear when scrolling. Excel provides Freeze Panes, Split, and New Window tools to improve navigation and comparison."},{type:"image",src:"/images/excel/module-5/freezing/freezing_rows_example.png",alt:"Large dataset requiring freeze panes"}]},{heading:"Freeze the Top Row",blocks:[{type:"paragraph",text:"If your headers are in Row 1, use Freeze Top Row to keep them visible while scrolling."},{type:"image",src:"/images/excel/module-5/freezing/freezing_top_row.png",alt:"Freeze Top Row command"},{type:"image",src:"/images/excel/module-5/freezing/freezing_row.png",alt:"Top row frozen example",caption:"Row 1 remains visible even as you scroll down."}]},{heading:"Freeze Multiple Rows",blocks:[{type:"paragraph",text:"To freeze more than one row, select the row below the rows you want frozen, then choose Freeze Panes."},{type:"image",src:"/images/excel/module-5/freezing/freezing_panes.png",alt:"Freeze Panes dropdown"},{type:"image",src:"/images/excel/module-5/freezing/freezing_panes(1).png",alt:"Multiple rows frozen"}]},{heading:"Freeze Columns",blocks:[{type:"paragraph",text:"To freeze columns, select the column to the right of the columns you want frozen."},{type:"image",src:"/images/excel/module-5/freezing/freezing_columns.png",alt:"Freeze columns selection"},{type:"image",src:"/images/excel/module-5/freezing/freezing_column_frozen.png",alt:"Column frozen result",caption:"The first column stays visible while scrolling horizontally."}]},{heading:"Unfreeze Panes",blocks:[{type:"paragraph",text:"To remove any freeze settings, go to View → Freeze Panes → Unfreeze Panes."},{type:"image",src:"/images/excel/module-5/freezing/freezing_unfreeze.png",alt:"Unfreeze command"}]},{heading:"Open a New Window",blocks:[{type:"paragraph",text:"Excel allows you to open a second window of the same workbook for comparison."},{type:"image",src:"/images/excel/module-5/freezing/freezing_new_window.png",alt:"New Window command"},{type:"image",src:"/images/excel/module-5/freezing/freezing_new_window_compare.png",alt:"Two windows open side by side"}]},{heading:"Arrange All Windows",blocks:[{type:"paragraph",text:"Use Arrange All to automatically tile workbook windows for comparison."},{type:"image",src:"/images/excel/module-5/freezing/freezing_arrange_all.png",alt:"Arrange All dialog"}]},{heading:"Split a Worksheet",blocks:[{type:"paragraph",text:"The Split command divides your worksheet into panes that scroll independently."},{type:"image",src:"/images/excel/module-5/freezing/freezing_split_origin.png",alt:"Before split applied"},{type:"image",src:"/images/excel/module-5/freezing/freezing_split_command.png",alt:"Split command"},{type:"image",src:"/images/excel/module-5/freezing/freezing_split_done.png",alt:"Split applied"},{type:"image",src:"/images/excel/module-5/freezing/freezing_split_final_result.png",alt:"Final split view",caption:"Each pane scrolls independently for comparison."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does freezing the top row in Excel do?",options:["Prevents the row from being edited","Locks the row so it cannot be deleted","Keeps the header row visible when you scroll down","Applies bold formatting to all cells in the row"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Within our example file, there is a LOT of sales data. For this challenge, we want to compare data for different years side by side. To do this:"},{type:"list",ordered:!0,items:["Download our practice workbook.","Open a new window for your workbook.","Freeze First Column and use the horizontal scroll bar to look at sales from 2015.","Unfreeze the first column.","Select cell G17 and click Split to split the worksheet into multiple panes. Hint: This should split the worksheet between rows 16 and 17 and columns F and G.","Use the horizontal scroll bar in the bottom-right of the window to move the worksheet so Column N, which contains data for January 2015, is next to Column F.","Open a new window for your workbook and select the 2012-2013 Sales tab.","Move your windows so they are side by side. Now you’re able to compare data for similar months from several different years. Your screen should look something like this:"]},{type:"image",src:"/images/excel/module-5/freezing/freezing_split_final_result.png",alt:"Two Excel windows side by side for comparing sales data across years",caption:"Goal: two workbook windows arranged side-by-side so you can compare the same months across different years."}]},{slug:"sorting-data",title:"Sorting Data",description:"Learn how to sort text, numbers, and custom lists in Excel. Master basic sorting, multi-level sorting, and logical ordering using the Sort dialog box.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/Ep5q1cUhQas",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-5/sorting/Excel_Sorting_Practice.xlsx"}],sections:[{heading:"Understanding Sorting in Excel",blocks:[{type:"paragraph",text:"Sorting reorganizes your dataset based on the values in one or more columns. Instead of manually rearranging rows, Excel automatically moves entire records together so your data remains aligned."},{type:"paragraph",text:"You can sort alphabetically, numerically, by date, or by a custom logical order such as T-shirt sizes."}]},{heading:"Step 1: Select a Cell Inside Your Dataset",blocks:[{type:"paragraph",text:"Before sorting, click anywhere inside your dataset. Excel will automatically detect the surrounding data range."},{type:"paragraph",text:"If you select only one column instead of the entire dataset, you risk misaligning rows and corrupting your data."},{type:"image",src:"/images/excel/module-5/sorting/sorting_cell_range.png",alt:"Selecting a cell inside the dataset"}]},{heading:"Step 2: Locate the Sort Commands",blocks:[{type:"paragraph",text:"Sorting tools are located on the Data tab inside the Sort & Filter group."},{type:"image",src:"/images/excel/module-5/sorting/sorting_ribbon.png",alt:"Sort & Filter group on Data tab"},{type:"paragraph",text:"There are two quick-sort buttons (A–Z and Z–A) and a full Sort button for advanced options."}]},{heading:"Basic Sorting: A to Z",blocks:[{type:"paragraph",text:"The A–Z button sorts text alphabetically (A to Z), numbers from smallest to largest, and dates from oldest to newest."},{type:"image",src:"/images/excel/module-5/sorting/sorting_a-z.png",alt:"A to Z sorting command"},{type:"paragraph",text:"After clicking A–Z, Excel reorganizes the entire dataset based on the selected column."},{type:"image",src:"/images/excel/module-5/sorting/sorting_a-z_done.png",alt:"Dataset sorted A to Z"}]},{heading:"Basic Sorting: Z to A",blocks:[{type:"paragraph",text:"The Z–A button reverses the order. It sorts text from Z to A, numbers from largest to smallest, and dates from newest to oldest."},{type:"paragraph",text:"This is useful when identifying top performers, highest values, or most recent entries."}]},{heading:"Using the Sort Dialog for More Control",blocks:[{type:"paragraph",text:"For advanced sorting, click the Sort button instead of the A–Z icons."},{type:"image",src:"/images/excel/module-5/sorting/sorting_sort_command.png",alt:"Sort command button"},{type:"paragraph",text:"The Sort dialog box allows you to choose specific columns and define custom sorting rules."},{type:"image",src:"/images/excel/module-5/sorting/sorting_dialog.png",alt:"Sort dialog box"},{type:"paragraph",text:"If your dataset includes headers, ensure 'My data has headers' is checked so Excel recognizes column names."}]},{heading:"Multi-Level Sorting",blocks:[{type:"paragraph",text:"Multi-level sorting allows you to sort by more than one column. Excel sorts by the first column, then breaks ties using the second column."},{type:"paragraph",text:"For example, you could sort by Homeroom number first, then by Last Name."},{type:"image",src:"/images/excel/module-5/sorting/sorting_add_level_dialog.png",alt:"Add Level in Sort dialog"},{type:"paragraph",text:"Use Add Level to introduce another sorting rule. You can adjust priority using Move Up or Move Down."},{type:"image",src:"/images/excel/module-5/sorting/sorting_add_level_move_up-down.png",alt:"Move Up and Move Down sorting levels"},{type:"image",src:"/images/excel/module-5/sorting/sorting_add_level_sorted.png",alt:"Multi-level sorted result"}]},{heading:"Sorting with Custom Lists",blocks:[{type:"paragraph",text:"Alphabetical order is not always logical. For example, T-shirt sizes should follow Small, Medium, Large, X-Large — not alphabetical order."},{type:"paragraph",text:"To create a logical order, use Custom Lists."},{type:"image",src:"/images/excel/module-5/sorting/sorting_dialog_order.png",alt:"Order dropdown showing Custom List option"},{type:"image",src:"/images/excel/module-5/sorting/sorting_custom_lists_dialog.png",alt:"Custom Lists dialog window"},{type:"paragraph",text:"Enter your logical sequence (Small, Medium, Large, X-Large) and click Add."},{type:"image",src:"/images/excel/module-5/sorting/sorting_custom_lists_selected.png",alt:"Custom list selected"},{type:"image",src:"/images/excel/module-5/sorting/sorting_custom_lists_sorted.png",alt:"Dataset sorted using custom list"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What type of sort would you use to organize a list from A to Z?",options:["Descending sort","Custom sort","Ascending sort","Multi-level sort"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Download and open the practice workbook provided for this lesson."},{type:"list",ordered:!0,items:["Click the Challenge tab at the bottom of the workbook.","For the main table, create a custom sort that sorts by Grade from Smallest to Largest and then by Camper Name from A to Z.","Create a second sort for the Additional Information section. Sort by Counselor (Column H) from A to Z.","Ensure the entire dataset moves together without misaligning rows.","When finished, your workbook should match the example shown below."]},{type:"image",src:"/images/excel/module-5/sorting/sorting_final_result.png",alt:"Final sorted challenge result",caption:"Final result after applying multi-level sorting and sorting the Additional Information section."}]},{slug:"filtering-data",title:"Filtering Data",description:"Learn how to filter lists and tables to show only the records you need. Use checkbox filters, search, text/number/date filters, and clear filters confidently.",duration:"14 min",videoUrl:"https://www.youtube.com/embed/_OdsZR_rL1U",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-5/filtering/Excel_Filtering_Practice.xlsx"}],sections:[{heading:"Why Filters Matter",blocks:[{type:"paragraph",text:"When a worksheet has a lot of rows, it’s hard (and honestly pointless) to scroll forever hunting for what you need. Filters let you temporarily hide rows that don’t match your criteria—without deleting anything."},{type:"paragraph",text:"Filters are perfect for finding items by category, narrowing to specific dates, or showing only records that meet a numeric requirement (like loan amounts over $100)."}]},{heading:"Before You Filter: Make Sure You Have Headers",blocks:[{type:"paragraph",text:"Filtering works best when your data has a clear header row (column names like ID#, Type, Item Description, etc.). Excel uses these headers to label each filter dropdown."},{type:"image",src:"/images/excel/module-5/filtering/filtering_header.png",alt:"Dataset with header row and filter dropdown arrows",caption:"Headers identify each column so Excel can filter correctly."}]},{heading:"Turn Filters On",blocks:[{type:"paragraph",text:"To enable filtering, go to the Data tab and click the Filter button. Excel adds a dropdown arrow to each header cell."},{type:"image",src:"/images/excel/module-5/filtering/filtering_data_tab_filter.png",alt:"Data tab Filter command"},{type:"paragraph",text:"Once filters are on, every column header gets a dropdown arrow you can click to filter that column."},{type:"image",src:"/images/excel/module-5/filtering/filtering_dropdown_arrow.png",alt:"Filter dropdown arrow in a table header"},{type:"paragraph",text:"You can also access Filter from the Home tab under Sort & Filter (different path, same tool)."},{type:"image",src:"/images/excel/module-5/filtering/filtering_sort_filter_alt.png",alt:"Home tab Sort & Filter menu showing Filter option"}]},{heading:"Basic Filtering with Checkboxes",blocks:[{type:"paragraph",text:"The simplest filter is the checkbox list. You open the filter dropdown, uncheck everything, then check only what you want to see."},{type:"paragraph",text:"Example: Filter the Type column to show only Laptop and Projector."},{type:"image",src:"/images/excel/module-5/filtering/filtering_menu.png",alt:"Filter menu dropdown showing checkbox list",caption:"The filter menu shows sorting at the top and checkbox filtering at the bottom."},{type:"paragraph",text:"First, uncheck Select All so you can start from a clean slate."},{type:"image",src:"/images/excel/module-5/filtering/filtering_uncheck.png",alt:"Unchecking Select All in a filter menu"},{type:"paragraph",text:"Then check only the values you want and click OK. Excel hides everything else."},{type:"image",src:"/images/excel/module-5/filtering/filtering_filtered.png",alt:"Filtered dataset after choosing values",caption:"Only rows matching the selected values remain visible."}]},{heading:"Applying Multiple Filters (Filters Stack)",blocks:[{type:"paragraph",text:"Filters are cumulative—meaning each new filter further narrows your results. This is how you go from “a lot of rows” to “exactly what I need.”"},{type:"paragraph",text:"Example: If you already filtered Type to Laptop + Projector, you can ALSO filter Checked Out to show only items checked out in August."},{type:"image",src:"/images/excel/module-5/filtering/filtering_multiple_filters.png",alt:"Applying another filter on a date column"},{type:"paragraph",text:"After applying that second filter, you’ll see a smaller subset that matches BOTH criteria."},{type:"image",src:"/images/excel/module-5/filtering/filtering_new_filter.png",alt:"New filter applied on top of an existing filter",caption:"Multiple filters narrow the list step-by-step."}]},{heading:"Clearing a Filter (Without Turning Filters Off)",blocks:[{type:"paragraph",text:"When you’re done with a filter, don’t panic-scroll. Just clear it."},{type:"paragraph",text:"Open the dropdown for the filtered column and choose Clear Filter From [Column Name]. That restores the hidden rows for that column’s filter."},{type:"image",src:"/images/excel/module-5/filtering/filtering_filter_menu.png",alt:"Clear Filter option in a filter dropdown"},{type:"paragraph",text:"If you want to remove ALL filters from the sheet at once, click Filter again on the Data tab to toggle filtering off."}]},{heading:"Filtering with Search",blocks:[{type:"paragraph",text:"Search is the fastest way to filter when you’re looking for one brand, keyword, or repeated term."},{type:"paragraph",text:"Open the filter dropdown for the column you want (like Equipment Detail), then type into the search box. Excel narrows the checkbox list automatically as you type."},{type:"image",src:"/images/excel/module-5/filtering/filtering_search.png",alt:"Filter search box inside dropdown"},{type:"paragraph",text:"Example: Type saris to show only Saris items."},{type:"image",src:"/images/excel/module-5/filtering/filtering_filtered_search.png",alt:"Search term applied inside the filter dropdown"},{type:"image",src:"/images/excel/module-5/filtering/filtering_laptop_search.png",alt:"Filtered results after search is applied",caption:"After clicking OK, the worksheet updates to show only matching rows."}]},{heading:"Advanced Text Filters (Contains / Does Not Contain)",blocks:[{type:"paragraph",text:"When checkboxes and search aren’t specific enough, use Text Filters. These let you filter based on rules like Begins With, Ends With, Contains, or Does Not Contain."},{type:"paragraph",text:"Example: Exclude items that contain the word laptop."},{type:"image",src:"/images/excel/module-5/filtering/filtering_does_not_contain.png",alt:"Text Filters menu showing Does Not Contain"},{type:"paragraph",text:"This opens a Custom AutoFilter box where you type the word or phrase and confirm."},{type:"image",src:"/images/excel/module-5/filtering/filtering_menu_between.png",alt:"Custom AutoFilter dialog for a text rule"}]},{heading:"Advanced Number Filters (Greater Than / Between)",blocks:[{type:"paragraph",text:"Number Filters are used for columns with numeric values like ID numbers, quantities, prices, or loan amounts."},{type:"paragraph",text:"You can filter values greater than, less than, between two numbers, top 10, above average, and more."},{type:"image",src:"/images/excel/module-5/filtering/filtering_number_filter.png",alt:"Number Filters menu showing Between option"},{type:"paragraph",text:"Example: Show only records with ID numbers between 3000 and 6000."}]},{heading:"Advanced Date Filters (This Month / Between Dates)",blocks:[{type:"paragraph",text:"Date filters are built for time-based data. You can filter by year, month, or use built-in ranges like Last Week, Next Month, or Between two dates."},{type:"paragraph",text:"Example: Filter Checked Out to show only items checked out between two specific dates."},{type:"image",src:"/images/excel/module-5/filtering/filtering_date_filters.png",alt:"Date Filters menu showing Between option"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does applying a filter to a column do?",options:["Permanently deletes rows that do not match the filter","Sorts the column in ascending order automatically","Shows only rows that match the selected criteria","Highlights matching cells with a color"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Download and open the practice workbook."},{type:"list",ordered:!0,items:["Click the Challenge tab in the bottom-left of the workbook.","Apply a filter to show only Electronics and Instruments.","Use the Search feature to filter item descriptions that contain the word Sansei (you should see 6 entries).","Clear the Item Description filter.","Using a number filter, show loan amounts greater than or equal to $100.","Filter to show only items that have deadlines in 2016.","When you're finished, your workbook should look like the example below."]},{type:"image",src:"/images/excel/module-5/filtering/filtering_final_result.png",alt:"Final filtering challenge result",caption:"Final result after applying item type, search, number, and date filters."}]},{slug:"groups-and-subtotals",title:"Groups and Subtotals",description:"Learn how to organize large datasets using grouping and automatically summarize data with the Subtotal command.",duration:"15 min",videoUrl:"https://www.youtube.com/embed/7JJOBFSHbZk",practiceFiles:[{name:"Download Practice Workbook",url:"/files/excel/Excel_Subtotals_Practice.xlsx"}],sections:[{heading:"Why Groups and Subtotals Matter",blocks:[{type:"paragraph",text:"Large datasets can quickly become overwhelming. Groups and Subtotals allow you to organize data into collapsible sections and automatically calculate summaries such as totals, counts, or averages."},{type:"paragraph",text:"When subtotals are applied, Excel creates an outline structure that lets you expand or collapse levels of detail."}]},{heading:"Grouping Rows or Columns",blocks:[{type:"paragraph",text:"You can manually group selected rows or columns to create collapsible sections."},{type:"list",ordered:!0,items:["Select the rows or columns you want to group.","Go to the Data tab.","Click the Group command in the Outline group."]},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_group_command.png",alt:"Group command on Data tab"},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_grouped_range.png",alt:"Grouped columns example",caption:"Selected columns are grouped and can now be collapsed."}]},{heading:"Hide and Show Detail",blocks:[{type:"paragraph",text:"Once data is grouped, minus (-) and plus (+) buttons appear to the left of the worksheet."},{type:"paragraph",text:"Click the minus sign to collapse (hide) detail. Click the plus sign to expand (show) detail."},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_hide.png",alt:"Hide detail button"},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_hidden.png",alt:"Collapsed group view"}]},{heading:"Important: Sort Before Using Subtotal",blocks:[{type:"paragraph",text:"Before creating subtotals, you must sort your data by the column you plan to group by."},{type:"paragraph",text:"For example, if you want to subtotal by T-Shirt Size, sort the worksheet by T-Shirt Size first."},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_sort.png",alt:"Sorting data before subtotaling"}]},{heading:"Creating a Subtotal",blocks:[{type:"list",ordered:!0,items:["Sort your worksheet by the column you want to subtotal.","Go to the Data tab.","Click Subtotal."]},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_subtotal_command.png",alt:"Subtotal command on Data tab"},{type:"paragraph",text:"In the Subtotal dialog box:"},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_subtotal_count_fx.png",alt:"Subtotal dialog showing Count function"},{type:"paragraph",text:"• At each change in: Select the grouping column (e.g., T-Shirt Size)\n• Use function: Choose COUNT, SUM, AVERAGE, etc.\n• Add subtotal to: Select the column to calculate"},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_t-shirt_size.png",alt:"Subtotal dialog selecting T-Shirt Size"}]},{heading:"Understanding Outline Levels",blocks:[{type:"paragraph",text:"After applying subtotals, Excel creates outline levels on the left side of the worksheet."},{type:"paragraph",text:"Level 1 shows only the Grand Total.\nLevel 2 shows subtotal rows.\nLevel 3 shows all detailed data."},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_group_level_1.png",alt:"Level 1 outline"},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_group_level_2.png",alt:"Level 2 outline"},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_group_level_3.png",alt:"Level 3 outline"},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_result_full_view.png",alt:"Full subtotal result"}]},{heading:"Removing Subtotals",blocks:[{type:"paragraph",text:"To remove subtotals entirely:"},{type:"list",ordered:!0,items:["Go to Data → Subtotal.","Click Remove All."]},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_subtotal_remove_all.png",alt:"Remove All in Subtotal dialog"}]},{heading:"Clearing Groups Without Removing Data",blocks:[{type:"paragraph",text:"If you want to remove grouping but keep the data, use Clear Outline."},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_ungroup_clear_outline.png",alt:"Clear Outline option"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does the Subtotal command do?",options:["Sorts the dataset alphabetically before calculating","Removes duplicate rows from the dataset","Automatically calculates summary values (sum, average, etc.) for grouped data","Converts a data range into an Excel Table"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Download the practice workbook and complete the following:"},{type:"list",ordered:!0,items:["Click the Challenge tab.","Sort the worksheet by Grade from Smallest to Largest.","Use Subtotal to group at each change in Grade.","Use the SUM function.","Add subtotals to Amount Raised.","Select outline Level 2 so only subtotals and the grand total appear."]},{type:"image",src:"/images/excel/module-5/groups-subtotals/groups-subtotals_group_level_2.png",alt:"Challenge final subtotal view",caption:"Final result should display subtotal rows and the grand total only."}]},{slug:"conditional-formatting",title:"Conditional Formatting",description:"Automatically highlight patterns, trends, and performance using Conditional Formatting rules, color scales, data bars, and icon sets.",duration:"15 min",videoUrl:"https://www.youtube.com/embed/zfQ8uOBoIj8",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-5/conditional-formatting/Excel_ConditionalFormatting_Practice.xlsx"}],sections:[{heading:"Why Conditional Formatting Matters",blocks:[{type:"paragraph",text:"When working with large datasets, it can be difficult to identify trends and performance issues just by reading numbers. Conditional Formatting automatically applies visual styling based on cell values so patterns become instantly visible."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_example.png",alt:"Example of conditional formatting applied to sales data"}]},{heading:"Step 1: Select the Desired Cells",blocks:[{type:"paragraph",text:"Before applying Conditional Formatting, select the range of cells you want to evaluate."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_selected_range.png",alt:"Selecting cells before applying conditional formatting"}]},{heading:"Highlight Cells Greater Than a Value",blocks:[{type:"paragraph",text:"To highlight values greater than a specific number, use the Highlight Cells Rules option."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_highlight_greater_than.png",alt:"Highlight Cells Rules Greater Than option"},{type:"paragraph",text:"Enter the comparison value (e.g., 4000) and choose a preset style such as Green Fill with Dark Green Text."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_green_fill.png",alt:"Greater Than dialog box with 4000 entered"},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_green_fill_done.png",alt:"Cells highlighted with green formatting",caption:"Values above the threshold are automatically highlighted."}]},{heading:"Using Color Scales",blocks:[{type:"paragraph",text:"Color Scales apply a gradient based on cell values. Highest values receive one color, lowest receive another, and middle values are blended between them."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_color_scales.png",alt:"Color scale preset applied to dataset"}]},{heading:"Using Data Bars",blocks:[{type:"paragraph",text:"Data Bars visually represent values inside each cell using horizontal bars, similar to a mini bar chart."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_data_bar.png",alt:"Data bars applied to dataset"}]},{heading:"Using Icon Sets",blocks:[{type:"paragraph",text:"Icon Sets add symbols such as arrows, circles, or indicators based on value ranges. These are useful for performance dashboards."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_icon_sets.png",alt:"Icon Sets menu"},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_icon_done.png",alt:"Icon set applied to dataset"}]},{heading:"Managing and Editing Rules",blocks:[{type:"paragraph",text:"Use Manage Rules to edit, delete, or prioritize formatting rules applied to a worksheet."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_delete_rule.png",alt:"Conditional Formatting Rules Manager"}]},{heading:"Clearing Conditional Formatting",blocks:[{type:"paragraph",text:"To remove formatting, click Conditional Formatting → Clear Rules, then choose whether to clear from selected cells or the entire sheet."},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_clear_rules.png",alt:"Clear Rules menu"},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_removed.png",alt:"Worksheet after conditional formatting removed"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which Conditional Formatting option fills cells with a color gradient based on their value?",options:["Highlight Cells Rules","Icon Sets","Data Bars","Color Scales"],correctIndex:3}]}],challenge:[{type:"paragraph",text:"Download and open the practice workbook. Then complete the following:"},{type:"list",ordered:!0,items:["Click the Challenge worksheet tab.","Select cells B3:J17.","Apply Conditional Formatting to highlight values Less Than 70 using a light red fill.","Apply the Icon Set called 3 Symbols (Circled).","Use Manage Rules to remove the light red fill rule but keep the icon set.","Your worksheet should match the example shown below."]},{type:"image",src:"/images/excel/module-5/conditional-formatting/conditional-formatting_final_result.png",alt:"Final conditional formatting challenge result",caption:"Final result showing icon set applied while red fill rule has been removed."}]}],level:"Intermediate",estimatedMinutes:50},{moduleNumber:6,moduleSlug:"module-6",title:"Tables, Charts & PivotTables",emoji:"\uD83D\uDCC8",description:"Structure data with tables, visualize insights with charts, and summarize information using PivotTables.",lessons:[{slug:"working-with-tables",title:"Working with Tables",description:"Learn how to convert datasets into Excel tables, apply styles, add rows automatically, and manage structured data more efficiently.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/iroIA8_3soo",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-6/tables/Excel_Tables_Practice.xlsx"}],sections:[{heading:"Why Tables Matter",blocks:[{type:"paragraph",text:"Excel tables transform ordinary cell ranges into structured datasets. Once data is converted into a table, Excel automatically enables sorting, filtering, and consistent formatting."},{type:"paragraph",text:"Tables are widely used in financial reports, inventory lists, employee records, and sales tracking because they keep large datasets organized."},{type:"image",src:"/images/excel/module-6/tables/tables_cells.png",alt:"Dataset before converting to table"}]},{heading:"Formatting Data as a Table",blocks:[{type:"paragraph",text:"To create a table, first select any cell inside your dataset. Excel will automatically detect the surrounding data range."},{type:"image",src:"/images/excel/module-6/tables/tables_cells.png",alt:"Selecting a cell within dataset"},{type:"paragraph",text:"Next, go to the Home tab and click Format as Table."},{type:"image",src:"/images/excel/module-6/tables/tables_format_as_table.png",alt:"Format as Table command"},{type:"paragraph",text:"Choose one of the available table styles from the gallery."},{type:"image",src:"/images/excel/module-6/tables/tables_select_table_style.png",alt:"Selecting a table style"}]},{heading:"Confirm the Table Range",blocks:[{type:"paragraph",text:"After selecting a table style, Excel displays the Create Table dialog box where you confirm the selected range."},{type:"paragraph",text:"If your dataset contains column headers, make sure the My Table Has Headers option is checked."},{type:"image",src:"/images/excel/module-6/tables/tables_dialog.png",alt:"Create Table dialog box"},{type:"image",src:"/images/excel/module-6/tables/tables_headers.png",alt:"Table headers enabled"}]},{heading:"Table Style Applied",blocks:[{type:"paragraph",text:"After confirming the dialog box, Excel converts the dataset into a formatted table."},{type:"image",src:"/images/excel/module-6/tables/tables_table_style_selected.png",alt:"Dataset formatted as a table"},{type:"paragraph",text:"Table styles include alternating row colors, filter dropdowns, and consistent formatting across the dataset."}]},{heading:"Using the Table Design Tab",blocks:[{type:"paragraph",text:"Once a table is created, Excel adds a Table Design tab to the ribbon. This tab contains tools for customizing the table."},{type:"image",src:"/images/excel/module-6/tables/tables_design_tab.png",alt:"Table Design tab"},{type:"paragraph",text:"You can use the Table Styles section to quickly apply a new visual style."},{type:"image",src:"/images/excel/module-6/tables/tables_design_tab_style.png",alt:"Table styles inside design tab"},{type:"image",src:"/images/excel/module-6/tables/tables_more.png",alt:"More table styles menu"}]},{heading:"Adding New Rows",blocks:[{type:"paragraph",text:"One powerful feature of Excel tables is automatic expansion. When you add new rows directly below the table, Excel automatically includes them in the table structure."},{type:"image",src:"/images/excel/module-6/tables/tables_new_row.png",alt:"Adding new row to table"},{type:"image",src:"/images/excel/module-6/tables/tables_new_rows_columns.png",alt:"Table expanding with new rows"},{type:"image",src:"/images/excel/module-6/tables/tables_new_content.png",alt:"New data added to table"}]},{heading:"Deleting Rows from a Table",blocks:[{type:"paragraph",text:"Rows inside a table can be deleted just like normal rows. Excel automatically adjusts the table size after deletion."},{type:"image",src:"/images/excel/module-6/tables/tables_deleted_row.png",alt:"Row deleted from table"}]},{heading:"Convert Table Back to a Range",blocks:[{type:"paragraph",text:"If you no longer need table functionality, you can convert the table back to a standard cell range."},{type:"image",src:"/images/excel/module-6/tables/tables_convert_to_range.png",alt:"Convert table to range command"},{type:"image",src:"/images/excel/module-6/tables/tables_clear.png",alt:"Table formatting removed"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is one advantage of converting a data range to an Excel Table?",options:["The table locks cells so no one can edit them","New rows added at the bottom are automatically included in the table","Formulas are converted to plain text for safety","The table removes duplicate values automatically"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Download the practice workbook and complete the following steps:"},{type:"list",ordered:!0,items:["Open the Challenge worksheet.","Select the entire dataset.","Format the data as a table using a Medium style.","Add a new row at the bottom of the table.","Enter sample data for the new row.","Delete one row from the table.","Change the table style using the Table Design tab.","When finished, your table should look similar to the example below."]},{type:"image",src:"/images/excel/module-6/tables/tables_final_result.png",alt:"Completed Excel table example",caption:"Final result after formatting the dataset as a table and modifying rows."}]},{slug:"charts",title:"Creating Charts in Excel",description:"Learn how to visualize data in Excel using charts. Charts help transform raw numbers into visual insights that make trends, comparisons, and patterns easier to understand.",duration:"30 min",videoUrl:"https://www.youtube.com/embed/_Wu7jYTr1Pk",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-6/charts/Excel_Charts_Practice.xlsx"}],sections:[{heading:"Why Charts Matter",blocks:[{type:"paragraph",text:"Charts turn raw numbers into something your brain can understand in two seconds. They help you spot trends, compare categories, and present data clearly in reports."},{type:"image",src:"/images/excel/module-6/charts/chart_final_result.png",alt:"Final chart example",caption:"A finished chart should clearly communicate the story your data is telling."}]},{heading:"Common Chart Types",blocks:[{type:"paragraph",text:"Excel offers many chart types. The key is choosing the one that matches your goal: compare categories, show change over time, or show parts of a whole."},{type:"image",src:"/images/excel/module-6/charts/chart_type_1.png",alt:"Types of charts overview"},{type:"image",src:"/images/excel/module-6/charts/chart_type_2.png",alt:"Column chart example"},{type:"image",src:"/images/excel/module-6/charts/chart_type_3.png",alt:"Line chart example"},{type:"image",src:"/images/excel/module-6/charts/chart_type_4.png",alt:"Pie chart example"},{type:"image",src:"/images/excel/module-6/charts/chart_type_5.png",alt:"Bar chart example"},{type:"image",src:"/images/excel/module-6/charts/chart_type_6.png",alt:"Area chart example"},{type:"image",src:"/images/excel/module-6/charts/chart_type_7b.png",alt:"Surface chart example"}]},{heading:"Step 1: Select Your Data",blocks:[{type:"paragraph",text:"Before inserting a chart, select the full range of data you want Excel to chart, including headings. Excel uses headings for the legend and axis labels."},{type:"image",src:"/images/excel/module-6/charts/chart_selected_cells.png",alt:"Selecting data before creating a chart"},{type:"image",src:"/images/excel/module-6/charts/chart_data_range.png",alt:"Highlighted data range used for chart"}]},{heading:"Step 2: Insert a Chart",blocks:[{type:"paragraph",text:"Go to the Insert tab. You can use Recommended Charts to let Excel suggest the best chart, or pick a chart type directly from the Charts group."},{type:"image",src:"/images/excel/module-6/charts/chart_recommended_charts.png",alt:"Recommended Charts button on the ribbon"},{type:"image",src:"/images/excel/module-6/charts/chart_inserted_chart.png",alt:"Chart inserted into the worksheet"}]},{heading:"Quick Layout",blocks:[{type:"paragraph",text:"Quick Layout is the fastest way to make a chart look presentable. It adds titles, labels, and legend arrangements with one click."},{type:"image",src:"/images/excel/module-6/charts/chart_quick_layout.png",alt:"Quick Layout menu"}]},{heading:"Add Chart Title and Elements",blocks:[{type:"paragraph",text:"Use the green + button (Chart Elements) to add a Chart Title, Axis Titles, Data Labels, and more."},{type:"image",src:"/images/excel/module-6/charts/chart_chart_element.png",alt:"Chart Elements button shown next to chart"},{type:"image",src:"/images/excel/module-6/charts/chart_add_elements.jpeg",alt:"Add Chart Element menu"},{type:"image",src:"/images/excel/module-6/charts/chart_chart_title.png",alt:"Adding a chart title"}]},{heading:"Change Chart Type",blocks:[{type:"paragraph",text:"If you pick the wrong chart type, no problem. Select the chart → Chart Design → Change Chart Type."},{type:"image",src:"/images/excel/module-6/charts/chart_change_type.png",alt:"Change Chart Type command"},{type:"image",src:"/images/excel/module-6/charts/chart_chart_type.png",alt:"Change Chart Type dialog"}]},{heading:"Switch Row/Column",blocks:[{type:"paragraph",text:"If your chart looks backwards (wrong categories/series), use Switch Row/Column to flip how Excel reads the data."},{type:"image",src:"/images/excel/module-6/charts/chart_switch_row_column_command.png",alt:"Switch Row/Column command"},{type:"image",src:"/images/excel/module-6/charts/chart_switched_row_column.png",alt:"Chart after switching rows and columns"}]},{heading:"Move Chart to a New Sheet",blocks:[{type:"paragraph",text:"To make charts cleaner and easier to present, move them onto their own chart sheet: Chart Design → Move Chart."},{type:"image",src:"/images/excel/module-6/charts/chart_move_chart.png",alt:"Move Chart command"},{type:"image",src:"/images/excel/module-6/charts/chart_choose_move.png",alt:"Move Chart dialog box"},{type:"image",src:"/images/excel/module-6/charts/chart_moved_chart.png",alt:"Chart on its own sheet"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which chart type is best for showing how individual parts make up a whole?",options:["Bar chart","Line chart","Pie chart","Area chart"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Download and open the practice workbook. Complete the following:"},{type:"list",ordered:!0,items:["Select the full dataset (including headings).","Insert a Column chart using Recommended Charts.","Add a Chart Title: Book Sales.","Use Quick Layout to add labels/titles if needed.","Change the chart type to Line.","Use Switch Row/Column to compare how the data changes.","Move the final chart to a new chart sheet named Chart1."]},{type:"image",src:"/images/excel/module-6/charts/chart_final_result.png",alt:"Final chart challenge result",caption:"Goal: clean chart with a proper title and a readable layout."}]},{slug:"pivot-tables",title:"Introduction to PivotTables",description:"PivotTables allow you to summarize large datasets instantly and reorganize your data to answer questions quickly.",videoUrl:"https://www.youtube.com/embed/N4K3xjM76kI",duration:"35 min",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-6/pivotTables/Excel_IntroPivotTables_Practice.xlsx"}],sections:[{heading:"Why PivotTables Are Powerful",blocks:[{type:"paragraph",text:"When a worksheet contains many rows of data, calculating totals manually becomes difficult. PivotTables automatically summarize and analyze large datasets."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_example.png",alt:"Dataset used to create a PivotTable"}]},{heading:"Step 1: Select Your Data",blocks:[{type:"paragraph",text:"Select the entire dataset including the column headers. These headers will become the fields used in the PivotTable."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_create.png",alt:"Selecting dataset before creating PivotTable"}]},{heading:"Step 2: Insert the PivotTable",blocks:[{type:"paragraph",text:"Go to the Insert tab and click PivotTable."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_ribbon_command.png",alt:"PivotTable command in Excel ribbon"},{type:"paragraph",text:"Excel will open the Create PivotTable dialog box."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_dialog_box.png",alt:"Create PivotTable dialog box"}]},{heading:"Step 3: Understanding the PivotTable Fields Panel",blocks:[{type:"paragraph",text:"A blank PivotTable and the PivotTable Fields panel will appear in a new worksheet."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_field_list.png",alt:"PivotTable fields panel"}]},{heading:"Step 4: Add Fields to Build the PivotTable",blocks:[{type:"paragraph",text:"To calculate total sales by salesperson:"},{type:"list",ordered:!0,items:["Add Salesperson to the Rows area","Add Order Amount to the Values area"]},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_add_fields.png",alt:"Adding fields to PivotTable"},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_summarized.png",alt:"PivotTable summarizing sales by salesperson"}]},{heading:"Adding Columns to Analyze More Data",blocks:[{type:"paragraph",text:"You can analyze the data further by dragging the Month field into the Columns area."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_add_column.png",alt:"Adding month to PivotTable columns"},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_multiple_columns.png",alt:"PivotTable showing monthly totals"}]},{heading:"Changing the PivotTable Perspective",blocks:[{type:"paragraph",text:"PivotTables allow you to reorganize (pivot) the data to answer different questions."},{type:"paragraph",text:"For example, remove Salesperson and instead add Region to see total sales by region."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_newField_region.png",alt:"Adding Region field"},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_sold_by_each_region.png",alt:"Sales totals by region"}]},{heading:"Sorting and Filtering",blocks:[{type:"paragraph",text:"PivotTables allow sorting and filtering so you can analyze your data more easily."},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_sort_filter.png",alt:"Sorting PivotTable data"}]},{heading:"Final PivotTable Example",blocks:[{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_done_example.png",alt:"Completed PivotTable example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does a PivotTable allow you to do?",options:["Create a chart from a selected cell range","Apply conditional formatting across the entire workbook","Summarize and reorganize large datasets without changing the original data","Automatically correct formulas that return errors"],correctIndex:2}]}],challenge:[{type:"list",ordered:!0,items:["Open our practice workbook.","Create a PivotTable in a separate sheet.","We want to answer the question What is the total amount sold in each region? To do this, select Region and Order Amount."]},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_challenge_example.png",alt:"PivotTable showing total amount sold by region"},{type:"list",ordered:!0,start:4,items:["In the Rows area, remove Region and replace it with Salesperson.","Add Month to the Columns area.","Change the number format of cells B5:E13 to Currency. Note: You might have to make columns C and D wider to see the values."]},{type:"paragraph",text:"When you're finished, your workbook should look like this:"},{type:"image",src:"/images/excel/module-6/pivotTables/pivotTable_final_result.png",alt:"Completed PivotTable showing sales by salesperson and month"}]}],level:"Intermediate",estimatedMinutes:55},{moduleNumber:7,moduleSlug:"module-7",title:"Data Analysis Tools",emoji:"\uD83D\uDD0D",description:"Advanced PivotTable techniques, What-If Analysis tools, and reference styles for deeper data analysis.",lessons:[{slug:"doing-more-with-pivottables",title:"Doing More with PivotTables",description:"Learn how to perform deeper analysis with PivotTables by filtering, grouping, and refreshing summarized data.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/FVzX4I88DBs",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-7/advanced-pivotTables/Excel_MorePivotTables_Practice.xlsx"}],sections:[{heading:"Filtering PivotTables",blocks:[{type:"paragraph",text:"PivotTables allow you to filter data to focus on specific information. You can filter by fields such as Salesperson, Region, or Month to quickly analyze subsets of your dataset."},{type:"paragraph",text:"To filter a PivotTable, drag a field such as Salesperson into the Filters area of the PivotTable Fields panel."},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_add_filter.png",alt:"Adding a field to the PivotTable filter area"}]},{heading:"Filtering Multiple Items",blocks:[{type:"paragraph",text:"You can filter multiple values from a PivotTable field. Select the filter dropdown, enable Select Multiple Items, and choose the items you want to analyze."},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_multiple_items.png",alt:"Selecting multiple filter items in PivotTable"},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_uncheck.png",alt:"Unchecking filter options in PivotTable"}]},{heading:"Using Slicers for Visual Filtering",blocks:[{type:"paragraph",text:"Slicers provide a visual way to filter PivotTable data. Instead of dropdown menus, slicers use clickable buttons that allow you to filter data quickly."},{type:"paragraph",text:"To insert a slicer, select the PivotTable and go to PivotTable Analyze → Insert Slicer."},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_add_slicer.png",alt:"Insert slicer button in Excel"},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_slicer_view.png",alt:"Slicer interface in Excel"}]},{heading:"Filtering with Slicers",blocks:[{type:"paragraph",text:"You can click individual buttons in the slicer to filter the PivotTable instantly. Hold Ctrl to select multiple items."},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_slicer_select.png",alt:"Selecting slicer filters"},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_slicer_view_select_item.png",alt:"Filtering data with slicers"}]},{heading:"Creating PivotCharts",blocks:[{type:"paragraph",text:"PivotCharts allow you to visualize PivotTable data in a chart format. When the PivotTable changes, the chart updates automatically."},{type:"paragraph",text:"Select the PivotTable and go to Insert → PivotChart."},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_insert_chart.png",alt:"Insert PivotChart menu"},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_create_pivotChart.png",alt:"PivotChart creation dialog"}]},{heading:"Interacting with PivotCharts",blocks:[{type:"paragraph",text:"PivotCharts remain connected to their PivotTables. When filters or slicers change, the chart updates automatically."},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_pivotChart_appear.png",alt:"PivotChart appearing in Excel"},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_pivotChart_switch_view.png",alt:"PivotChart switching views"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After applying filters, slicers, and charts, you can quickly analyze patterns in your dataset. PivotTables and PivotCharts together provide powerful tools for summarizing and visualizing data."},{type:"image",src:"/images/excel/module-7/advanced-pivotTables/advanced_pivotTables_final_result.png",alt:"Final PivotTable and PivotChart result"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does a Slicer do in a PivotTable?",options:["Splits the PivotTable into two separate tables","Deletes rows that do not match a selected value","Provides a visual, clickable filter to quickly narrow PivotTable results","Converts PivotTable data into a regular cell range"],correctIndex:2}]}],challenge:[{type:"list",ordered:!0,items:["Open the practice workbook.","Create a PivotTable from the dataset.","Add Salesperson to Filters.","Filter the PivotTable to show only two salespeople.","Insert a Slicer for Salesperson.","Use the slicer to change which salespeople appear.","Create a PivotChart to visualize the sales totals."]}]},{slug:"what-if-analysis",title:"What-If Analysis",description:"Learn how to experiment with data using Excel’s What-If Analysis tools. In this lesson you will use Goal Seek to determine unknown values, explore Scenario Manager, and understand how Data Tables allow you to test multiple possibilities at once.",duration:"35 min",videoUrl:"https://www.youtube.com/embed/STTYxT6iFio",practiceFiles:[{name:"Download Practice Workbook",url:"/practice/excel/module-7/what-if-analysis/Excel_WhatIfAnalysis_Practice.xlsx"}],sections:[{heading:"Understanding What-If Analysis",blocks:[{type:"paragraph",text:"What-If Analysis is a powerful Excel feature that allows you to experiment with different values in formulas to see how the results change. Instead of manually changing numbers repeatedly, Excel can automatically calculate the impact of different inputs."},{type:"paragraph",text:"This is extremely useful in business, finance, and data analysis. For example, you may want to know how many units must be sold to reach a target revenue, what grade you need on a final exam to pass a class, or how many guests you can invite to an event while staying within a fixed budget."},{type:"paragraph",text:"Excel provides three primary What-If Analysis tools:"},{type:"list",ordered:!1,items:["Goal Seek – finds the required input value needed to reach a desired result.","Scenario Manager – compares multiple sets of values for different scenarios.","Data Tables – shows the results of formulas when one or two variables change."]}]},{heading:"Example: Calculating a Final Grade",blocks:[{type:"paragraph",text:"In this example, we want to determine the grade needed on a final exam to achieve a passing average in a course."},{type:"paragraph",text:"The worksheet contains grades for four assignments: Paper 1, Paper 2, Quiz, and Lab. The final exam grade has not yet been entered, but we already created a formula to calculate the overall average."},{type:"paragraph",text:"The formula used is:"},{type:"paragraph",text:"=AVERAGE(B2:B6)"},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_average_function.png",alt:"Average formula used to calculate final grade"},{type:"paragraph",text:"Because the final exam grade has not yet been entered, the calculated final grade currently shows 65."},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_average_result.png",alt:"Average formula result before using Goal Seek"}]},{heading:"Opening Goal Seek",blocks:[{type:"paragraph",text:"Goal Seek allows Excel to calculate what value must be entered into a specific cell in order to produce a desired result."},{type:"paragraph",text:"To open Goal Seek:"},{type:"list",ordered:!0,items:["Click the Data tab on the Excel ribbon.","Locate the Forecast or Data Tools section.","Click What-If Analysis.","Select Goal Seek from the dropdown menu."]},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_goal_seek_command.png",alt:"Opening Goal Seek from the What If Analysis menu"}]},{heading:"Using the Goal Seek Dialog Box",blocks:[{type:"paragraph",text:"When Goal Seek opens, a dialog box will appear with three input fields that define the calculation."},{type:"list",ordered:!0,items:["Set Cell – the cell containing the formula result you want to control.","To Value – the target value you want the formula to equal.","By Changing Cell – the input value Excel will modify to reach the target."]},{type:"paragraph",text:"In our example we want the Final Grade to equal 70."},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_goal_seek_dialog.png",alt:"Goal Seek dialog box"},{type:"paragraph",text:"We set the dialog as follows:"},{type:"list",ordered:!1,items:["Set cell: B7 (Final Grade)","To value: 70","By changing cell: B6 (Final Exam)"]},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_goal_seek_dialog_2.png",alt:"Goal Seek dialog example with values filled in"}]},{heading:"Goal Seek Finds the Required Grade",blocks:[{type:"paragraph",text:"After clicking OK, Excel automatically adjusts the value in the Final Exam cell until the average grade becomes exactly 70."},{type:"paragraph",text:"A confirmation dialog appears indicating that Goal Seek successfully found a solution."},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_goal_seek.png",alt:"Goal Seek confirmation message"},{type:"paragraph",text:"In this case, Excel determines that a score of 90 is required on the final exam in order to reach the target average of 70."},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_goal_seek_result.png",alt:"Goal Seek calculated final exam score"},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_goal_seek_result_2.png",alt:"Final grade after Goal Seek"}]},{heading:"Example 2: Event Budget Planning",blocks:[{type:"paragraph",text:"Goal Seek can also be used in financial and planning scenarios."},{type:"paragraph",text:"In this example, we are planning an event with a reservation fee and a cost per guest."},{type:"paragraph",text:"The formula used to calculate the total cost is:"},{type:"paragraph",text:"=B2 + B3 * B4"},{type:"paragraph",text:"This formula adds the fixed reservation fee and the variable cost per guest."},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_example_2.png",alt:"Event budget example worksheet"},{type:"paragraph",text:"We want to determine how many guests we can invite while keeping the total cost under $500."},{type:"paragraph",text:"Using Goal Seek, we set:"},{type:"list",ordered:!1,items:["Set Cell: B5 (Total Budget)","To Value: 500","By Changing Cell: B4 (Number of Guests)"]},{type:"paragraph",text:"Excel calculates that approximately 18.62 guests can be invited."},{type:"paragraph",text:"Since the number of guests must be a whole number, the value must be rounded down to 18 guests to stay within budget."}]},{heading:"Scenario Manager",blocks:[{type:"paragraph",text:"Scenario Manager allows you to compare different possible situations by storing multiple sets of values."},{type:"paragraph",text:"For example, you might compare different venues for an event, each with a different reservation fee and price per guest."},{type:"paragraph",text:"Each scenario stores a different combination of input values that can be applied to the worksheet instantly."},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_scenarios.png",alt:"Scenario manager example"}]},{heading:"Using Data Tables",blocks:[{type:"paragraph",text:"Data Tables allow you to evaluate formulas using many different input values at the same time."},{type:"paragraph",text:"In the example below, Excel calculates loan payments for multiple combinations of interest rates and loan terms."},{type:"paragraph",text:"This allows analysts to quickly see how different financial conditions impact the payment amount."},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_data_tables.png",alt:"Excel data table example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which What-If Analysis tool finds the input value needed to reach a specific result?",options:["Scenario Manager","Data Tables","Solver","Goal Seek"],correctIndex:3}]}],challenge:[{type:"list",ordered:!0,items:["Download and open the practice workbook.","Navigate to the Challenge worksheet.","Create a formula that calculates the average sales for cells B2 through B7.","Use Goal Seek to determine how much must be sold in June to reach a $200,000 mid-year average.","Verify that the result updates the average correctly."]},{type:"image",src:"/images/excel/module-7/what-if-analysis/what-if-analysis_final_result.png",alt:"Goal Seek result showing number of guests"}]},{slug:"reference-styles",title:"What are Reference Styles?",description:"Learn the difference between A1 and R1C1 reference styles in Excel and how to switch between them using the Excel Options menu.",duration:"10 min",sections:[{heading:"Understanding Reference Styles",blocks:[{type:"paragraph",text:"Every Excel spreadsheet is organized into rows and columns. Rows are identified by numbers (1, 2, 3, etc.), while columns are typically identified by letters (A, B, C, etc.). This common labeling system is known as the A1 reference style."},{type:"paragraph",text:"In the A1 reference style, the column letter appears first and the row number appears second. For example, the cell located in column A and row 1 is called A1."},{type:"paragraph",text:"Excel also supports an alternative reference format called R1C1 reference style. In this format, both rows and columns are identified by numbers. The letter R represents the row number, while C represents the column number."},{type:"paragraph",text:"For example, the cell that would normally be called A1 becomes R1C1 when using this reference system."}]},{heading:"A1 vs R1C1 Reference Styles",blocks:[{type:"paragraph",text:"The A1 reference style is the default format used in Excel and is the style most people are familiar with. However, some advanced users prefer the R1C1 reference style when working with complex formulas because it makes relative references easier to understand in certain situations."},{type:"paragraph",text:"The image below shows the difference between the two reference styles."},{type:"image",src:"/images/excel/module-7/reference-styles/reference-styles_example.png",alt:"Comparison of R1C1 reference style and A1 reference style"},{type:"paragraph",text:"In the image on the left, the column headers are numbered instead of labeled with letters. This indicates that the worksheet is using the R1C1 reference style."},{type:"paragraph",text:"In the image on the right, the columns are labeled with letters such as A, B, and C. This is the standard A1 reference style that Excel uses by default."},{type:"paragraph",text:"In most situations you will want to use the A1 reference style because it is easier to read and matches the way Excel tutorials and documentation describe cell references."}]},{heading:"Accessing Excel Options",blocks:[{type:"paragraph",text:"If your spreadsheet is currently using the R1C1 reference style, you can switch back to the standard A1 style using Excel Options."},{type:"paragraph",text:"To access the Excel Options menu, begin by clicking the File tab located in the top-left corner of the Excel window."},{type:"image",src:"/images/excel/module-7/reference-styles/reference-styles_file_tab.png",alt:"Click the File tab in Excel"},{type:"paragraph",text:"Clicking the File tab will open the Backstage view. This screen contains several options for managing your workbook, including saving, printing, exporting, and accessing account settings."},{type:"image",src:"/images/excel/module-7/reference-styles/reference-styles_backstage_options.png",alt:"Backstage view options menu"},{type:"paragraph",text:"At the bottom of the Backstage view menu, click Options. This will open the Excel Options dialog box where you can customize many settings related to formulas, calculations, and interface preferences."}]},{heading:"Turning Off R1C1 Reference Style",blocks:[{type:"paragraph",text:"Once the Excel Options dialog box appears, select the Formulas category from the list on the left side of the window."},{type:"image",src:"/images/excel/module-7/reference-styles/reference-styles_excel_options_formulas.png",alt:"Excel Options formulas settings"},{type:"paragraph",text:"Inside the Formulas section, you will see an option labeled R1C1 reference style."},{type:"paragraph",text:"If this box is checked, Excel will display columns as numbers instead of letters. To switch back to the standard reference style, simply uncheck the R1C1 reference style box."},{type:"paragraph",text:"After unchecking the box, click OK. Excel will immediately return to the standard A1 reference style."},{type:"paragraph",text:"You will now see column letters again at the top of the worksheet, such as A, B, C, and D, instead of numbers."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"In R1C1 reference style, how is the cell in row 3, column 2 identified?",options:["B3","C2R3","R3C2","3B"],correctIndex:2}]}],challenge:[{type:"list",ordered:!0,items:["Open Excel and create a new blank workbook.","Navigate to the File tab and open Excel Options.","Click the Formulas category.","Locate the R1C1 reference style checkbox.","Toggle the checkbox on and off to observe how the column labels change.","Return the setting to the standard A1 reference style."]}]}],level:"Advanced",estimatedMinutes:60}],word:[{moduleNumber:1,moduleSlug:"module-1",title:"Introduction to Word 2019",emoji:"\uD83D\uDCDD",description:"Interface navigation, document creation, saving, and essential formatting.",lessons:[{slug:"getting-started",title:"Getting Started with Word",description:"Learn how to navigate the Word interface and understand the Ribbon, Quick Access Toolbar, and Backstage view.",videoUrl:"https://www.youtube.com/embed/j-ZAVHk5SaU",duration:"8 min",sections:[{heading:"Introduction",blocks:[{type:"paragraph",text:"Microsoft Word is a word processing application that allows you to create a variety of documents, including letters, resumes, and more. In this lesson, you'll learn how to navigate the Word interface and become familiar with important features such as the Ribbon, Quick Access Toolbar, and Backstage view."}]},{heading:"About This Tutorial",blocks:[{type:"paragraph",text:"The procedures in this tutorial will work for all recent versions of Microsoft Word, including Word 2019, Word 2016, and Microsoft 365. There may be slight differences, but for the most part these versions are very similar."}]},{heading:"The Word Interface",blocks:[{type:"paragraph",text:"When you open Word for the first time, the Start Screen appears. From here, you can create a new document, choose a template, or access recently edited documents. Select Blank Document to access the Word interface."},{type:"image",src:"/images/word/getting-started/create_new_blank.png",alt:"Word Start Screen",caption:"Select Blank Document from the Start Screen."}]},{heading:"Working with the Word Environment",blocks:[{type:"paragraph",text:"All recent versions of Word include the Ribbon and the Quick Access Toolbar, where you'll find commands to perform common tasks in Word, as well as Backstage view."}]},{heading:"The Ribbon",blocks:[{type:"paragraph",text:"Word uses a tabbed Ribbon system instead of traditional menus. The Ribbon contains multiple tabs near the top of the Word window. Each tab contains groups of related commands."},{type:"image",src:"/images/word/getting-started/start_ribbon_tabs.png",alt:"Microsoft Word Ribbon Tabs",caption:"The Ribbon contains multiple tabs and command groups."},{type:"paragraph",text:"Some groups have a small arrow in the bottom-right corner that opens additional options."},{type:"image",src:"/images/word/getting-started/start_ribbon_arrow.png",alt:"Dialog Box Launcher Arrow",caption:"Click the small arrow for additional formatting options."}]},{heading:"Showing and Hiding the Ribbon",blocks:[{type:"paragraph",text:"If the Ribbon takes up too much space, you can hide it. Click the Ribbon Display Options button in the upper-right corner of the window."},{type:"image",src:"/images/word/getting-started/start_ribbon_minimize.png",alt:"Ribbon Display Options"},{type:"list",ordered:!1,items:["Auto-hide Ribbon – Completely hides the Ribbon.","Show Tabs – Shows only the tab names.","Show Tabs and Commands – Shows the full Ribbon (default)."]}]},{heading:"Using the Tell Me Feature",blocks:[{type:"paragraph",text:"If you're having trouble finding a command, use the Tell Me feature. Type what you're looking for in the Tell Me bar and select a result from the dropdown."},{type:"image",src:"/images/word/getting-started/start_ribbon_tellme.png",alt:"Tell Me Search Bar"}]},{heading:"The Quick Access Toolbar",blocks:[{type:"paragraph",text:"Located above the Ribbon, the Quick Access Toolbar provides quick access to Save, Undo, and Redo. You can customize it with additional commands."},{type:"image",src:"/images/word/getting-started/start_quick_print.png",alt:"Quick Access Toolbar Menu"},{type:"list",ordered:!0,items:["Click the drop-down arrow next to the Quick Access Toolbar.","Select the command you want to add.","The command will appear on the toolbar."]}]},{heading:"The Ruler",blocks:[{type:"paragraph",text:"The Ruler appears at the top and left of the document and helps you adjust margins and alignment precisely."},{type:"image",src:"/images/word/getting-started/start_ruler_tab.png",alt:"View Tab with Ruler Option"},{type:"paragraph",text:"To show or hide the Ruler, click the View tab and check or uncheck the Ruler box."}]},{heading:"Backstage View",blocks:[{type:"paragraph",text:"Backstage view provides options for saving, printing, sharing, and managing documents. Click the File tab to open Backstage view."},{type:"image",src:"/images/word/getting-started/start_backstage_file.png",alt:"Backstage View File Tab"},{type:"image",src:"/images/word/getting-started/start_backstage_lg.png",alt:"Backstage View Large"}]},{heading:"Document Views and Zooming",blocks:[{type:"paragraph",text:"Word offers several document views: Read Mode, Print Layout, and Web Layout. These views change how your document appears."},{type:"image",src:"/images/word/getting-started/start_view_print.png",alt:"Print Layout View"},{type:"paragraph",text:"You can zoom in or out using the zoom slider in the bottom-right corner of the window."},{type:"image",src:"/images/word/getting-started/start_zoom.png",alt:"Zoom Slider"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Where are most Word formatting commands found?",options:["The File menu","The status bar","The Ribbon","The Quick Access Toolbar"],correctIndex:2}]}],challenge:[{type:"list",ordered:!0,items:["Open Word and create a blank document.","Change Ribbon Display Options to Show Tabs.","Using Customize Quick Access Toolbar, add New, Quick Print, and Spelling & Grammar.","In the Tell Me bar, type Shape and press Enter.","Choose a shape and double-click somewhere in the document.","Show the Ruler if it is not already visible.","Zoom the document to 120%.","Change the Document view to Web Layout.","When finished, your document should look something like this.","Change Ribbon Display Options back to Show Tabs and Commands, and change view back to Print Layout."]},{type:"image",src:"/images/word/getting-started/word2016_gettingtoknow3_img.png",alt:"Completed Word Challenge Document"}]},{slug:"understanding-onedrive",title:"Understanding OneDrive (Word)",description:"Learn how to sign in, save files to OneDrive, and share documents online.",videoUrl:"https://www.youtube.com/embed/OR_RjjqF1qc",duration:"2 min",sections:[{heading:"Introduction",blocks:[{type:"paragraph",text:"Many of the features in Microsoft Office are designed for saving and sharing files online. OneDrive is Microsoft’s cloud storage space that allows you to save, edit, and share your documents from any device."},{type:"paragraph",text:"You can access OneDrive from your computer, smartphone, or tablet. To get started, you’ll need a free Microsoft account."},{type:"paragraph",text:"Once you have a Microsoft account, click Sign in in the upper-right corner of the Word window to connect your account."},{type:"image",src:"/images/word/understanding-onedrive/onedrive_signin.png",alt:"Sign in to Microsoft Account in Word",caption:"Click Sign in in the upper-right corner of Word."}]},{heading:"Benefits of Using OneDrive",blocks:[{type:"list",ordered:!1,items:["Access your files anywhere – Open documents from any device with an Internet connection.","Back up your files – Protect your documents even if something happens to your computer.","Share files – Allow others to view or edit your documents for collaboration."]}]},{heading:"Saving and Opening Files",blocks:[{type:"paragraph",text:"When signed in, OneDrive appears as a save location whenever you click Save or Save As."},{type:"paragraph",text:"You can choose between saving to OneDrive or saving locally to This PC."},{type:"image",src:"/images/word/understanding-onedrive/onedrive_saveas.png",alt:"Save As Screen with OneDrive Option",caption:"Choose OneDrive to save online or This PC to save locally."}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the main benefit of saving a Word document to OneDrive?",options:["It automatically formats your document","It allows you to access your files from any device","It converts your file to PDF automatically","It increases your document storage limit"],correctIndex:1}]}],challenge:[{type:"list",ordered:!0,items:["Click Sign in in Word.","Sign in with a Microsoft account.","Click File → Save As.","Select OneDrive as the save location.","Save a document to OneDrive."]}]},{slug:"creating-and-opening-documents",title:"Creating and Opening Documents",description:"Learn how to create new documents from templates, open existing files, pin documents, and convert older Word files.",videoUrl:"https://www.youtube.com/embed/PafCMUVH_OA",duration:"8 min",practiceFiles:[{name:"Creating and Opening Documents Practice File",url:"/practice/word/module-1/creating-and-opening-documents/word_createopen_practice.doc"}],sections:[{heading:"Creating a New Document",blocks:[{type:"paragraph",text:"To create a new document, click the File tab to open Backstage view, then select New. You can choose Blank document or search for a template."},{type:"image",src:"/images/word/creating-and-opening-documents/new_template_start.png",alt:"New document screen"},{type:"paragraph",text:"You can type a keyword such as flyer in the search bar to find matching templates."},{type:"image",src:"/images/word/creating-and-opening-documents/new_template_search_.jpg",alt:"Searching for flyer template"},{type:"paragraph",text:"Templates are also organized by category. Select a category such as Flyers to browse available designs."},{type:"image",src:"/images/word/creating-and-opening-documents/new_template_category_splat.png",alt:"Template categories"},{type:"paragraph",text:"Click a template preview, then select Create to open the new document."},{type:"image",src:"/images/word/creating-and-opening-documents/new_template_create.jpg",alt:"Create template button"}]},{heading:"Opening an Existing Document",blocks:[{type:"paragraph",text:"To open an existing file, click File, then select Open. You can choose from Recent documents, OneDrive, or This PC."},{type:"image",src:"/images/word/creating-and-opening-documents/create_open_command.png",alt:"Open command in Backstage view"},{type:"paragraph",text:"Select Browse to locate a file stored on your computer."},{type:"image",src:"/images/word/creating-and-opening-documents/new_open_browse.png",alt:"Browse option"},{type:"image",src:"/images/word/creating-and-opening-documents/new_open_select.png",alt:"Selecting a document"}]},{heading:"Pinning and Unpinning Documents",blocks:[{type:"paragraph",text:"You can pin frequently used documents so they stay at the top of your Recent list."},{type:"image",src:"/images/word/creating-and-opening-documents/new_pin_start.png",alt:"Pinned document"},{type:"paragraph",text:"Click the pushpin icon again to unpin the document."},{type:"image",src:"/images/word/creating-and-opening-documents/new_pin_unpin.png",alt:"Unpin document"}]},{heading:"Compatibility Mode and Converting Files",blocks:[{type:"paragraph",text:"If you open a document created in an older version of Word, it may open in Compatibility Mode. Some features may be limited."},{type:"image",src:"/images/word/creating-and-opening-documents/new_convert_compare_crop.png",alt:"Compatibility Mode label"},{type:"paragraph",text:"To upgrade the file to the latest format, click File, then select Convert."},{type:"image",src:"/images/word/creating-and-opening-documents/new_convert_command.png",alt:"Convert command"},{type:"paragraph",text:"Click OK to confirm the conversion."},{type:"image",src:"/images/word/creating-and-opening-documents/new_convert_ok.png",alt:"Convert confirmation dialog"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What feature lets you quickly reopen a file you worked on recently?",options:["The New tab","The Recent list","The Template gallery","The Browse button"],correctIndex:1}]}],challenge:[{type:"list",ordered:!0,items:["Create a new document using a flyer template.","Search for a template using a keyword.","Open an existing document from This PC.","Pin a document to the Recent list.","Unpin the document.","Open a file in Compatibility Mode (if available).","Convert the file to the newest format."]}]},{slug:"saving-and-sharing-documents",title:"Saving and Sharing Documents",description:"Learn how to save documents, use AutoRecover, change file types, export to PDF, and share documents with others.",videoUrl:"https://www.youtube.com/embed/iHuFzz7Wvt4",duration:"8 min",practiceFiles:[{name:"Saving and Sharing Practice File",url:"/practice/word/module-1/saving-and-sharing/word_saveshare_practice.docx"}],sections:[{heading:"Saving a Document",blocks:[{type:"paragraph",text:"To save a document, click the File tab, then select Save or Save As. If it is your first time saving the file, you will be prompted to choose a location."},{type:"image",src:"/images/word/saving-and-sharing/save_command.png",alt:"Save command in Backstage view"},{type:"image",src:"/images/word/saving-and-sharing/save_dialog.png",alt:"Save dialog box"}]},{heading:"Using AutoRecover",blocks:[{type:"paragraph",text:"Word automatically saves temporary versions of your document using AutoRecover. If Word closes unexpectedly, you may see the Document Recovery pane when you reopen it."},{type:"image",src:"/images/word/saving-and-sharing/save_autosave_recover.png",alt:"Document Recovery pane"},{type:"image",src:"/images/word/saving-and-sharing/save_autosave_splat.png",alt:"Recover Unsaved Documents option"}]},{heading:"Changing Default Save Options",blocks:[{type:"paragraph",text:"You can change how Word saves documents by going to File → Options → Save. From here, you can adjust AutoRecover timing and default save locations."},{type:"image",src:"/images/word/saving-and-sharing/save_default_options.png",alt:"Word Save options"},{type:"image",src:"/images/word/saving-and-sharing/save_default_dialog.png",alt:"Default save location dialog"}]},{heading:"Using Save As and Browsing",blocks:[{type:"paragraph",text:"Select Save As to save a copy of your document in a different location or under a different name."},{type:"image",src:"/images/word/saving-and-sharing/save_saveas.png",alt:"Save As screen"},{type:"image",src:"/images/word/saving-and-sharing/save_browse.png",alt:"Browse option"}]},{heading:"Changing File Types and Exporting",blocks:[{type:"paragraph",text:"You can change the file type by selecting File → Export → Change File Type."},{type:"image",src:"/images/word/saving-and-sharing/save_export_file_command.png",alt:"Export and Change File Type"},{type:"image",src:"/images/word/saving-and-sharing/save_export_file_splat.png",alt:"Change File Type options"},{type:"paragraph",text:"To create a PDF, choose File → Export → Create PDF/XPS Document."},{type:"image",src:"/images/word/saving-and-sharing/save_export_pdf_command.png",alt:"Create PDF command"},{type:"image",src:"/images/word/saving-and-sharing/save_export_pdf_dialog.png",alt:"Publish as PDF dialog"}]},{heading:"Sharing a Document",blocks:[{type:"paragraph",text:"You can share documents directly from Word by selecting File → Share."},{type:"image",src:"/images/word/saving-and-sharing/save_share_command.png",alt:"Share command"},{type:"image",src:"/images/word/saving-and-sharing/share_menu.jpg",alt:"Share menu"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which file format should you use when sending a final document that others should not edit?",options:["Word 97-2003 (.doc)","Plain Text (.txt)","PDF (.pdf)","Rich Text Format (.rtf)"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Download the practice file and complete the following steps:"},{type:"list",ordered:!0,items:["Open the practice file.","Use Save As to save a copy to a new location.","Change the file type to Word 97-2003 Document.","Export the document as a PDF.","Recover an unsaved document (if available).","Open File → Options and review the Save settings.","Use the Share feature to generate a share link (if signed in)."]}]}],level:"Beginner",estimatedMinutes:35},{moduleNumber:2,moduleSlug:"module-2",title:"Basic Formatting",emoji:"✏️",description:"Master paragraph formatting, alignment, spacing, and essential document styling.",lessons:[{slug:"text-basics",title:"Text Basics",description:"Learn how to insert, delete, select, cut, copy, paste, and move text efficiently in Word.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/vmEzxQfVj5c?si=FydXQ8y--1kuD0b1",practiceFiles:[{name:"Word Text Basics Practice File",url:"/practice/word/module-2/text-basics/word_textbasics_practice.docx"}],sections:[{heading:"Selecting Text",blocks:[{type:"paragraph",text:"Before editing text, you must first select it. You can click and drag your mouse across text, double-click to select a word, triple-click to select a paragraph, or press Ctrl + A to select the entire document."},{type:"image",src:"/images/word/text-basics/text_select.png",alt:"Selecting text in Word"}]},{heading:"Cut, Copy, and Paste",blocks:[{type:"paragraph",text:"The Cut command removes selected text and places it on the clipboard. The Copy command duplicates selected text. Paste inserts the content from the clipboard."},{type:"image",src:"/images/word/text-basics/text_copy_command.png",alt:"Copy command"},{type:"image",src:"/images/word/text-basics/text_copy_done.png",alt:"Copy result"},{type:"image",src:"/images/word/text-basics/text_cut_command.png",alt:"Cut command"}]},{heading:"Moving Text",blocks:[{type:"paragraph",text:"To move text, select it, cut it, then paste it in the desired location."},{type:"image",src:"/images/word/text-basics/text_cut_destination.png",alt:"Cut destination"},{type:"image",src:"/images/word/text-basics/text_cut_done.png",alt:"Cut complete"}]},{heading:"Insertion Point",blocks:[{type:"paragraph",text:"The insertion point is the blinking vertical line that shows where text will appear when you type."},{type:"image",src:"/images/word/text-basics/text_insertion_point.png",alt:"Insertion point"}]},{heading:"Using Symbols",blocks:[{type:"paragraph",text:"You can insert special symbols like ™ from the Insert tab by selecting Symbol."},{type:"image",src:"/images/word/text-basics/text_symbol_command.png",alt:"Insert symbol command"},{type:"image",src:"/images/word/text-basics/text_symbol_done.png",alt:"Symbol inserted"}]},{heading:"Real-World Example",blocks:[{type:"image",src:"/images/word/text-basics/word2016_textbasics2_img.png",alt:"Completed auto detailing flyer"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which keyboard shortcut copies selected text?",options:["Ctrl + X","Ctrl + V","Ctrl + C","Ctrl + Z"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Select and copy the 'H2O Signature Wash' section.","Paste it below the 'Signature Interior' section.","Cut the pricing line and move it to the correct section.","Insert the ™ symbol after 'H2O Mobile Wash & Valet'."]}]},{slug:"formatting-text",title:"Formatting Text",description:"Learn how to change font, size, case, color, alignment, bold, italic, underline, and highlighting in Microsoft Word.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/pmAl-8Tf8Pg?si=ObAc154cTG0NXlLk",practiceFiles:[{name:"Word Formatting Text Practice File",url:"/practice/word/module-2/formatting-text/word_formattext_practice.docx"}],sections:[{heading:"Text Alignment",blocks:[{type:"paragraph",text:"Alignment controls how text is positioned between the margins. You can align text to the left, center, right, or justify it."},{type:"image",src:"/images/word/formatting-text/formatting_alignment_select.png",alt:"Selecting text before alignment"},{type:"image",src:"/images/word/formatting-text/formatting_alignment_command.png",alt:"Alignment command in Word"},{type:"image",src:"/images/word/formatting-text/formatting_alignment_result.png",alt:"Aligned text result"}]},{heading:"Changing Text Case",blocks:[{type:"paragraph",text:"The Change Case command allows you to quickly convert text to uppercase, lowercase, or capitalize each word."},{type:"image",src:"/images/word/formatting-text/formatting_case_select.png",alt:"Selecting text before changing case"},{type:"image",src:"/images/word/formatting-text/formatting_case_menu.png",alt:"Change case dropdown menu"},{type:"image",src:"/images/word/formatting-text/formatting_case_result.png",alt:"Uppercase text result"}]},{heading:"Changing Font Type",blocks:[{type:"paragraph",text:"You can change the font style from the Font dropdown menu in the Home tab."},{type:"image",src:"/images/word/formatting-text/formatting_font_select.png",alt:"Selecting text before changing font"},{type:"image",src:"/images/word/formatting-text/formatting_font_menu.png",alt:"Font dropdown menu"},{type:"image",src:"/images/word/formatting-text/formatting_font_result.png",alt:"Changed font result"}]},{heading:"Changing Font Size",blocks:[{type:"paragraph",text:"Adjust font size using the size dropdown menu or the Increase/Decrease Font Size buttons."},{type:"image",src:"/images/word/formatting-text/formatting_size_select.png",alt:"Selecting text before resizing"},{type:"image",src:"/images/word/formatting-text/formatting_size_menu.png",alt:"Font size dropdown menu"},{type:"image",src:"/images/word/formatting-text/formatting_size_grow_shrink.png",alt:"Grow and shrink font buttons"},{type:"image",src:"/images/word/formatting-text/formatting_size_result.png",alt:"Resized text result"}]},{heading:"Changing Font Color",blocks:[{type:"paragraph",text:"Use the Font Color dropdown to apply theme colors or choose custom colors."},{type:"image",src:"/images/word/formatting-text/formatting_color_select.png",alt:"Selecting text before changing color"},{type:"image",src:"/images/word/formatting-text/formatting_color_menu2.png",alt:"Font color dropdown menu"},{type:"image",src:"/images/word/formatting-text/formatting_color_more_colors.png",alt:"More colors dialog"},{type:"image",src:"/images/word/formatting-text/formatting_color_result2.png",alt:"Font color result"}]},{heading:"Text Highlighting",blocks:[{type:"paragraph",text:"The Text Highlight tool allows you to emphasize important information."},{type:"image",src:"/images/word/formatting-text/formatting_highlight_select.png",alt:"Selecting text before highlighting"},{type:"image",src:"/images/word/formatting-text/formatting_highlight_menu.png",alt:"Highlight color menu"},{type:"image",src:"/images/word/formatting-text/formatting_highlight_result.png",alt:"Highlighted text result"},{type:"image",src:"/images/word/formatting-text/formatting_highlight_no_color.png",alt:"Removing highlight"}]},{heading:"Bold, Italic, and Underline",blocks:[{type:"paragraph",text:"Use Bold, Italic, and Underline to emphasize text."},{type:"image",src:"/images/word/formatting-text/formatting_emphasis_select.png",alt:"Selecting text before applying emphasis"},{type:"image",src:"/images/word/formatting-text/formatting_emphasis_command.png",alt:"Bold Italic Underline buttons"},{type:"image",src:"/images/word/formatting-text/formatting_emphasis_result.png",alt:"Bold and italic result"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After applying alignment, case changes, font adjustments, color, highlighting, and emphasis, your completed document should look like this:"},{type:"image",src:"/images/word/formatting-text/word2016_format_text_img.png",alt:"Completed For Rent flyer example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which formatting option makes text appear slanted?",options:["Bold","Italic","Underline","Strikethrough"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Change the title to ALL CAPS.","Center-align the main heading.","Increase the font size of the title to 72pt.","Change the font color of the title.","Apply bold formatting to the price.","Highlight the contact phone number.","Modify the font style of the title."]}]},{slug:"find-and-replace",title:"Using Find & Replace",description:"Learn how to search for text, navigate results, and replace words or phrases efficiently in Microsoft Word.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/p3Ql9y3eEyo?si=ZQ4tqLb9hhar33zv",practiceFiles:[{name:"Word Find and Replace Practice File",url:"/practice/word/module-2/find-and-replace/word_findreplace_practice.docx"}],sections:[{heading:"Using Find (Ctrl + F)",blocks:[{type:"paragraph",text:"The Find command allows you to search for specific words or phrases in a document. Press Ctrl + F or click Find in the Editing group on the Home tab."},{type:"image",src:"/images/word/find-replace/2016-01-05_12-20-50.png",alt:"Find command button"},{type:"image",src:"/images/word/find-replace/2016-01-05_12-22-01.png",alt:"Navigation pane showing results"},{type:"paragraph",text:"The Navigation pane displays all matching results. Click any result to jump directly to that location in the document."}]},{heading:"Advanced Find Options",blocks:[{type:"paragraph",text:"Click the dropdown arrow in the Navigation pane to access Advanced Find. This allows you to refine your search or locate specific elements such as tables, graphics, or footnotes."},{type:"image",src:"/images/word/find-replace/2016-01-05_12-23-11.png",alt:"Advanced find options menu"}]},{heading:"Using Replace (Ctrl + H)",blocks:[{type:"paragraph",text:"The Replace command allows you to search for text and automatically replace it with new text. Press Ctrl + H or click Replace in the Editing group."},{type:"image",src:"/images/word/find-replace/2016-01-05_12-25-23.png",alt:"Replace command"},{type:"image",src:"/images/word/find-replace/2016-01-05_12-26-17.png",alt:"Find and Replace dialog box"},{type:"image",src:"/images/word/find-replace/2016-01-05_12-29-47.png",alt:"Replace example"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After using Replace All, every instance of the word is updated throughout the document instantly."},{type:"image",src:"/images/word/find-replace/2016-01-11_08-48-30.png",alt:"Final replaced document result"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which keyboard shortcut opens Find & Replace?",options:["Ctrl + F","Ctrl + G","Ctrl + H","Ctrl + R"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Use Find to search for the word 'fiction'.","Navigate through all results using the arrows in the Navigation pane.","Open Replace (Ctrl + H).","Replace 'Sewanee Review' with 'SR'.","Use Replace All to update the entire document.","Verify that all instances were correctly replaced."]}]},{slug:"lists",title:"Lists (Bulleted, Numbered & Multilevel)",description:"Learn how to create, customize, and manage bulleted, numbered, and multilevel lists in Microsoft Word.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/tyXahko-tX8",practiceFiles:[{name:"Word Lists Practice File",url:"/practice/word/module-2/lists/word_lists_practice.docx"}],sections:[{heading:"Creating a Bulleted List",blocks:[{type:"paragraph",text:"Bulleted lists are useful when order does not matter. Select your text, then click the Bullets button in the Paragraph group on the Home tab."},{type:"image",src:"/images/word/lists/lists_create_bulleted_select.png",alt:"Selecting text before applying bullets"},{type:"image",src:"/images/word/lists/lists_create_bulleted_command.png",alt:"Bullets command button"},{type:"image",src:"/images/word/lists/lists_create_bulleted_result2.png",alt:"Bulleted list result"}]},{heading:"Customizing Bullets",blocks:[{type:"paragraph",text:"You can customize bullets using symbols, fonts, or colors by selecting Define New Bullet from the dropdown menu."},{type:"image",src:"/images/word/lists/lists_bullet_symbol_define2.png",alt:"Define new bullet dialog"},{type:"image",src:"/images/word/lists/lists_bullet_symbol_wingdings.png",alt:"Wingdings symbol selection"},{type:"image",src:"/images/word/lists/lists_bullet_symbol_result.png",alt:"Custom bullet result"}]},{heading:"Changing Bullet Color",blocks:[{type:"paragraph",text:"Bullet colors can be changed independently from text color using the Font option inside Define New Bullet."},{type:"image",src:"/images/word/lists/lists_bullet_color_menu.png",alt:"Bullet color menu"},{type:"image",src:"/images/word/lists/lists_bullet_color_result.png",alt:"Green bullet result"}]},{heading:"Creating a Numbered List",blocks:[{type:"paragraph",text:"Numbered lists are used when order matters. Select your text and click the Numbering button in the Paragraph group."},{type:"image",src:"/images/word/lists/lists_create_numbered_select.png",alt:"Selecting text for numbering"},{type:"image",src:"/images/word/lists/lists_create_numbered_result.png",alt:"Numbered list result"}]},{heading:"Restarting or Continuing Numbering",blocks:[{type:"paragraph",text:"Right-click a numbered list to restart numbering at 1 or continue numbering from a previous list."},{type:"image",src:"/images/word/lists/lists_restart_numbering_menu.png",alt:"Restart numbering menu"},{type:"image",src:"/images/word/lists/lists_restart_numbering_result.png",alt:"Restart numbering result"}]},{heading:"Multilevel Lists",blocks:[{type:"paragraph",text:"Multilevel lists allow sub-items under main items. Use the Increase Indent and Decrease Indent buttons to change levels."},{type:"image",src:"/images/word/lists/lists_multilevel_create_select2.png",alt:"Multilevel list dropdown"},{type:"image",src:"/images/word/lists/lists_multilevel_level_increase2.png",alt:"Increase indent"},{type:"image",src:"/images/word/lists/lists_multilevel_level_style.png",alt:"Multilevel result"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What type of list should you use when the order of items matters?",options:["Bulleted list","Multilevel list","Numbered list","Custom symbol list"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Create a bulleted list.","Customize the bullet symbol.","Change the bullet color.","Create a numbered list.","Restart numbering.","Create a multilevel list with at least two levels."]}]},{slug:"hyperlinks",title:"Links (Hyperlinks)",description:"Learn how to insert, edit, follow, and remove hyperlinks in Microsoft Word.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/mNJZo8ESMp0",practiceFiles:[{name:"Word Hyperlinks Practice File",url:"/practice/word/module-2/hyperlinks/word_hyperlinks_practice.docx"}],sections:[{heading:"Inserting a Hyperlink",blocks:[{type:"paragraph",text:"To insert a hyperlink, select the text you want to turn into a link. Then go to the Insert tab and click the Link button."},{type:"image",src:"/images/word/hyperlinks/hyperlinks_format_select.png",alt:"Selecting text before inserting hyperlink"},{type:"image",src:"/images/word/hyperlinks/hyperlinks_format_insert.png",alt:"Insert hyperlink command"},{type:"image",src:"/images/word/hyperlinks/hyperlinks_format_result.png",alt:"Hyperlink result in document"}]},{heading:"Following a Hyperlink",blocks:[{type:"paragraph",text:"To follow a hyperlink in Word, hold the Ctrl key and click the link. This opens the webpage in your browser."},{type:"image",src:"/images/word/hyperlinks/hyperlinks_understanding_ctrl_follow.png",alt:"Ctrl + Click to follow link"},{type:"image",src:"/images/word/hyperlinks/hyperlinks_understanding_website_example.png",alt:"Website example after clicking hyperlink"}]},{heading:"Editing a Hyperlink",blocks:[{type:"paragraph",text:"To edit an existing hyperlink, right-click the link and choose Edit Hyperlink. You can change the display text or the web address."},{type:"image",src:"/images/word/hyperlinks/hyperlinks_format_edit.png",alt:"Edit hyperlink option"}]},{heading:"Removing a Hyperlink",blocks:[{type:"paragraph",text:"To remove a hyperlink but keep the text, right-click the link and select Remove Hyperlink."},{type:"image",src:"/images/word/hyperlinks/hyperlinks_format_remove.png",alt:"Remove hyperlink option"}]},{heading:"Automatic Hyperlinks",blocks:[{type:"paragraph",text:"Word automatically converts web addresses (like www.poolsafely.gov) into clickable hyperlinks when you press Enter or Space."},{type:"image",src:"/images/word/hyperlinks/hyperlink_link.jpg",alt:"Automatic hyperlink example"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"When you are finished, your page should look something like this."},{type:"image",src:"/images/word/hyperlinks/word2016_hyperlink_img2.png",alt:"Insert Hyperlink dialog box"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How do you follow a hyperlink in a Word document?",options:["Double-click the link","Hold Ctrl and click the link","Right-click and select Open Hyperlink","Press Enter while the link is selected"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a hyperlink for 'City of Orlando'.","Verify the link using Ctrl + Click.","Edit the hyperlink address.","Remove a hyperlink but keep the text.","Create a hyperlink from a typed web address."]}]},{slug:"printing-documents",title:"Printing Documents",description:"Learn how to access the Print pane, select a printer, adjust print settings, and print specific pages in Microsoft Word.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/7bLQFTCsH8Y",practiceFiles:[{name:"Word Printing Practice File",url:"/practice/word/module-2/printing/word_printing_practice.docx"}],sections:[{heading:"Opening the Print Pane",blocks:[{type:"paragraph",text:"To print a document, click the File tab and then select Print. This opens the Print pane where you can preview and adjust settings before printing."},{type:"image",src:"/images/word/printing/printing_pane_file_tab.png",alt:"Clicking the File tab"},{type:"image",src:"/images/word/printing/printing_pane_print_tab.png",alt:"Print pane in Word"}]},{heading:"Selecting a Printer",blocks:[{type:"paragraph",text:"Use the Printer dropdown menu to choose which printer to send your document to. Word displays the printer status (Ready, Offline, etc.)."},{type:"image",src:"/images/word/printing/printing_to_print_1.png",alt:"Printer dropdown menu"}]},{heading:"Choosing the Number of Copies",blocks:[{type:"paragraph",text:"Use the Copies box to specify how many copies of the document you want to print."},{type:"image",src:"/images/word/printing/printing_to_print_2.png",alt:"Copies selection box"}]},{heading:"Adjusting Print Settings",blocks:[{type:"paragraph",text:"Under Settings, you can choose to print all pages, specific pages, one-sided or double-sided, portrait or landscape orientation, margins, and more."},{type:"image",src:"/images/word/printing/printing_to_print_3.png",alt:"Print settings options"},{type:"image",src:"/images/word/printing/printing_to_print_4.png",alt:"More print settings"}]},{heading:"Printing Specific Pages",blocks:[{type:"paragraph",text:"To print specific pages, select Custom Print and enter page numbers separated by commas (e.g., 2,5) or ranges (e.g., 1-3)."},{type:"image",src:"/images/word/printing/printing_custom_print_pages.png",alt:"Custom print page selection"},{type:"image",src:"/images/word/printing/printing_custom_print_print.png",alt:"Print button in custom print"}]},{heading:"Print Preview",blocks:[{type:"paragraph",text:"The preview pane shows exactly how your document will look when printed. Use the zoom slider to adjust the view before printing."},{type:"image",src:"/images/word/printing/word2016_printing_img_2.png",alt:"Print preview example"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After selecting your printer, adjusting settings, and reviewing the preview, click the Print button to send your document to the printer."},{type:"image",src:"/images/word/printing/download.png",alt:"Print button highlighted"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Where can you preview how your document will look before printing?",options:["The View tab","The Home tab","The Print pane in Backstage view","The Page Layout dialog box"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Open the Print pane.","Select your printer from the dropdown list.","Print 2 copies of the document.","Print only pages 1–3 and page 5.","Change the orientation to Landscape.","Review the print preview before printing."]}]}],level:"Beginner",estimatedMinutes:40},{moduleNumber:3,moduleSlug:"module-3",title:"Styles, Media & Themes",emoji:"\uD83C\uDFA8",description:"Use styles, themes, images, and media to create visually polished documents.",lessons:[{slug:"pictures-text-wrapping",title:"Pictures & Text Wrapping",description:"Learn how to insert images, resize them properly, and control how text wraps around pictures in Microsoft Word.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/sqkEDw99szg",practiceFiles:[{name:"Word Pictures & Text Wrapping Practice File",url:"/practice/word/module-3/pictures-text-wrapping/word_picturestextwrapping_practice.docx"}],sections:[{heading:"Inserting a Picture from Your Computer",blocks:[{type:"paragraph",text:"To insert a picture from your computer, go to the Insert tab and click Pictures. Then choose This Device and select your image."},{type:"image",src:"/images/word/pictures-text-wrapping/pictures_insert.jpg",alt:"Insert picture from device"}]},{heading:"Inserting an Online Picture",blocks:[{type:"paragraph",text:"You can also insert images from online sources. Click Insert → Online Pictures, search for a keyword, select an image, and click Insert."},{type:"image",src:"/images/word/pictures-text-wrapping/pictures_search.jpg",alt:"Online picture search window"},{type:"image",src:"/images/word/pictures-text-wrapping/pictures_onedrive.jpg",alt:"Online pictures category screen"}]},{heading:"Resizing a Picture",blocks:[{type:"paragraph",text:"To resize a picture, click the image and drag a corner handle. Dragging from the corner keeps the image proportional and prevents distortion."},{type:"image",src:"/images/word/pictures-text-wrapping/insert_picture_resize.png",alt:"Resize image using corner handles"}]},{heading:"Understanding Text Wrapping",blocks:[{type:"paragraph",text:"By default, pictures are inserted In Line with Text. To freely move and position a picture, you must change its wrapping style."},{type:"paragraph",text:"Select the image, then click the Layout Options icon or go to Picture Format → Wrap Text."},{type:"image",src:"/images/word/pictures-text-wrapping/2016-01-12_09-23-34.png",alt:"Layout options button"}]},{heading:"Wrap Text Options",blocks:[{type:"paragraph",text:"Word provides several wrapping options: In Line with Text, Square, Tight, Through, Top and Bottom, Behind Text, and In Front of Text."},{type:"paragraph",text:"Square wrapping is commonly used in newsletters because it allows text to flow neatly around the image."},{type:"image",src:"/images/word/pictures-text-wrapping/2016-01-12_09-24-44.png",alt:"Wrap text menu options"}]},{heading:"Using Square Text Wrapping",blocks:[{type:"paragraph",text:"After selecting Square wrapping, drag the image to position it. The surrounding text will automatically adjust around the picture."},{type:"image",src:"/images/word/pictures-text-wrapping/2016-01-12_09-26-17.png",alt:"Square wrapping applied"}]},{heading:"Using Top and Bottom Wrapping",blocks:[{type:"paragraph",text:"Top and Bottom wrapping places text above and below the image only. This is useful when separating content sections."},{type:"image",src:"/images/word/pictures-text-wrapping/2016-01-12_09-27-19.png",alt:"Top and bottom wrapping example"}]},{heading:"Move with Text vs Fix Position",blocks:[{type:"paragraph",text:"When using wrapping styles, you can choose Move with Text or Fix Position on Page. Move with Text keeps the image connected to surrounding content."},{type:"image",src:"/images/word/pictures-text-wrapping/2016-01-12_09-27-59.png",alt:"Move with text option"}]},{heading:"Using Position Presets",blocks:[{type:"paragraph",text:"Instead of manually dragging images, use Picture Format → Position to choose preset layout options."},{type:"image",src:"/images/word/pictures-text-wrapping/2016-01-12_09-50-34.png",alt:"Position preset menu"}]},{heading:"Aligning Images",blocks:[{type:"paragraph",text:"Use Picture Format → Align to align images precisely. Alignment guides help create professional layouts."},{type:"image",src:"/images/word/pictures-text-wrapping/2016-01-11_10-50-52.png",alt:"Align tools in picture format"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After inserting and wrapping images properly, your newsletter should have balanced spacing, clear structure, and professional image placement."},{type:"image",src:"/images/word/pictures-text-wrapping/word2016_pictureswrapping2_img.png",alt:"Completed newsletter with wrapped images"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which text wrapping style keeps an image on the same line as surrounding text?",options:["In Line with Text","Square","Tight","Behind Text"],correctIndex:0}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a picture from your computer.","Apply Square text wrapping.","Insert an online image.","Apply Top and Bottom wrapping to one image.","Use Position presets to adjust layout.","Align the image using alignment tools.","Ensure images are set to Move with Text."]}]},{slug:"formatting-pictures",title:"Formatting Pictures",description:"Learn how to crop images, apply picture styles, add borders, adjust color and corrections, and compress images in Microsoft Word.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/eC4bRXx9k6g?si=9Y7ajF4Ato7_DjyJ",practiceFiles:[{name:"Word Formatting Pictures Practice File",url:"/practice/word/module-3/formatting-pictures/word_formatpictures_practice.docx"}],sections:[{heading:"Introduction to Formatting Pictures",blocks:[{type:"paragraph",text:"Microsoft Word provides powerful tools for formatting pictures. You can crop images, apply artistic effects, adjust brightness and color, add borders, and compress pictures to reduce file size."},{type:"image",src:"/images/word/format-pictures/formatpics_adjust_all.png",alt:"Format tab with picture tools"}]},{heading:"Cropping an Image",blocks:[{type:"paragraph",text:"Cropping removes unwanted areas of an image. Select the image, go to the Format tab, and click Crop."},{type:"image",src:"/images/word/format-pictures/formatpics_crop_command2.png",alt:"Crop command"},{type:"image",src:"/images/word/format-pictures/formatpics_crop_handles2.png",alt:"Crop handles"},{type:"image",src:"/images/word/format-pictures/formatpics_crop_result.png",alt:"Cropped image result"}]},{heading:"Crop to Shape",blocks:[{type:"paragraph",text:"You can crop a picture into a specific shape. Click Crop → Crop to Shape and select a shape such as circle, star, or banner."},{type:"image",src:"/images/word/format-pictures/formatpics_shape_command.png",alt:"Crop to shape menu"},{type:"image",src:"/images/word/format-pictures/formatpics_shape_result.png",alt:"Cropped to shape result"}]},{heading:"Adding a Picture Border",blocks:[{type:"paragraph",text:"You can add a colored border to any image. Use Picture Border to choose a color, weight (thickness), and line style."},{type:"image",src:"/images/word/format-pictures/formatpics_border_command.png",alt:"Picture border options"}]},{heading:"Using Corrections",blocks:[{type:"paragraph",text:"The Corrections tool allows you to sharpen or soften an image and adjust brightness and contrast."},{type:"image",src:"/images/word/format-pictures/formatpics_adjust_corrections.png",alt:"Picture corrections menu"}]},{heading:"Adjusting Color",blocks:[{type:"paragraph",text:"The Color tool allows you to adjust saturation (vibrancy), tone (warm or cool), and recolor the entire image."},{type:"image",src:"/images/word/format-pictures/formatpics_adjust_color.png",alt:"Color adjustments menu"}]},{heading:"Applying Artistic Effects",blocks:[{type:"paragraph",text:"Artistic Effects apply stylized filters such as pastel, watercolor, or glow. These should be used carefully in professional documents."},{type:"image",src:"/images/word/format-pictures/formatpics_adjust_artistic.png",alt:"Artistic effects gallery"}]},{heading:"Using Picture Styles",blocks:[{type:"paragraph",text:"Picture Styles are predefined formats that quickly apply frames, shadows, and visual effects without manually adjusting settings."},{type:"image",src:"/images/word/format-pictures/formatpics_adjust_styles.png",alt:"Picture styles gallery"}]},{heading:"Compressing Pictures",blocks:[{type:"paragraph",text:"Large images increase document size. Use Compress Pictures to reduce resolution and delete cropped areas."},{type:"image",src:"/images/word/format-pictures/formatpics_compress_command.png",alt:"Compress pictures command"},{type:"image",src:"/images/word/format-pictures/formatpics_compress_dialog.png",alt:"Compress pictures dialog box"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After applying picture styles, cropping to shapes, recoloring elements, and compressing images, your finished document should look like this:"},{type:"image",src:"/images/word/format-pictures/word2016_formatpictures_img.png",alt:"Completed formatted document example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What tool would you use to remove the outer edge of an image?",options:["Corrections","Artistic Effects","Crop","Picture Styles"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Change the sailboat image to the 'Simple Frame, White' style.","Crop the sailboat image to the Double Wave shape.","Recolor the anchor to Gold, Accent 2 Light.","Apply an artistic effect to one image.","Compress all pictures using the Email (96 ppi) setting."]}]},{slug:"shapes",title:"Shapes",description:"Learn how to insert, resize, rotate, reorder, and format shapes in Microsoft Word, including fill, outline, styles, and special effects.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/6OJRvC1C7-U?si=ecqD5EXs5t_XiW_e",practiceFiles:[{name:"Word Shapes Practice File",url:"/practice/word/module-3/shapes/word_shapes_practice.docx"}],sections:[{heading:"Inserting a Shape",blocks:[{type:"paragraph",text:"To insert a shape, go to the Insert tab and click Shapes. Choose a shape from the dropdown menu, then click and drag on the page to draw it."},{type:"image",src:"/images/word/shapes/shapes_insert_menu2.png",alt:"Insert shapes menu"},{type:"image",src:"/images/word/shapes/shapes_insert_in_document3.png",alt:"Shape inserted in document"}]},{heading:"Adding Text to a Shape",blocks:[{type:"paragraph",text:"You can type directly inside most shapes. After inserting the shape, simply begin typing. Use the Home tab to adjust font, size, color, and alignment."},{type:"image",src:"/images/word/shapes/shapes_insert_text.jpg",alt:"Typing inside a shape"}]},{heading:"Resizing and Rotating Shapes",blocks:[{type:"paragraph",text:"Select a shape to display sizing handles. Drag corner handles to resize proportionally. Use the circular rotation handle at the top to rotate the shape."},{type:"image",src:"/images/word/shapes/shapes_resize_select.jpg",alt:"Shape selected with handles"},{type:"image",src:"/images/word/shapes/shapes_resize_handle.jpg",alt:"Resizing shape using handles"},{type:"image",src:"/images/word/shapes/shapes_resize_rotate.jpg",alt:"Rotating a shape"},{type:"paragraph",text:"Some shapes include yellow adjustment handles. These allow you to modify specific parts of the shape, such as banner folds."},{type:"image",src:"/images/word/shapes/shapes_resize_yellow.jpg",alt:"Yellow adjustment handle"}]},{heading:"Changing Shape Order",blocks:[{type:"paragraph",text:"When shapes overlap, you can control which appears in front. Right-click the shape and choose Bring to Front or Send to Back."},{type:"image",src:"/images/word/shapes/shapes_order_menu.jpg",alt:"Bring to front or send to back menu"},{type:"image",src:"/images/word/shapes/shapes_order_result.jpg",alt:"Shape ordering result"},{type:"paragraph",text:"For complex documents, use the Selection Pane (Format tab → Selection Pane) to select and manage overlapping shapes."},{type:"image",src:"/images/word/shapes/shapes_order_selection_pane.jpg",alt:"Selection pane"}]},{heading:"Applying Shape Styles",blocks:[{type:"paragraph",text:"Use Shape Styles on the Format tab to quickly apply preset combinations of fill, outline, and effects."},{type:"image",src:"/images/word/shapes/shapes_style_command.png",alt:"Shape styles command"},{type:"image",src:"/images/word/shapes/shapes_style_menu.png",alt:"Shape styles gallery"},{type:"image",src:"/images/word/shapes/shapes_style_result.jpg",alt:"Shape style applied"}]},{heading:"Changing Shape Fill",blocks:[{type:"paragraph",text:"Click Shape Fill to change the interior color of a shape. You can choose theme colors, gradients, textures, or select No Fill for transparency."},{type:"image",src:"/images/word/shapes/shapes_fill_menu.png",alt:"Shape fill menu"},{type:"image",src:"/images/word/shapes/shapes_fill_result.jpg",alt:"Shape fill result"}]},{heading:"Changing Shape Outline",blocks:[{type:"paragraph",text:"Use Shape Outline to change border color, thickness (weight), dashes, or remove the outline entirely."},{type:"image",src:"/images/word/shapes/shapes_outline_menu.png",alt:"Shape outline menu"},{type:"image",src:"/images/word/shapes/shapes_outline_lines.png",alt:"Outline weight options"},{type:"image",src:"/images/word/shapes/shapes_outline_result.jpg",alt:"Outline result"}]},{heading:"Adding Shape Effects",blocks:[{type:"paragraph",text:"Select Shape Effects to add shadows, reflections, glow, bevel, or 3-D rotation effects."},{type:"image",src:"/images/word/shapes/shapes_effects_menu.png",alt:"Shape effects menu"},{type:"image",src:"/images/word/shapes/shapes_effects_result.jpg",alt:"Shape effects applied"},{type:"paragraph",text:"For advanced customization, open the Format Shape pane to fine-tune bevel size, depth, lighting, and more."},{type:"image",src:"/images/word/shapes/shapes_effects_format.jpg",alt:"Format shape pane"}]},{heading:"Changing to a Different Shape",blocks:[{type:"paragraph",text:"You can convert one shape into another without deleting it. Go to Format → Edit Shape → Change Shape and choose a new option."},{type:"image",src:"/images/word/shapes/shapes_edit_menu.png",alt:"Edit shape menu"},{type:"image",src:"/images/word/shapes/shapes_edit_result.jpg",alt:"Changed shape result"}]},{heading:"Final Example",blocks:[{type:"paragraph",text:"After inserting, formatting, layering, and applying effects, your completed design might look like this:"},{type:"image",src:"/images/word/shapes/shapes_effects_result.jpg",alt:"Completed shapes design"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What must you do to add text inside a shape in Word?",options:["Insert a text box first, then place it over the shape","Click the shape and start typing","Use the Insert > Text > Text Box command","Right-click the shape and select Add Text from a dialog box"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks. Your finished result should resemble the example shown below:"},{type:"list",ordered:!0,items:["Insert a Cloud shape on the right side of the page.","Change the shape fill to white.","Change the outline color to gray.","Apply a Circle Bevel effect from Shape Effects.","Insert a Sun shape and apply a Gold style.","Send the Sun backward so it appears behind the Cloud.","Adjust positioning so the sun peeks out from behind the cloud."]},{type:"image",src:"/images/word/shapes/word2016_shapes_img_edited2.png",alt:"Completed cloud and sun shapes example"}]},{slug:"text-boxes",title:"Text Boxes",description:"Learn how to insert built-in text boxes, draw custom text boxes, resize, move, format, apply styles, and change shapes in Microsoft Word.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/LRGZEi7lSnA?si=HO6IryaHGHU_-Ss6",practiceFiles:[{name:"Word Text Boxes Practice File",url:"/practice/word/module-3/textboxes/word_textboxes_practice.docx"}],sections:[{heading:"Inserting a Built-In Text Box",blocks:[{type:"paragraph",text:"Go to the Insert tab and click Text Box. Choose from the built-in text box gallery to quickly add styled text areas to your document."},{type:"image",src:"/images/word/textboxes/textboxes_insert_command.png",alt:"Insert text box command"},{type:"image",src:"/images/word/textboxes/textboxes_insert_built_in.png",alt:"Built-in text box gallery"}]},{heading:"Drawing a Custom Text Box",blocks:[{type:"paragraph",text:"Select Draw Text Box from the Text Box dropdown. Click and drag anywhere in the document to create a custom-sized text box."},{type:"image",src:"/images/word/textboxes/textboxes_insert_draw.png",alt:"Draw text box option"},{type:"image",src:"/images/word/textboxes/textboxes_insert_drag.png",alt:"Dragging to create text box"}]},{heading:"Typing and Formatting Text",blocks:[{type:"paragraph",text:"Click inside the text box and begin typing. Use the Home tab to change font style, size, color, and alignment."},{type:"image",src:"/images/word/textboxes/textboxes_insert_format.png",alt:"Formatting text inside text box"}]},{heading:"Moving and Resizing Text Boxes",blocks:[{type:"paragraph",text:"Click the border of the text box to select it. Drag from the border to move it. Use the corner sizing handles to resize proportionally."},{type:"image",src:"/images/word/textboxes/textboxes_move2.png",alt:"Moving text box"},{type:"image",src:"/images/word/textboxes/textboxes_resize.png",alt:"Resizing text box"}]},{heading:"Applying Shape Styles",blocks:[{type:"paragraph",text:"When a text box is selected, the Format tab appears. Use Shape Styles to quickly apply preset fill, outline, and effect combinations."},{type:"image",src:"/images/word/textboxes/textboxes_shape_style_command.png",alt:"Shape styles command"},{type:"image",src:"/images/word/textboxes/textboxes_shape_style_menu.png",alt:"Shape styles gallery"},{type:"image",src:"/images/word/textboxes/textboxes_shape_style_result.png",alt:"Shape style applied to text box"}]},{heading:"Changing the Text Box Shape",blocks:[{type:"paragraph",text:"You can convert a text box into another shape. Go to Format → Edit Shape → Change Shape and select a new shape."},{type:"image",src:"/images/word/textboxes/textboxes_edit_shape_command.png",alt:"Edit shape command"},{type:"image",src:"/images/word/textboxes/textboxes_edit_shape_menu.png",alt:"Change shape menu"},{type:"image",src:"/images/word/textboxes/textboxes_edit_shape_result.png",alt:"Changed shape result"}]},{heading:"Final Example",blocks:[{type:"paragraph",text:"After inserting, styling, resizing, and changing shapes, your final promotional layout might look like this:"},{type:"image",src:"/images/word/textboxes/word2016_textbox_img.png",alt:"Completed text box promotional layout"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the purpose of a text box in Word?",options:["To insert a table with formatted cells","To apply a border to a paragraph","To place text anywhere on the page, independent of the main text flow","To create a hyperlink around a block of text"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a built-in text box.","Resize and position it over the image.","Change the fill color to orange.","Change the text to: Up to 75% off!","Apply a Shape Style from the gallery.","Change the text box shape to an Oval."]}]},{slug:"align-order-group",title:"Align, Order & Group Objects",description:"Learn how to align objects, distribute spacing, change object order, flip images, group items, and use the Selection Pane in Microsoft Word.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/6nx5H8yhhWo?si=RWGfiWZfjcgClgPM",practiceFiles:[{name:"Word Align & Group Practice File",url:"/practice/word/module-3/align/word2016_align_order_group_img.docx"}],sections:[{heading:"Aligning Objects",blocks:[{type:"paragraph",text:"Select multiple objects by holding Ctrl and clicking each one. Go to Format → Align to align objects left, center, right, top, middle, or bottom."},{type:"image",src:"/images/word/align/align_select.png",alt:"Selecting multiple objects"},{type:"image",src:"/images/word/align/align_command.png",alt:"Align command dropdown"},{type:"image",src:"/images/word/align/align_right_done.png",alt:"Objects aligned right"}]},{heading:"Distributing Objects Evenly",blocks:[{type:"paragraph",text:"Use Distribute Horizontally or Distribute Vertically to evenly space selected objects."},{type:"image",src:"/images/word/align/align_vertically_command.png",alt:"Distribute vertically command"},{type:"image",src:"/images/word/align/align_vertically_done.png",alt:"Objects evenly distributed"}]},{heading:"Flipping and Rotating Objects",blocks:[{type:"paragraph",text:"Use the Rotate dropdown in the Format tab to rotate or flip objects horizontally or vertically."},{type:"image",src:"/images/word/align/align_flip_command.png",alt:"Flip horizontal command"},{type:"image",src:"/images/word/align/align_flip_done.png",alt:"Object flipped horizontally"}]},{heading:"Changing Object Order",blocks:[{type:"paragraph",text:"When objects overlap, use Bring Forward, Send Backward, Send to Back, or Bring to Front to control layering."},{type:"image",src:"/images/word/align/align_order_intro.png",alt:"Overlapping objects example"},{type:"image",src:"/images/word/align/align_order_sendbackward.png",alt:"Send backward command"},{type:"image",src:"/images/word/align/align_order_sendtoback.png",alt:"Send to back command"}]},{heading:"Using the Selection Pane",blocks:[{type:"paragraph",text:"Open the Selection Pane (Format → Selection Pane) to view, rename, hide, or reorder objects easily."},{type:"image",src:"/images/word/align/align_order_selectionpane_splat.png",alt:"Selection pane open"}]},{heading:"Grouping and Ungrouping Objects",blocks:[{type:"paragraph",text:"Select multiple objects and click Group to combine them into one unit. Use Ungroup to separate them again."},{type:"image",src:"/images/word/align/align_group_command.png",alt:"Group command"},{type:"image",src:"/images/word/align/align_group_done.png",alt:"Grouped objects"},{type:"image",src:"/images/word/align/align_ungroup_command.png",alt:"Ungroup command"},{type:"image",src:"/images/word/align/align_ungroup_done.png",alt:"Ungrouped objects"}]},{heading:"Final Example",blocks:[{type:"paragraph",text:"After aligning, ordering, and grouping objects, your completed layout should look clean, balanced, and professional."},{type:"image",src:"/images/word/align/word2016_align_order_group_img.png",alt:"Final aligned and grouped layout"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does grouping multiple objects do in Word?",options:["Locks the objects so they cannot be moved","Merges their fill colors together","Applies the same style to all selected objects","Lets you move and resize them together as one unit"],correctIndex:3}]}],challenge:[{type:"paragraph",text:"Using the practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Select the four service buttons and align them to the right.","Distribute the buttons vertically so spacing is even.","Group the four buttons together.","Flip the banner image horizontally.","Send the background image to the back.","Use the Selection Pane to confirm object order."]},{type:"image",src:"/images/word/align/word2016_align_order_group_img.png",alt:"Completed alignment challenge result"}]}],level:"Intermediate",estimatedMinutes:40},{moduleNumber:4,moduleSlug:"module-4",title:"References, Review & Collaboration",emoji:"\uD83E\uDD1D",description:"Use headers, footers, track changes, comments, and collaboration tools for professional document workflows.",lessons:[{slug:"headers-and-footers",title:"Headers & Footers",description:"Create, edit, and customize headers and footers in Microsoft Word. Insert preset headers, add dates, page numbers, and format different first pages.",duration:"7 min",videoUrl:"https://www.youtube.com/embed/hxSGN6IJAFc?si=lsvChAnjpi3Hb-kj",practiceFiles:[{name:"Headers & Footers Practice File",url:"/practice/word/module-4/headers/word_headersfooters_practice.docx"}],sections:[{heading:"Creating a Header",blocks:[{type:"paragraph",text:"Go to Insert → Header. Choose a built-in style or select Blank to create your own header."},{type:"image",src:"/images/word/headers/header_preset_command.png",alt:"Header preset command"},{type:"image",src:"/images/word/headers/header_preset_menu3.png",alt:"Header preset gallery"},{type:"image",src:"/images/word/headers/header_preset_type.png",alt:"Typing inside preset header placeholder"}]},{heading:"Working with Preset Header Placeholders",blocks:[{type:"paragraph",text:"Built-in headers include content controls such as [Document Title]. Click inside the placeholder to replace it with your own text."},{type:"paragraph",text:"To remove the placeholder entirely, right-click the field and choose Remove Content Control."},{type:"image",src:"/images/word/headers/header_preset_remove_content.png",alt:"Remove content control option"}]},{heading:"Editing a Header",blocks:[{type:"paragraph",text:"Double-click at the top of the page to open the header area. The Header & Footer Tools Design tab will appear."},{type:"image",src:"/images/word/headers/header_create_click_callout.png",alt:"Double-click header area"},{type:"image",src:"/images/word/headers/header_create_design_tab.png",alt:"Header design tab"}]},{heading:"Inserting Date & Time",blocks:[{type:"paragraph",text:"Click Date & Time inside the header. Choose a format and check Update automatically if needed."},{type:"image",src:"/images/word/headers/header_datetime_command.png",alt:"Date and time command"},{type:"image",src:"/images/word/headers/header_datetime_dialog.png",alt:"Date dialog box"},{type:"image",src:"/images/word/headers/header_datetime_result.png",alt:"Date inserted in header"}]},{heading:"Adding Page Numbers",blocks:[{type:"paragraph",text:"Go to Insert → Page Number and choose placement and alignment."},{type:"image",src:"/images/word/headers/header_design_page_number.png",alt:"Page number menu"}]},{heading:"Different First Page",blocks:[{type:"paragraph",text:"Select Different First Page from the Design tab to remove the header from the first page only."},{type:"image",src:"/images/word/headers/header_design_first_page.png",alt:"Different first page option"}]},{heading:"Removing a Header",blocks:[{type:"paragraph",text:"To remove the header entirely, go to Insert → Header → Remove Header."},{type:"image",src:"/images/word/headers/header_design_remove_header2.png",alt:"Remove header option"}]},{heading:"Closing the Header Area",blocks:[{type:"paragraph",text:"Click Close Header and Footer to return to the main document."},{type:"image",src:"/images/word/headers/header_create_close.png",alt:"Close header button"}]},{heading:"Completed Example",blocks:[{type:"image",src:"/images/word/headers/header_create_result.png",alt:"Completed header example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the purpose of a header in a Word document?",options:["To add decorative borders around the page","To set the document's font and color theme","To display repeated content at the top of every page","To insert a table of contents automatically"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a preset header.","Replace the placeholder text with your name.","Remove any remaining content control boxes.","Insert today’s date and set it to update automatically.","Add page numbers to the bottom right.","Make the first page header different.","Close the Header & Footer tools properly."]}]},{slug:"track-changes",title:"Track Changes",description:"Learn how to track edits in a Word document, accept or reject changes, and review a document's revision history for professional collaboration.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/pLKHMRBR0Z0",practiceFiles:[{name:"Track Changes Practice File",url:"/practice/word/module-4/track-changes/word_trackchanges_practice.docx"}],sections:[{heading:"What Is Track Changes?",blocks:[{type:"paragraph",text:"Track Changes is a feature in Word that records every edit made to a document — insertions, deletions, and formatting changes — so reviewers can see exactly what was modified and by whom."}]},{heading:"Turning On Track Changes",blocks:[{type:"paragraph",text:"Go to the Review tab and click Track Changes to toggle it on. When active, the button appears highlighted and all edits are marked in the document."},{type:"image",src:"/images/word/track-changes/trackchanges_command.png",alt:"Track Changes button on the Review tab"},{type:"image",src:"/images/word/track-changes/trackchanges_active.png",alt:"Track Changes turned on"}]},{heading:"How Changes Appear in the Document",blocks:[{type:"paragraph",text:"Inserted text appears underlined, deleted text appears with a strikethrough, and a change bar appears in the margin to mark edited lines. Each reviewer's changes appear in a different color."},{type:"image",src:"/images/word/track-changes/trackchanges_markup_example.png",alt:"Example of tracked insertions and deletions in a document"}]},{heading:"Controlling What Markup Is Shown",blocks:[{type:"paragraph",text:"Use the Show Markup menu on the Review tab to control which types of changes are visible. You can also switch the display to Simple Markup (margin indicators only) or No Markup (clean view) using the dropdown next to Track Changes."},{type:"image",src:"/images/word/track-changes/trackchanges_showmarkup_menu.png",alt:"Show Markup dropdown menu"},{type:"image",src:"/images/word/track-changes/trackchanges_display_dropdown.png",alt:"All Markup / Simple Markup / No Markup display options"}]},{heading:"Accepting and Rejecting Changes",blocks:[{type:"paragraph",text:"Click inside a tracked change, then choose Accept or Reject from the Review tab. Use Accept All or Reject All to process every change at once."},{type:"image",src:"/images/word/track-changes/trackchanges_accept_reject_buttons.png",alt:"Accept and Reject buttons on the Review tab"},{type:"image",src:"/images/word/track-changes/trackchanges_accept_all_menu.png",alt:"Accept All Changes option in the dropdown"}]},{heading:"Using the Review Pane",blocks:[{type:"paragraph",text:"Click Reviewing Pane on the Review tab to open a sidebar listing all tracked changes and comments in sequence. This is useful for quickly navigating between edits in long documents."},{type:"image",src:"/images/word/track-changes/trackchanges_reviewing_pane.png",alt:"Reviewing pane showing list of tracked changes"}]},{heading:"Locking Track Changes",blocks:[{type:"paragraph",text:"To prevent others from turning off Track Changes, go to Track Changes → Lock Tracking and set a password. Changes cannot be accepted or rejected until the document is unlocked."},{type:"image",src:"/images/word/track-changes/trackchanges_lock_tracking.png",alt:"Lock Tracking option and password dialog"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does the Track Changes feature do in Word?",options:["Automatically corrects spelling errors as you type","Records insertions, deletions, and formatting edits so reviewers can see what was changed","Saves a new version of the document every time you make an edit","Restricts editing so only the document owner can make changes"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the practice document and turn on Track Changes.","Delete a sentence and type a replacement — notice how both the deletion and insertion are marked.","Switch the display to Simple Markup, then back to All Markup.","Accept one tracked change individually.","Use Accept All to accept all remaining changes.","Turn off Track Changes when finished."]}]},{slug:"comments",title:"Comments",description:"Add, reply to, resolve, and delete comments in Word to communicate feedback and collaborate on documents without altering the main content.",duration:"6 min",videoUrl:"https://www.youtube.com/embed/pLKHMRBR0Z0",practiceFiles:[{name:"Comments Practice File",url:"/practice/word/module-4/comments/word_comments_practice.docx"}],sections:[{heading:"What Are Comments?",blocks:[{type:"paragraph",text:"Comments let you attach notes to specific text in a document without changing the content. They appear as colored bubbles in the margin and are ideal for feedback, questions, and review notes."}]},{heading:"Inserting a Comment",blocks:[{type:"paragraph",text:"Select the text you want to comment on, then go to Review → New Comment. A comment balloon appears in the margin linked to your selected text. Type your note inside the balloon."},{type:"image",src:"/images/word/comments/comments_new_comment_command.png",alt:"New Comment button on the Review tab"},{type:"image",src:"/images/word/comments/comments_balloon_example.png",alt:"Comment balloon in the document margin"}]},{heading:"Replying to a Comment",blocks:[{type:"paragraph",text:"Click inside an existing comment balloon and click the Reply button (the curved arrow icon) to add a threaded reply. This creates a conversation thread attached to the same text."},{type:"image",src:"/images/word/comments/comments_reply_button.png",alt:"Reply button inside a comment balloon"},{type:"image",src:"/images/word/comments/comments_thread_example.png",alt:"Threaded comment conversation"}]},{heading:"Resolving a Comment",blocks:[{type:"paragraph",text:"Click the three-dot menu (…) inside a comment balloon and choose Resolve Thread. The comment turns gray to indicate it has been addressed but keeps it visible for reference."},{type:"image",src:"/images/word/comments/comments_resolve_menu.png",alt:"Resolve Thread option in comment menu"},{type:"image",src:"/images/word/comments/comments_resolved_state.png",alt:"Resolved comment shown in gray"}]},{heading:"Deleting a Comment",blocks:[{type:"paragraph",text:"To permanently remove a comment, right-click the comment balloon and choose Delete Comment, or use the Delete button on the Review tab. Choose Delete All Comments in Document to remove all at once."},{type:"image",src:"/images/word/comments/comments_delete_command.png",alt:"Delete Comment option on right-click menu"},{type:"image",src:"/images/word/comments/comments_delete_all_menu.png",alt:"Delete All Comments option on Review tab"}]},{heading:"Navigating Between Comments",blocks:[{type:"paragraph",text:"Use the Previous and Next buttons in the Comments group on the Review tab to jump between comments without scrolling through the document manually."},{type:"image",src:"/images/word/comments/comments_navigate_buttons.png",alt:"Previous and Next comment navigation buttons"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What happens when you resolve a comment in Word?",options:["The comment is permanently deleted from the document","The comment is saved as a footnote at the bottom of the page","The comment turns gray to show it has been addressed but remains visible","The commented text is automatically accepted and formatted"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Select a sentence in the practice document and insert a comment asking a question about the content.","Reply to an existing comment in the document.","Resolve a comment thread.","Delete one comment completely.","Use the Previous and Next buttons to navigate all remaining comments."]}]}],level:"Intermediate",estimatedMinutes:45},{moduleNumber:5,moduleSlug:"module-5",title:"Tables, Charts & Mail Merge",emoji:"\uD83D\uDCCA",description:"Create tables, insert charts, and automate document creation using Mail Merge.",lessons:[{slug:"inserting-tables",title:"Inserting Tables",description:"Learn how to insert tables in Microsoft Word, navigate cells, and understand the different methods for creating tables.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/sOkNrU3JKUA",practiceFiles:[{name:"Inserting Tables Practice File",url:"/practice/word/module-5/tables/word_inserttables_practice.docx"}],sections:[{heading:"Why Use Tables?",blocks:[{type:"paragraph",text:"Tables organize information into rows and columns, making data easier to read and compare. Common uses include schedules, contact lists, comparison charts, and data summaries."}]},{heading:"Inserting a Table Using the Grid",blocks:[{type:"paragraph",text:"Go to Insert → Table. Move your mouse over the grid to select the number of columns and rows, then click to insert the table."},{type:"image",src:"/images/word/tables/tables_insert_grid.png",alt:"Insert Table grid selector"},{type:"image",src:"/images/word/tables/tables_insert_grid_result.png",alt:"Blank table inserted in the document"}]},{heading:"Inserting a Table Using the Dialog Box",blocks:[{type:"paragraph",text:"For precise control, go to Insert → Table → Insert Table. Enter the exact number of columns and rows in the dialog box, then click OK."},{type:"image",src:"/images/word/tables/tables_insert_dialog.png",alt:"Insert Table dialog box with column and row fields"}]},{heading:"Navigating a Table",blocks:[{type:"paragraph",text:"Click any cell to position your cursor there. Press Tab to move to the next cell, or Shift + Tab to move to the previous cell. Pressing Tab in the last cell of the last row automatically adds a new row."},{type:"image",src:"/images/word/tables/tables_navigation_tab.png",alt:"Tab key navigation through table cells"}]},{heading:"Converting Text to a Table",blocks:[{type:"paragraph",text:"If you have a list of text separated by tabs or commas, you can convert it to a table. Select the text, go to Insert → Table → Convert Text to Table, choose the separator, and click OK."},{type:"image",src:"/images/word/tables/tables_convert_text_menu.png",alt:"Convert Text to Table menu option"},{type:"image",src:"/images/word/tables/tables_convert_text_dialog.png",alt:"Convert Text to Table dialog box"}]},{heading:"The Table Design and Layout Tabs",blocks:[{type:"paragraph",text:"When your cursor is inside a table, two contextual tabs appear: Table Design (for styles and borders) and Layout (for rows, columns, alignment, and cell size)."},{type:"image",src:"/images/word/tables/tables_contextual_tabs.png",alt:"Table Design and Layout contextual tabs"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What happens when you press Tab in the very last cell of a table?",options:["The cursor moves to the cell above","Word inserts a new row at the end of the table","The table is deleted and replaced with plain text","A new column is added to the right"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a 4-column, 5-row table using the grid selector.","Type a header label in each of the four columns in the first row.","Fill in two additional rows of data using Tab to move between cells.","Add a new row at the end of the table by pressing Tab in the last cell.","Convert the comma-separated list in the practice file into a table."]}]},{slug:"modifying-tables",title:"Modifying Tables",description:"Learn how to add and delete rows and columns, merge and split cells, resize columns, and apply table styles in Microsoft Word.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/sOkNrU3JKUA",practiceFiles:[{name:"Modifying Tables Practice File",url:"/practice/word/module-5/tables/word_modifytables_practice.docx"}],sections:[{heading:"Adding Rows and Columns",blocks:[{type:"paragraph",text:"Right-click a cell and choose Insert to add rows above or below, or columns to the left or right. You can also hover over the edge of a row or column to see the quick-insert (+) button."},{type:"image",src:"/images/word/tables/tables_insert_row_rightclick.png",alt:"Insert row options in right-click menu"},{type:"image",src:"/images/word/tables/tables_insert_plus_button.png",alt:"Quick-insert plus button on table edge"}]},{heading:"Deleting Rows, Columns, and the Table",blocks:[{type:"paragraph",text:"Select the row or column you want to remove, right-click, and choose Delete Rows or Delete Columns. To delete the entire table, right-click and choose Delete Table."},{type:"image",src:"/images/word/tables/tables_delete_row_menu.png",alt:"Delete Rows option in right-click menu"}]},{heading:"Merging Cells",blocks:[{type:"paragraph",text:"Select two or more adjacent cells, go to the Layout tab, and click Merge Cells. The selected cells combine into one, which is useful for spanning a header across multiple columns."},{type:"image",src:"/images/word/tables/tables_merge_cells_select.png",alt:"Cells selected for merging"},{type:"image",src:"/images/word/tables/tables_merge_cells_result.png",alt:"Merged cell spanning multiple columns"}]},{heading:"Splitting Cells",blocks:[{type:"paragraph",text:"Select a cell, go to the Layout tab, and click Split Cells. Enter the number of columns and rows to divide the cell into, then click OK."},{type:"image",src:"/images/word/tables/tables_split_cells_dialog.png",alt:"Split Cells dialog box"}]},{heading:"Resizing Columns and Rows",blocks:[{type:"paragraph",text:"Drag the column or row border to resize manually. For precise sizing, select a column and use the Width field in the Layout tab's Cell Size group. Click AutoFit → AutoFit Contents to resize all columns to fit their content automatically."},{type:"image",src:"/images/word/tables/tables_resize_drag.png",alt:"Dragging a column border to resize"},{type:"image",src:"/images/word/tables/tables_autofit_menu.png",alt:"AutoFit Contents option in Layout tab"}]},{heading:"Applying Table Styles",blocks:[{type:"paragraph",text:"Click inside the table, go to the Table Design tab, and browse the Table Styles gallery. Hover over any style to preview it on your table, then click to apply."},{type:"image",src:"/images/word/tables/tables_style_gallery.png",alt:"Table Styles gallery on the Table Design tab"},{type:"image",src:"/images/word/tables/tables_style_applied.png",alt:"Table with a formatted style applied"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does the Merge Cells command do in a Word table?",options:["Combines selected adjacent cells into a single cell","Copies the content of one cell into all selected cells","Automatically fills cells with sequential numbers","Removes the borders between all cells in the table"],correctIndex:0}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the practice table and add a new row at the bottom.","Delete the third column from the table.","Merge the cells in the first row across all columns to create a spanning header.","Use AutoFit Contents to resize all columns to fit their text.","Apply a Table Style of your choice from the Table Design tab."]}]},{slug:"inserting-charts",title:"Inserting Charts",description:"Learn how to insert and customize charts in Microsoft Word to visually represent data from a built-in spreadsheet editor.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/Jqa9A3FuUss",practiceFiles:[{name:"Inserting Charts Practice File",url:"/practice/word/module-5/charts/word_charts_practice.docx"}],sections:[{heading:"Inserting a Chart",blocks:[{type:"paragraph",text:"Go to Insert → Chart. The Insert Chart dialog opens with a list of chart types on the left. Select the type you want (such as Column, Bar, Pie, or Line), choose a subtype, and click OK."},{type:"image",src:"/images/word/charts/charts_insert_command.png",alt:"Chart button on the Insert tab"},{type:"image",src:"/images/word/charts/charts_insert_dialog.png",alt:"Insert Chart dialog with chart types"}]},{heading:"Editing Chart Data",blocks:[{type:"paragraph",text:"After inserting a chart, a small Excel-style spreadsheet opens next to it. Edit the sample data in this window — the chart updates automatically as you type. Close the data window when you are done."},{type:"image",src:"/images/word/charts/charts_data_spreadsheet.png",alt:"Chart data spreadsheet editor"},{type:"image",src:"/images/word/charts/charts_data_result.png",alt:"Chart updated to reflect new data"}]},{heading:"Changing the Chart Type",blocks:[{type:"paragraph",text:"Right-click the chart and choose Change Chart Type to switch to a different visualization. You can switch between column, bar, line, pie, and many other types."},{type:"image",src:"/images/word/charts/charts_change_type_menu.png",alt:"Change Chart Type option in right-click menu"}]},{heading:"Chart Design and Format Tabs",blocks:[{type:"paragraph",text:"Clicking a chart reveals two contextual tabs: Chart Design (for layouts, styles, and data) and Format (for shapes, fills, and text formatting). Use these to customize the appearance of your chart."},{type:"image",src:"/images/word/charts/charts_contextual_tabs.png",alt:"Chart Design and Format contextual tabs"}]},{heading:"Adding Chart Titles and Labels",blocks:[{type:"paragraph",text:"On the Chart Design tab, click Add Chart Element to add or adjust chart titles, axis titles, data labels, legends, and gridlines."},{type:"image",src:"/images/word/charts/charts_add_element_menu.png",alt:"Add Chart Element menu"},{type:"image",src:"/images/word/charts/charts_title_added.png",alt:"Chart with a title and data labels"}]},{heading:"Applying a Chart Style",blocks:[{type:"paragraph",text:"In the Chart Design tab, browse the Chart Styles gallery to quickly apply a coordinated color scheme and style to the entire chart."},{type:"image",src:"/images/word/charts/charts_style_gallery.png",alt:"Chart Styles gallery on the Chart Design tab"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What opens automatically when you insert a chart in Word?",options:["A file browser to import chart data from a CSV file","A small spreadsheet editor where you enter the chart data","A wizard that asks you to choose colors and fonts","The Format Cells dialog from Microsoft Excel"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a Column chart into the practice document.","Replace the sample data with your own values (at least 3 categories, 2 series).","Add a chart title.","Add data labels to the chart.","Change the chart type to a Bar chart.","Apply a chart style from the Chart Design tab."]}]},{slug:"mail-merge-basics",title:"Mail Merge Basics",description:"Learn how to use Mail Merge in Word to automatically generate personalized letters, envelopes, and labels from a data source.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/Xh_gWMqF17c",practiceFiles:[{name:"Mail Merge Letter Template",url:"/practice/word/module-5/mail-merge/word_mailmerge_letter.docx"},{name:"Mail Merge Data Source",url:"/practice/word/module-5/mail-merge/word_mailmerge_data.xlsx"}],sections:[{heading:"What Is Mail Merge?",blocks:[{type:"paragraph",text:"Mail Merge combines a letter template (the main document) with a list of recipients (the data source) to automatically produce personalized copies. It is commonly used for form letters, address labels, and name badges."}]},{heading:"Step 1 – Start the Mail Merge",blocks:[{type:"paragraph",text:"Go to Mailings → Start Mail Merge and choose the document type: Letters, Envelopes, Labels, or Email Messages. For this lesson, select Letters."},{type:"image",src:"/images/word/mail-merge/mailmerge_start_command.png",alt:"Start Mail Merge button on Mailings tab"},{type:"image",src:"/images/word/mail-merge/mailmerge_start_menu.png",alt:"Mail merge document type options"}]},{heading:"Step 2 – Select Recipients",blocks:[{type:"paragraph",text:"Click Select Recipients on the Mailings tab. Choose Use an Existing List to connect an Excel spreadsheet or CSV file as your data source. Navigate to the file and click Open, then select the correct sheet."},{type:"image",src:"/images/word/mail-merge/mailmerge_select_recipients.png",alt:"Select Recipients menu options"},{type:"image",src:"/images/word/mail-merge/mailmerge_select_sheet_dialog.png",alt:"Select Table dialog to choose the data sheet"}]},{heading:"Step 3 – Insert Merge Fields",blocks:[{type:"paragraph",text:"Place your cursor in the document where you want personalized data (such as the recipient's name). Click Insert Merge Field on the Mailings tab and choose the field from your data source, such as FirstName or City."},{type:"image",src:"/images/word/mail-merge/mailmerge_insert_field_button.png",alt:"Insert Merge Field button on Mailings tab"},{type:"image",src:"/images/word/mail-merge/mailmerge_field_inserted.png",alt:"Merge field inserted in the letter template"}]},{heading:"Step 4 – Preview Results",blocks:[{type:"paragraph",text:"Click Preview Results on the Mailings tab to see how the first recipient's data fills in. Use the arrow buttons to cycle through all records and confirm the merge looks correct."},{type:"image",src:"/images/word/mail-merge/mailmerge_preview_button.png",alt:"Preview Results button"},{type:"image",src:"/images/word/mail-merge/mailmerge_preview_result.png",alt:"Letter preview with real recipient data filled in"}]},{heading:"Step 5 – Finish & Merge",blocks:[{type:"paragraph",text:"Click Finish & Merge on the Mailings tab. Choose Edit Individual Documents to create a new document with all personalized copies combined, or Print Documents to send them directly to the printer."},{type:"image",src:"/images/word/mail-merge/mailmerge_finish_merge_menu.png",alt:"Finish & Merge options menu"},{type:"image",src:"/images/word/mail-merge/mailmerge_merged_document.png",alt:"Final merged document with multiple personalized letters"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the role of the data source in a Mail Merge?",options:["It stores the letter template with the merge fields","It contains the list of recipients and their personalized information","It controls the page layout and print settings","It defines the styles and themes applied to each letter"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the letter template practice file and start a Letters mail merge.","Connect the provided Excel data source file as your recipient list.","Insert merge fields for FirstName, LastName, and City in the appropriate places in the letter.","Use Preview Results to check that the first three records display correctly.","Use Finish & Merge → Edit Individual Documents to produce the complete set of letters."]}]}],level:"Intermediate",estimatedMinutes:50},{moduleNumber:6,moduleSlug:"module-6",title:"Advanced Formatting",emoji:"\uD83D\uDCC4",description:"Master advanced document layout techniques including columns, page formatting, and structured documents.",lessons:[{slug:"page-layout",title:"Page Layout",description:"Learn how to adjust margins, orientation, paper size, and use the Page Setup dialog box in Microsoft Word.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/aRvVeiWmFZk",practiceFiles:[{name:"Word Page Layout Practice File",url:"/practice/word/module-6/page-layout/word_pagelayout_practice.docx"}],sections:[{heading:"Changing Margins",blocks:[{type:"paragraph",text:"Margins control the space between your text and the edge of the page. To change margins, go to the Layout tab and click Margins."},{type:"image",src:"/images/word/page-layout/layout_margins_command.png",alt:"Margins command button"},{type:"image",src:"/images/word/page-layout/layout_margins_menu.png",alt:"Margins dropdown menu"}]},{heading:"Custom Margins",blocks:[{type:"paragraph",text:"For precise control, click Custom Margins to open the Page Setup dialog box. Here you can manually adjust top, bottom, left, and right margins."},{type:"image",src:"/images/word/page-layout/layout_custom_margins_menu.png",alt:"Custom margins option"},{type:"image",src:"/images/word/page-layout/layout_custom_margins_page_setup.png",alt:"Page setup margins dialog"}]},{heading:"Changing Page Orientation",blocks:[{type:"paragraph",text:"Orientation determines whether your document prints vertically (Portrait) or horizontally (Landscape)."},{type:"image",src:"/images/word/page-layout/layout_orientation_command.png",alt:"Orientation command"},{type:"image",src:"/images/word/page-layout/layout_orientation_menu.png",alt:"Orientation dropdown menu"},{type:"image",src:"/images/word/page-layout/layout_orientation_landscape.png",alt:"Landscape orientation result"},{type:"image",src:"/images/word/page-layout/layout_orientation_portrait.png",alt:"Portrait orientation result"}]},{heading:"Changing Paper Size",blocks:[{type:"paragraph",text:"You can change the paper size from the Layout tab by clicking Size. Word provides preset sizes such as Letter, Legal, and A4."},{type:"image",src:"/images/word/page-layout/layout_size_command.png",alt:"Size command button"},{type:"image",src:"/images/word/page-layout/layout_size_menu.png",alt:"Paper size dropdown menu"}]},{heading:"Custom Paper Size",blocks:[{type:"paragraph",text:"To define a custom paper size, click More Paper Sizes to open the Page Setup dialog box and manually enter width and height."},{type:"image",src:"/images/word/page-layout/layout_custom_size_menu.png",alt:"More paper sizes option"},{type:"image",src:"/images/word/page-layout/layout_custom_size_page_setup.png",alt:"Custom paper size dialog"}]},{heading:"Using the Page Setup Dialog Box",blocks:[{type:"paragraph",text:"The Page Setup launcher provides full control over margins, paper size, orientation, and layout options in one place."},{type:"image",src:"/images/word/page-layout/layout_page_setup.png",alt:"Page setup launcher"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After adjusting margins, orientation, and paper size, your completed document should look like this:"},{type:"image",src:"/images/word/page-layout/word2016_page_layout_img.png",alt:"Completed page layout example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which page orientation makes the page wider than it is tall?",options:["Portrait","Landscape","Custom","Letter"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Change the margins to Narrow.","Set orientation to Landscape.","Change the paper size to Legal.","Create custom margins of 0.75 inches on all sides.","Open the Page Setup dialog box and review all layout settings."]}]},{slug:"indents-and-tabs",title:"Indents and Tabs",description:"Learn how to use the ruler, tab selector, and indentation tools to control paragraph layout in Microsoft Word.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/vJGYWVe52T4?si=P2fE667vh32d5DfJ",practiceFiles:[{name:"Word Indents & Tabs Practice File",url:"/practice/word/module-6/indents-tabs/word_indentstabs_practice.docx"}],sections:[{heading:"Using the Ruler",blocks:[{type:"paragraph",text:"The ruler allows you to visually control indents and tab stops. If it is not visible, go to the View tab and check Ruler."},{type:"image",src:"/images/word/indents-tabs/2016-01-05_15-15-13.png",alt:"Enabling the ruler in Word"}]},{heading:"Adjusting Indents",blocks:[{type:"paragraph",text:"Indentation moves text inward from the margin. You can adjust the left indent, right indent, first-line indent, or hanging indent using the ruler or the Layout tab."},{type:"image",src:"/images/word/indents-tabs/indent_commands_before.png",alt:"Indent controls before adjustment"},{type:"image",src:"/images/word/indents-tabs/indent_commands_after.png",alt:"Indent controls after adjustment"}]},{heading:"First-Line Indent",blocks:[{type:"paragraph",text:"A first-line indent moves only the first line of a paragraph inward. This is commonly used in essays and formal writing."},{type:"image",src:"/images/word/indents-tabs/tabs_inline_first.png",alt:"First line indent example"}]},{heading:"Hanging Indent",blocks:[{type:"paragraph",text:"A hanging indent moves all lines except the first inward. This format is commonly used for Works Cited or reference pages."},{type:"image",src:"/images/word/indents-tabs/indent_hanging_example2.png",alt:"Hanging indent example"}]},{heading:"Using Tab Stops",blocks:[{type:"paragraph",text:"Tab stops allow you to align text precisely. You can set left, center, right, or decimal tabs using the tab selector and ruler."},{type:"image",src:"/images/word/indents-tabs/tabs_inline_center.png",alt:"Center tab example"},{type:"image",src:"/images/word/indents-tabs/tabs_inline_left_indent.png",alt:"Left tab example"}]},{heading:"Real-World Example",blocks:[{type:"paragraph",text:"Below is an example of a professionally formatted resume section using indents and tab stops."},{type:"image",src:"/images/word/indents-tabs/word2016_indents2_img1.png",alt:"Completed resume example"},{type:"image",src:"/images/word/indents-tabs/word2016_indents2_img2.png",alt:"Completed resume layout"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a hanging indent?",options:["All lines of a paragraph are indented equally","Only the first line is indented; remaining lines stay at the margin","All lines except the first are indented","The paragraph is indented from the right margin only"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Enable the ruler.","Apply a first-line indent to the body paragraph.","Create a hanging indent for the Works Cited section.","Use tab stops to align dates to the right margin.","Adjust left and right indents for the Skills section."]}]},{slug:"line-paragraph-spacing",title:"Line and Paragraph Spacing",description:"Learn how to adjust line spacing and paragraph spacing for professional document formatting.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/mXWvKHWe2Co?si=ALpc88kNziEZhfGI",practiceFiles:[{name:"Word Line and Paragraph Spacing Practice File",url:"/practice/word/module-6/line-paragraph-spacing/word_lineparagraphspacing_practice.docx"}],sections:[{heading:"Using the Line Spacing Menu",blocks:[{type:"paragraph",text:"You can quickly change line spacing from the Line and Paragraph Spacing button in the Paragraph group on the Home tab."},{type:"image",src:"/images/word/line-paragraph-spacing/2016-01-11_09-49-05.png",alt:"Line spacing dropdown menu"},{type:"image",src:"/images/word/line-paragraph-spacing/2016-01-11_13-03-40.png",alt:"Line spacing applied result"}]},{heading:"Opening Line Spacing Options",blocks:[{type:"paragraph",text:"For advanced spacing control, open the Paragraph dialog box and use the Line spacing dropdown menu."},{type:"image",src:"/images/word/line-paragraph-spacing/2016-01-08_10-58-38.png",alt:"Paragraph dialog box with line spacing options"}]},{heading:"Spacing Before and After Paragraphs",blocks:[{type:"paragraph",text:"Paragraph spacing adds space before or after entire paragraphs. This creates cleaner documents without using extra blank lines."},{type:"image",src:"/images/word/line-paragraph-spacing/2016-01-08_10-42-20.png",alt:"Before and After spacing settings"},{type:"image",src:"/images/word/line-paragraph-spacing/2016-01-11_09-51-32.png",alt:"Paragraph spacing result example"}]},{heading:"Professional Example",blocks:[{type:"paragraph",text:"Proper spacing improves readability and gives letters and resumes a clean, professional look."},{type:"image",src:"/images/word/line-paragraph-spacing/2016-01-08_10-34-42.png",alt:"Letter before spacing adjustment"},{type:"image",src:"/images/word/line-paragraph-spacing/word2016_linespacing_img3.png",alt:"Letter after spacing adjustment"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Which spacing setting adds extra space between paragraphs without using blank lines?",options:["Line spacing set to Double","Spacing Before or After paragraphs","Increase Indent","Column spacing"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Change the body text to 1.5 line spacing.","Add spacing after each paragraph.","Remove unnecessary blank lines created using Enter.","Adjust the document to look professionally formatted."]}]},{slug:"breaks",title:"Breaks (Page, Column & Section)",description:"Learn how to insert, manage, and delete page breaks, column breaks, and section breaks in Microsoft Word.",duration:"12 min",videoUrl:"https://www.youtube.com/embed/78fvQ9Ks8DA",practiceFiles:[{name:"Word Breaks Practice File",url:"/practice/word/module-6/breaks/word_breaks_practice.docx"}],sections:[{heading:"Understanding Breaks",blocks:[{type:"paragraph",text:"Breaks allow you to control how content flows in your document. You can force text onto a new page, start a new column, or create a new section with different formatting."},{type:"image",src:"/images/word/breaks/break_section_intro.png",alt:"Break types overview"}]},{heading:"Inserting a Page Break",blocks:[{type:"paragraph",text:"A page break forces content to begin on the next page. Go to the Insert tab and click Page Break, or press Ctrl + Enter."},{type:"image",src:"/images/word/breaks/break_page_command.png",alt:"Insert page break command"},{type:"image",src:"/images/word/breaks/break_page_done.png",alt:"Page break result"}]},{heading:"Inserting a Section Break",blocks:[{type:"paragraph",text:"Section breaks allow different formatting in different parts of the document, such as changing columns, margins, or orientation."},{type:"image",src:"/images/word/breaks/break_section_command.png",alt:"Section break menu"},{type:"image",src:"/images/word/breaks/break_section_added.png",alt:"Section break added"}]},{heading:"Types of Section Breaks",blocks:[{type:"paragraph",text:"Word provides several types of section breaks: Next Page, Continuous, Even Page, and Odd Page. Continuous section breaks are useful when changing formatting without starting a new page."},{type:"image",src:"/images/word/breaks/break_section_start.png",alt:"Section break options"}]},{heading:"Column Breaks",blocks:[{type:"paragraph",text:"A column break forces text to move to the next column. This is useful when working with multi-column layouts."},{type:"image",src:"/images/word/breaks/break_other_intro.png",alt:"Column break option"}]},{heading:"Viewing Breaks with Show/Hide",blocks:[{type:"paragraph",text:"Breaks are invisible by default. Click the Show/Hide \xb6 button on the Home tab to display formatting marks and see where breaks are located."},{type:"image",src:"/images/word/breaks/break_delete_showhide.png",alt:"Show hide formatting marks"},{type:"image",src:"/images/word/breaks/break_page_splat_showhide.png",alt:"Visible page break"}]},{heading:"Deleting a Break",blocks:[{type:"paragraph",text:"To delete a break, place your cursor directly before it and press Delete. Removing a section break may change formatting in your document."},{type:"image",src:"/images/word/breaks/break_delete_placeinsertion.png",alt:"Placing insertion point before break"},{type:"image",src:"/images/word/breaks/break_delete_done.png",alt:"Break removed result"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After inserting and managing breaks correctly, your document should have clean page transitions and properly formatted sections."},{type:"image",src:"/images/word/breaks/word2016_breaks_img_combined.png",alt:"Completed breaks example"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What type of break forces content to start on a new page?",options:["Page break","Column break","Continuous section break","Next Page section break"],correctIndex:0}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Insert a page break before the 'Monthly Revenue' section.","Insert a section break before the 'Clients Overview' section.","Change one section to a two-column layout.","Use Show/Hide to display formatting marks.","Delete an unnecessary page or section break."]}]},{slug:"columns",title:"Columns",description:"Learn how to create, customize, and remove columns in Microsoft Word, including how to use column breaks and adjust column spacing.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/X1n2VG1yxFs?si=WLrIc_XyiWiQtSBB",practiceFiles:[{name:"Word Columns Practice File",url:"/practice/word/module-6/columns/word_columns_practice.docx"}],sections:[{heading:"Adding Columns",blocks:[{type:"paragraph",text:"Columns allow text to flow from top to bottom in one column, then continue at the top of the next column—similar to newspapers or newsletters."},{type:"paragraph",text:"To add columns, select your text, go to the Layout tab, and click Columns. Then choose Two, Three, or another preset option."},{type:"image",src:"/images/word/columns/columns_add_select.png",alt:"Selecting text before applying columns"},{type:"image",src:"/images/word/columns/columns_add_menu.png",alt:"Columns dropdown menu"},{type:"image",src:"/images/word/columns/columns_add_result.png",alt:"Text displayed in two columns"}]},{heading:"Inserting a Column Break",blocks:[{type:"paragraph",text:"A column break forces text to move to the top of the next column immediately."},{type:"paragraph",text:"Place your insertion point where you want the new column to begin. Then go to Layout → Breaks → Column."},{type:"image",src:"/images/word/columns/columns_break_menu.png",alt:"Breaks menu showing column break"},{type:"image",src:"/images/word/columns/columns_break_insert_callout.png",alt:"Inserting a column break"},{type:"image",src:"/images/word/columns/columns_break_result.png",alt:"Column break result"}]},{heading:"Customizing Columns",blocks:[{type:"paragraph",text:"To adjust column width or spacing, click Columns and choose More Columns."},{type:"paragraph",text:"From the Columns dialog box, you can change the number of columns, adjust spacing, and add a line between columns."},{type:"image",src:"/images/word/columns/columns_more_columns.png",alt:"More Columns dialog box"},{type:"image",src:"/images/word/columns/columns_indent_markers.png",alt:"Column spacing and indent markers"}]},{heading:"Removing Columns",blocks:[{type:"paragraph",text:"To remove columns, select the text and go to Layout → Columns → One."},{type:"image",src:"/images/word/columns/columns_remove_menu.png",alt:"Columns menu showing One column"}]},{heading:"Removing a Column Break",blocks:[{type:"paragraph",text:"To delete a column break, turn on Show/Hide (\xb6) to reveal formatting marks. Then place your insertion point before the break and press Delete."},{type:"image",src:"/images/word/columns/columns_remove_breaks_showhide.png",alt:"Show/Hide formatting marks"},{type:"image",src:"/images/word/columns/columns_remove_breaks_insertion.png",alt:"Selecting column break"},{type:"image",src:"/images/word/columns/columns_remove_breaks_result.png",alt:"Column break removed"}]},{heading:"Final Result",blocks:[{type:"paragraph",text:"After applying columns and adjusting spacing properly, your newsletter should look clean, balanced, and professionally formatted."},{type:"image",src:"/images/word/columns/word2016_columns2_img.png",alt:"Completed newsletter with two columns"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is a column break used for?",options:["To remove all columns and return to a single-column layout","To add a line between two columns","To force text to the top of the next column","To change the number of columns in the document"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Using the provided practice file, complete the following tasks:"},{type:"list",ordered:!0,items:["Convert the Community Reminders section into two columns.","Insert a column break after the first bullet.","Adjust spacing between columns using More Columns.","Add a line between columns.","Remove the column break.","Return the section to one column."]}]}],level:"Advanced",estimatedMinutes:50},{moduleNumber:7,moduleSlug:"module-7",title:"Advanced Styles & Themes",emoji:"⚙️",description:"Deep dive into document styles, themes, and advanced formatting techniques used for certification-level workflows.",lessons:[{slug:"working-with-styles",title:"Working with Styles",description:"Learn how to apply and manage Word's built-in paragraph and character styles to format documents consistently and efficiently.",duration:"10 min",videoUrl:"https://www.youtube.com/embed/fLmJV5RVJoM",practiceFiles:[{name:"Working with Styles Practice File",url:"/practice/word/module-7/styles/word_styles_practice.docx"}],sections:[{heading:"What Are Styles?",blocks:[{type:"paragraph",text:"A style is a saved collection of formatting settings — font, size, color, spacing, and more — that can be applied to text in a single click. Using styles ensures consistent formatting throughout your document and makes updates fast and easy."}]},{heading:"The Styles Gallery",blocks:[{type:"paragraph",text:"The Styles gallery is located on the Home tab in the Styles group. It displays a row of preset styles such as Normal, Heading 1, Heading 2, Title, and more. Hover over any style to see a live preview before applying it."},{type:"image",src:"/images/word/styles/styles_gallery_home_tab.png",alt:"Styles gallery on the Home tab"},{type:"image",src:"/images/word/styles/styles_gallery_expanded.png",alt:"Expanded styles gallery"}]},{heading:"Applying a Style",blocks:[{type:"paragraph",text:"Click inside the paragraph you want to format (or select specific text for a character style), then click the style name in the gallery. The formatting is applied instantly."},{type:"image",src:"/images/word/styles/styles_apply_heading1.png",alt:"Applying Heading 1 style to a paragraph"},{type:"image",src:"/images/word/styles/styles_apply_result.png",alt:"Paragraph formatted with Heading 1 style"}]},{heading:"Paragraph vs. Character Styles",blocks:[{type:"paragraph",text:"Paragraph styles (marked with a \xb6 symbol) apply formatting to an entire paragraph. Character styles (marked with an a symbol) apply formatting only to selected text within a paragraph."},{type:"image",src:"/images/word/styles/styles_type_indicators.png",alt:"Paragraph and character style type indicators"}]},{heading:"Opening the Styles Pane",blocks:[{type:"paragraph",text:"Click the small launcher arrow at the bottom-right corner of the Styles group to open the Styles pane. This gives you access to all available styles, not just those shown in the gallery."},{type:"image",src:"/images/word/styles/styles_pane_launcher.png",alt:"Styles pane launcher arrow"},{type:"image",src:"/images/word/styles/styles_pane_open.png",alt:"Styles pane showing all available styles"}]},{heading:"Clearing a Style",blocks:[{type:"paragraph",text:"To remove formatting applied by a style, select the text and click Clear All in the Styles pane, or choose Normal from the Styles gallery to reset to the default paragraph style."},{type:"image",src:"/images/word/styles/styles_clear_all.png",alt:"Clear All option in the Styles pane"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the main advantage of using Styles in Word?",options:["They automatically translate the document into other languages","They let you apply consistent, saved formatting combinations with a single click","They lock the document so no one else can edit it","They convert a Word document into a PDF automatically"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the practice document and apply the Heading 1 style to the first line.","Apply Heading 2 to each section title in the document.","Apply the Normal style to a body paragraph that was incorrectly formatted.","Open the Styles pane and identify one character style and one paragraph style.","Use Clear All to remove formatting from one heading and observe the result."]}]},{slug:"modifying-styles",title:"Modifying Styles",description:"Learn how to customize existing Word styles so that formatting updates apply automatically throughout the entire document.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/fLmJV5RVJoM",practiceFiles:[{name:"Modifying Styles Practice File",url:"/practice/word/module-7/modifying-styles/word_modifyingstyles_practice.docx"}],sections:[{heading:"Why Modify Styles?",blocks:[{type:"paragraph",text:"Instead of manually reformatting every heading or paragraph, you can modify the underlying style. Every paragraph using that style updates automatically — saving time and ensuring consistency throughout the document."}]},{heading:"Update a Style to Match Selection",blocks:[{type:"paragraph",text:"Apply manual formatting to one paragraph, then right-click the style name in the gallery and choose Update [Style Name] to Match Selection. All text using that style updates to match."},{type:"image",src:"/images/word/styles/styles_update_to_match.png",alt:"Update Heading 1 to Match Selection option"}]},{heading:"Modifying a Style with the Modify Dialog",blocks:[{type:"paragraph",text:"Right-click a style in the gallery or Styles pane and choose Modify. The Modify Style dialog box gives you complete control over font, paragraph settings, borders, numbering, and more."},{type:"image",src:"/images/word/styles/styles_modify_rightclick.png",alt:"Right-click Modify option on a style"},{type:"image",src:"/images/word/styles/styles_modify_dialog.png",alt:"Modify Style dialog box"}]},{heading:"Formatting Options in the Modify Dialog",blocks:[{type:"paragraph",text:"Inside the Modify Style dialog, use the Format button at the bottom-left to access advanced settings like Font, Paragraph, Tabs, Borders, and Numbering."},{type:"image",src:"/images/word/styles/styles_modify_format_button.png",alt:"Format dropdown in Modify Style dialog"}]},{heading:"Updating Automatically vs. This Document Only",blocks:[{type:"paragraph",text:"In the Modify Style dialog you can choose whether to apply the change to this document only or to new documents based on the current template. For most cases, choose Only in this document."},{type:"image",src:"/images/word/styles/styles_modify_scope_options.png",alt:"Scope options at the bottom of Modify Style dialog"}]},{heading:"Creating a New Style",blocks:[{type:"paragraph",text:"To save a custom combination as a new style, format a paragraph the way you want, then open the Styles pane and click New Style (the first icon at the bottom). Give it a name and set the type to Paragraph or Character."},{type:"image",src:"/images/word/styles/styles_new_style_button.png",alt:"New Style button at the bottom of the Styles pane"},{type:"image",src:"/images/word/styles/styles_new_style_dialog.png",alt:"Create New Style from Formatting dialog"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What happens when you modify a style in Word?",options:["Only the currently selected paragraph is changed","All paragraphs in the document using that style update automatically","The style is deleted and replaced with a new one","Word creates a copy of the style with a new name"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Apply bold and change the font color of one Heading 1 paragraph, then use Update Heading 1 to Match Selection.","Open the Modify Style dialog for Normal and change the font to Calibri 12pt.","Observe that all Normal-styled paragraphs updated to reflect the change.","Use the Format → Paragraph option in the Modify dialog to add 6pt spacing after the Normal style.","Create a brand new style named 'Callout' using blue 11pt italic text."]}]},{slug:"style-sets",title:"Style Sets",description:"Learn how to switch between Word's built-in Style Sets to instantly change the look and feel of headings and body text across your entire document.",duration:"7 min",videoUrl:"https://www.youtube.com/embed/CvnSSnm6bAc",practiceFiles:[{name:"Style Sets Practice File",url:"/practice/word/module-7/style-sets/word_stylesets_practice.docx"}],sections:[{heading:"What Is a Style Set?",blocks:[{type:"paragraph",text:"A Style Set is a coordinated collection of heading, body, and paragraph style definitions. Switching Style Sets changes the fonts, sizes, and spacing used by all built-in styles at once — without removing the styles themselves."}]},{heading:"Accessing Style Sets",blocks:[{type:"paragraph",text:"Go to the Design tab and look at the Document Formatting group. The row of thumbnails at the top represents the available Style Sets. Hover over any thumbnail to preview the effect on your document."},{type:"image",src:"/images/word/style-sets/stylesets_design_tab.png",alt:"Style Sets row on the Design tab"},{type:"image",src:"/images/word/style-sets/stylesets_hover_preview.png",alt:"Live preview of a Style Set"}]},{heading:"Applying a Style Set",blocks:[{type:"paragraph",text:"Click a Style Set thumbnail to apply it. Word updates all heading and body styles throughout the document to match the new set."},{type:"image",src:"/images/word/style-sets/stylesets_apply_result.png",alt:"Document after applying a different Style Set"}]},{heading:"Restoring to the Default Style Set",blocks:[{type:"paragraph",text:"To return to Word's original default styles, click the first thumbnail (Default) or right-click the Style Set gallery and choose Reset to the Default Style Set."},{type:"image",src:"/images/word/style-sets/stylesets_reset_default.png",alt:"Reset to Default Style Set option"}]},{heading:"Saving a Custom Style Set",blocks:[{type:"paragraph",text:"After customizing styles, you can save them as a new Style Set. Click the More arrow in the Document Formatting group to expand the gallery, then choose Save as a New Style Set. Name it and click Save."},{type:"image",src:"/images/word/style-sets/stylesets_save_new.png",alt:"Save as a New Style Set option"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What does switching a Style Set do to your document?",options:["It deletes all existing paragraphs and replaces them with placeholder text","It changes the fonts, sizes, and spacing of all built-in styles across the entire document","It applies a background color to every page in the document","It locks the document formatting so no more changes can be made"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the practice document and confirm headings are styled with Heading 1 and Heading 2.","Go to the Design tab and hover over three different Style Sets to preview them.","Apply the Lines (Stylish) Style Set and observe the changes.","Try a second Style Set such as Centered.","Reset the document to the Default Style Set.","Modify one heading style, then save the result as a new Style Set named 'My Style Set'."]}]},{slug:"using-themes",title:"Using Themes",description:"Learn how to apply and customize document themes to control the color palette, fonts, and graphic effects used throughout your Word document.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/CvnSSnm6bAc",practiceFiles:[{name:"Themes Practice File",url:"/practice/word/module-7/themes/word_themes_practice.docx"}],sections:[{heading:"What Is a Theme?",blocks:[{type:"paragraph",text:"A theme is a coordinated set of colors, fonts, and graphic effects applied to a document. Themes are different from Style Sets — a theme defines the color palette and typefaces available, while a Style Set defines how those elements are used in headings and body text."}]},{heading:"Applying a Theme",blocks:[{type:"paragraph",text:"Go to the Design tab and click the Themes button (far left in the Document Formatting group). A gallery of built-in themes appears. Hover over any theme to preview it live, then click to apply."},{type:"image",src:"/images/word/themes/themes_button_design_tab.png",alt:"Themes button on the Design tab"},{type:"image",src:"/images/word/themes/themes_gallery.png",alt:"Themes gallery"},{type:"image",src:"/images/word/themes/themes_apply_preview.png",alt:"Live preview of a theme on the document"}]},{heading:"Changing Theme Colors",blocks:[{type:"paragraph",text:"Click Colors in the Document Formatting group to choose a different color palette independently of the full theme. This lets you mix colors from one theme with fonts from another."},{type:"image",src:"/images/word/themes/themes_colors_button.png",alt:"Colors button on Design tab"},{type:"image",src:"/images/word/themes/themes_colors_gallery.png",alt:"Theme color palette gallery"}]},{heading:"Changing Theme Fonts",blocks:[{type:"paragraph",text:"Click Fonts in the Document Formatting group to choose a different font pairing. Each entry shows a Heading font and Body font combination."},{type:"image",src:"/images/word/themes/themes_fonts_button.png",alt:"Fonts button on Design tab"},{type:"image",src:"/images/word/themes/themes_fonts_gallery.png",alt:"Theme font pairing gallery"}]},{heading:"Changing Theme Effects",blocks:[{type:"paragraph",text:"Click Effects to apply a different visual style to shapes, SmartArt, and charts in the document. Effects control shadows, reflections, and 3D formatting."},{type:"image",src:"/images/word/themes/themes_effects_gallery.png",alt:"Theme effects gallery"}]},{heading:"Saving a Custom Theme",blocks:[{type:"paragraph",text:"After mixing colors, fonts, and effects to your liking, save the combination as a custom theme: click Themes → Save Current Theme. Give it a name so it is available for future documents."},{type:"image",src:"/images/word/themes/themes_save_current.png",alt:"Save Current Theme option"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What three elements does a Word theme control?",options:["Page margins, line spacing, and tab stops","Colors, fonts, and graphic effects","Header text, footer text, and page numbers","Document language, currency format, and date format"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the practice document and apply the Office theme.","Change the theme to Ion and observe how heading colors change.","Switch the Colors palette to Blue Warm without changing the rest of the theme.","Switch the Fonts pairing to Calibri - Calibri.","Save the current combination as a custom theme named 'My Theme'."]}]},{slug:"table-of-contents",title:"Table of Contents",description:"Learn how to insert an automatic Table of Contents in Word using heading styles, and how to update it as your document changes.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/eiStMVS9ooQ",practiceFiles:[{name:"Table of Contents Practice File",url:"/practice/word/module-7/table-of-contents/word_toc_practice.docx"}],sections:[{heading:"How an Automatic TOC Works",blocks:[{type:"paragraph",text:"Word builds an automatic Table of Contents by reading the heading styles (Heading 1, Heading 2, Heading 3) applied throughout your document. Each heading becomes a TOC entry with a page number. You must apply heading styles before inserting the TOC."}]},{heading:"Applying Heading Styles",blocks:[{type:"paragraph",text:"Click inside each section title and apply the appropriate heading style from the Home tab. Use Heading 1 for main sections, Heading 2 for subsections, and Heading 3 for sub-subsections."},{type:"image",src:"/images/word/table-of-contents/toc_apply_headings.png",alt:"Applying heading styles to document sections"}]},{heading:"Inserting a Table of Contents",blocks:[{type:"paragraph",text:"Place your cursor at the location where you want the TOC (typically the beginning of the document). Go to References → Table of Contents and choose from the built-in Automatic Table styles."},{type:"image",src:"/images/word/table-of-contents/toc_references_command.png",alt:"Table of Contents button on References tab"},{type:"image",src:"/images/word/table-of-contents/toc_gallery.png",alt:"Table of Contents gallery options"},{type:"image",src:"/images/word/table-of-contents/toc_inserted_result.png",alt:"Inserted Table of Contents in the document"}]},{heading:"Navigating the Document Using the TOC",blocks:[{type:"paragraph",text:"Hold Ctrl and click any entry in the TOC to jump directly to that section. This works in both editing mode and read-only view."},{type:"image",src:"/images/word/table-of-contents/toc_ctrl_click_navigate.png",alt:"Ctrl+click navigation in the Table of Contents"}]},{heading:"Updating the Table of Contents",blocks:[{type:"paragraph",text:"After editing your document, click anywhere inside the TOC and click Update Table. Choose Update page numbers only to refresh page numbers, or Update entire table to rebuild the TOC with any new headings."},{type:"image",src:"/images/word/table-of-contents/toc_update_button.png",alt:"Update Table button above the TOC"},{type:"image",src:"/images/word/table-of-contents/toc_update_dialog.png",alt:"Update Table of Contents dialog"}]},{heading:"Removing the Table of Contents",blocks:[{type:"paragraph",text:"Go to References → Table of Contents → Remove Table of Contents to delete it from the document. This does not remove the heading styles from your text."},{type:"image",src:"/images/word/table-of-contents/toc_remove_option.png",alt:"Remove Table of Contents option"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What must you do before inserting an automatic Table of Contents?",options:["Save the document in PDF format","Apply heading styles (Heading 1, 2, 3) to your section titles","Insert page breaks before each section","Enable Track Changes so Word can find the headings"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open the practice document and apply Heading 1 to three main section titles.","Apply Heading 2 to at least two subsection titles.","Place your cursor on the first page and insert an Automatic Table 1 TOC.","Ctrl+click a TOC entry to navigate to that section.","Add a new heading in the body text, then update the entire TOC to reflect it."]}]}],level:"Advanced",estimatedMinutes:55},{moduleNumber:8,moduleSlug:"module-8",title:"Office 365 and More",emoji:"☁️",description:"Explore modern Microsoft 365 features, cloud collaboration, and advanced Word productivity tools.",lessons:[{slug:"using-word-online",title:"Using Word Online",description:"Learn how to access and use Word Online through a browser, edit documents in the cloud, and understand the differences between Word Online and the desktop app.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/oXCnZ0e-Vfo",sections:[{heading:"What Is Word Online?",blocks:[{type:"paragraph",text:"Word Online (also called Word for the web) is a free browser-based version of Microsoft Word available through Microsoft 365. It lets you create, view, and edit Word documents from any device with a browser — no software installation needed."}]},{heading:"Accessing Word Online",blocks:[{type:"paragraph",text:"Go to office.com and sign in with your Microsoft account. Click the Word icon to open Word Online. You can also open any .docx file stored in OneDrive directly in your browser."},{type:"image",src:"/images/word/word-online/wordonline_office_home.png",alt:"Microsoft 365 home page with Word icon"},{type:"image",src:"/images/word/word-online/wordonline_interface.png",alt:"Word Online editing interface in a browser"}]},{heading:"Creating a New Document",blocks:[{type:"paragraph",text:"Click New blank document on the Word Online start page to open a new, blank document. Files are saved automatically to OneDrive as you work."},{type:"image",src:"/images/word/word-online/wordonline_new_document.png",alt:"New blank document button in Word Online"}]},{heading:"Editing Mode vs. Reading View",blocks:[{type:"paragraph",text:"Word Online opens documents in Editing view by default. Click View → Reading View to switch to a clean, non-editable layout. Switch back to Editing view to make changes."},{type:"image",src:"/images/word/word-online/wordonline_reading_view.png",alt:"Reading View in Word Online"}]},{heading:"Opening in the Desktop App",blocks:[{type:"paragraph",text:"If you need features not available in Word Online, click Edit in Desktop App (or Open in Desktop App) in the toolbar. This opens the file directly in the Word desktop application and syncs changes back to OneDrive automatically."},{type:"image",src:"/images/word/word-online/wordonline_open_desktop.png",alt:"Open in Desktop App button in Word Online"}]},{heading:"Key Differences from the Desktop App",blocks:[{type:"paragraph",text:"Word Online covers the most common tasks but lacks some advanced desktop features, including macros, certain advanced layout tools, and some reference and mail merge functions. For basic writing and editing, Word Online works seamlessly."},{type:"image",src:"/images/word/word-online/wordonline_ribbon_comparison.png",alt:"Simplified Word Online ribbon compared to desktop"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is one key advantage of Word Online over the desktop app?",options:["It supports macros and advanced automation features","It can be accessed from any device with a browser without installing software","It stores files locally on your hard drive instead of the cloud","It offers more advanced layout tools than the desktop version"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Go to office.com and sign in with your Microsoft account.","Open Word Online and create a new blank document.","Type a short paragraph and add a heading using the Heading 1 style.","Switch to Reading View and then back to Editing view.","Open the document in the desktop app using the Edit in Desktop App button."]}]},{slug:"co-authoring-in-word",title:"Co-Authoring in Word",description:"Learn how to share a Word document and collaborate with others in real time using Microsoft 365 co-authoring features.",duration:"9 min",videoUrl:"https://www.youtube.com/embed/WCROca-WFiI",sections:[{heading:"What Is Co-Authoring?",blocks:[{type:"paragraph",text:"Co-authoring lets multiple people edit the same Word document at the same time. Changes from each author appear in real time without requiring anyone to check the file in or out."}]},{heading:"Sharing a Document for Co-Authoring",blocks:[{type:"paragraph",text:"The document must be saved to OneDrive or SharePoint to enable co-authoring. Click Share in the top-right corner, enter the email addresses of your collaborators, choose their permission level (can edit or can view), and click Send."},{type:"image",src:"/images/word/co-authoring/coauthor_share_button.png",alt:"Share button in the top-right corner of Word"},{type:"image",src:"/images/word/co-authoring/coauthor_share_dialog.png",alt:"Share document dialog with email entry"}]},{heading:"Seeing Other Authors in Real Time",blocks:[{type:"paragraph",text:"When another person is editing the document, their cursor and a colored flag with their name appear in the document. Each co-author is assigned a unique color so you can see exactly where they are working."},{type:"image",src:"/images/word/co-authoring/coauthor_presence_flag.png",alt:"Author presence flag showing another user's location"}]},{heading:"Viewing Who Has the File Open",blocks:[{type:"paragraph",text:"Profile pictures or initials appear in the top-right corner for everyone currently in the document. Click an icon to see the person's name and jump to where they are editing."},{type:"image",src:"/images/word/co-authoring/coauthor_author_icons.png",alt:"Co-author icons in the top right corner of Word"}]},{heading:"AutoSave and Co-Authoring",blocks:[{type:"paragraph",text:"When a file is stored on OneDrive, AutoSave turns on automatically and saves your changes every few seconds. This ensures other co-authors always see the most recent version of the document."},{type:"image",src:"/images/word/co-authoring/coauthor_autosave_toggle.png",alt:"AutoSave toggle turned on in Word"}]},{heading:"Managing Sharing Permissions",blocks:[{type:"paragraph",text:"To change or remove someone's access, click Share → Manage Access. From here you can change a collaborator's permission level to View Only or remove their access entirely."},{type:"image",src:"/images/word/co-authoring/coauthor_manage_access.png",alt:"Manage Access panel showing collaborator permissions"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"Where does a Word document need to be saved to enable co-authoring?",options:["On a USB flash drive shared between users","In a local folder on your desktop","On OneDrive or SharePoint","Emailed as an attachment to all collaborators"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Save a document to OneDrive and confirm AutoSave is on.","Click Share and invite a classmate or colleague with Edit permissions.","Ask them to open the document and make a change — observe their cursor flag.","Locate their author icon in the top-right corner and click it to jump to their position.","Open Manage Access and change their permission to View Only."]}]},{slug:"smart-lookup-and-researcher",title:"Smart Lookup & Researcher",description:"Use Word's built-in research tools to look up definitions, find background information, and insert properly cited content without leaving the document.",duration:"7 min",videoUrl:"https://www.youtube.com/embed/lX6sMD5BXLY",sections:[{heading:"What Is Smart Lookup?",blocks:[{type:"paragraph",text:"Smart Lookup uses Bing to search for definitions, Wikipedia articles, and web results for any word or phrase in your document. Results appear in a side panel so you can research without switching to a browser."}]},{heading:"Using Smart Lookup",blocks:[{type:"paragraph",text:"Right-click a word or selected phrase and choose Smart Lookup from the context menu. The Insights pane opens on the right with definitions, related web results, and images."},{type:"image",src:"/images/word/smart-lookup/smartlookup_rightclick_menu.png",alt:"Smart Lookup option in the right-click context menu"},{type:"image",src:"/images/word/smart-lookup/smartlookup_insights_pane.png",alt:"Smart Lookup Insights pane with search results"}]},{heading:"What Is Researcher?",blocks:[{type:"paragraph",text:"Researcher is a more advanced tool designed for writing essays and reports. It finds credible sources from the web, lets you explore topics in depth, and allows you to insert quotes and citations directly into your document."}]},{heading:"Opening Researcher",blocks:[{type:"paragraph",text:"Go to the References tab and click Researcher. Type a topic in the search box. Word returns a list of articles and sources. Click any result to read a summary and see available content to insert."},{type:"image",src:"/images/word/smart-lookup/researcher_references_tab.png",alt:"Researcher button on the References tab"},{type:"image",src:"/images/word/smart-lookup/researcher_search_results.png",alt:"Researcher pane with topic search results"}]},{heading:"Adding Content and Citations",blocks:[{type:"paragraph",text:"Inside a Researcher source, click Add to add a quote or passage to your document. Word automatically inserts a footnote citation. You can also click the plus (+) icon next to a heading to add it as a topic outline entry."},{type:"image",src:"/images/word/smart-lookup/researcher_add_citation.png",alt:"Add button inserting a citation from Researcher"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the main difference between Smart Lookup and Researcher?",options:["Smart Lookup is only available in Word Online; Researcher works only in the desktop app","Smart Lookup provides quick definitions and web results, while Researcher is designed for deeper research with citations","Researcher searches your local files; Smart Lookup searches the internet","There is no difference — they both do the same thing"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Right-click a word in your document and select Smart Lookup. Read the definition that appears.","Close Smart Lookup and go to References → Researcher.","Search for a topic related to your document's subject.","Open one of the source articles in the Researcher pane.","Insert a passage from the source into your document using the Add button.","Observe the automatically inserted citation."]}]},{slug:"dictation-and-voice",title:"Dictation & Voice Features",description:"Use Word's Dictation feature to type hands-free using your voice, and learn how to use voice commands to edit, format, and punctuate as you speak.",duration:"7 min",videoUrl:"https://www.youtube.com/embed/cC3IOqrHMFU",sections:[{heading:"What Is Dictation?",blocks:[{type:"paragraph",text:"Dictation converts your spoken words into typed text in Word. It works with a microphone connected to your computer and uses Microsoft's speech recognition service. Dictation is available on both the desktop app and Word Online."}]},{heading:"Starting Dictation",blocks:[{type:"paragraph",text:"Click inside your document where you want to start typing, then go to Home → Dictate. The microphone icon turns red and a listening indicator appears. Speak clearly and Word types your words in real time."},{type:"image",src:"/images/word/dictation/dictation_home_tab_button.png",alt:"Dictate button on the Home tab"},{type:"image",src:"/images/word/dictation/dictation_listening_indicator.png",alt:"Red microphone icon showing Dictation is active"}]},{heading:"Adding Punctuation by Voice",blocks:[{type:"paragraph",text:"Speak punctuation marks aloud as you dictate. For example, say 'comma', 'period', 'question mark', or 'new paragraph' and Word will insert them automatically."},{type:"image",src:"/images/word/dictation/dictation_punctuation_example.png",alt:"Example of punctuation inserted by voice"}]},{heading:"Voice Commands for Editing",blocks:[{type:"paragraph",text:"You can use voice commands to make edits while dictating. Say 'delete that' to remove the last word, 'undo that' to undo the last action, or 'select [word]' to select a specific word for formatting."},{type:"image",src:"/images/word/dictation/dictation_voice_commands.png",alt:"List of supported voice commands in Dictation"}]},{heading:"Changing Dictation Language",blocks:[{type:"paragraph",text:"Click the dropdown arrow on the Dictate button to select a different spoken language. Word supports dozens of languages and regional accents for dictation."},{type:"image",src:"/images/word/dictation/dictation_language_menu.png",alt:"Dictation language dropdown menu"}]},{heading:"Stopping Dictation",blocks:[{type:"paragraph",text:"Click the Dictate button again or press the keyboard shortcut (Alt + `) to stop dictation. The microphone icon turns back to its normal color."},{type:"image",src:"/images/word/dictation/dictation_stop.png",alt:"Dictate button deactivated after stopping"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"How do you insert a period (full stop) when using Dictation in Word?",options:["Press the period key on your keyboard","Pause for two seconds and Word adds the period automatically","Say the word 'period' while dictating","Click the Punctuation button in the Dictation toolbar"],correctIndex:2}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open a blank document and click Home → Dictate.","Dictate a two-sentence paragraph, speaking punctuation marks aloud.","Use the voice command 'new paragraph' to start a new paragraph.","Say 'undo that' to undo your last dictated word.","Stop dictation and review the text for accuracy.","Correct any misrecognized words by typing normally."]}]},{slug:"accessibility-features",title:"Accessibility Features",description:"Learn how to use Word's Accessibility Checker to identify and fix issues that make documents difficult to use for people with disabilities.",duration:"8 min",videoUrl:"https://www.youtube.com/embed/aRvMDhDNB4o",sections:[{heading:"Why Accessibility Matters",blocks:[{type:"paragraph",text:"An accessible document can be read and navigated by people who use screen readers, keyboard-only navigation, or other assistive technologies. Word includes tools that help you catch common accessibility issues before sharing your document."}]},{heading:"Running the Accessibility Checker",blocks:[{type:"paragraph",text:"Go to Review → Check Accessibility. The Accessibility pane opens on the right, listing Errors, Warnings, and Tips. Click any issue to jump directly to the problem in the document."},{type:"image",src:"/images/word/accessibility/accessibility_checker_command.png",alt:"Check Accessibility button on the Review tab"},{type:"image",src:"/images/word/accessibility/accessibility_checker_pane.png",alt:"Accessibility Checker pane with errors and warnings"}]},{heading:"Adding Alt Text to Images",blocks:[{type:"paragraph",text:"Alt text describes an image for screen readers. Right-click an image and choose Edit Alt Text. Type a brief, descriptive sentence that explains what the image shows. Avoid vague descriptions like 'image 1'."},{type:"image",src:"/images/word/accessibility/accessibility_alttext_rightclick.png",alt:"Edit Alt Text option in right-click menu"},{type:"image",src:"/images/word/accessibility/accessibility_alttext_pane.png",alt:"Alt Text pane with description field"}]},{heading:"Using Meaningful Heading Structure",blocks:[{type:"paragraph",text:"Screen readers use heading styles to help users navigate long documents. Use Heading 1 for main sections, Heading 2 for subsections, and so on — never skip levels (e.g., going from Heading 1 directly to Heading 3)."},{type:"image",src:"/images/word/accessibility/accessibility_heading_structure.png",alt:"Correct heading hierarchy example"}]},{heading:"Making Tables Accessible",blocks:[{type:"paragraph",text:"Data tables should have a header row that labels each column. Select your table, go to Table Design → check Header Row, and confirm the first row is formatted as a header so screen readers can announce column names."},{type:"image",src:"/images/word/accessibility/accessibility_table_header_row.png",alt:"Header Row checkbox in Table Design tab"}]},{heading:"Using Meaningful Hyperlink Text",blocks:[{type:"paragraph",text:"Avoid hyperlinks that only show the raw URL or phrases like 'click here'. Instead, use descriptive link text such as 'Visit the Microsoft 365 support page' so screen reader users understand the link's destination."},{type:"image",src:"/images/word/accessibility/accessibility_link_text_example.png",alt:"Example of descriptive vs. vague hyperlink text"}]},{heading:"Knowledge Check",blocks:[{type:"knowledge-check",question:"What is the purpose of alt text on images in a Word document?",options:["It appears as a caption below the image when printed","It describes the image for screen readers so visually impaired users understand the content","It compresses the image file size for faster sharing","It locks the image so it cannot be moved or resized"],correctIndex:1}]}],challenge:[{type:"paragraph",text:"Complete the following tasks:"},{type:"list",ordered:!0,items:["Open a document that contains at least one image and a table.","Run Check Accessibility from the Review tab.","Fix any missing alt text by right-clicking each image and entering a description.","Check that your heading structure does not skip levels.","Review any hyperlinks in the document and update generic 'click here' text with descriptive link labels.","Re-run the Accessibility Checker and confirm the errors are resolved."]}]}],level:"Advanced",estimatedMinutes:45}]}}};